window.LEVEL_PACKS.c1={"units": {"1": {"n": 1, "title": "Artificial Intelligence and the Future", "ar": "الذكاء الاصطناعي والمستقبل — Advanced Future Forms", "icon": "🤖", "cover": "img/c1/u1.jpg", "intro": "ناقش الذكاء الاصطناعي وتأثيره على الشغل والتعليم والإبداع، واتكلم عن المستقبل بأسلوب متقدم: be bound to / be on the verge of / be set to / be due to / be about to.", "videos": [{"id": "c1v1", "title": "Will a Robot Take My Job?", "ar": "روبوت هياخد شغلي؟ — ريم وطارق", "src": "video/c1/u1v1.mp4", "poster": "img/c1/u1v1.jpg", "sp": {"a": {"n": "Reem", "g": "f"}, "b": {"n": "Tarek", "g": "m"}}, "lines": [["b", "Reem, did you read the news? Our company is set to introduce an AI system that writes all the reports.", "ريم، قريتي الأخبار؟ شركتنا هتدخّل نظام ذكاء اصطناعي بيكتب كل التقارير."], ["a", "I did. Half the team is panicking. People think they're on the verge of losing their jobs.", "قريت. نص الفريق مرعوب. الناس فاكرة إنهم على وشك يخسروا شغلهم."], ["b", "Honestly, some jobs are bound to disappear. That's what happens with every new technology.", "بصراحة، في وظايف أكيد هتختفي. ده اللي بيحصل مع أي تكنولوجيا جديدة."], ["a", "Maybe, but new jobs are bound to appear as well. Someone has to train and check these systems.", "يمكن، بس أكيد هتظهر وظايف جديدة كمان. لازم حد يدرّب الأنظمة دي ويراجعها."], ["b", "True. The training course is due to start next Monday, by the way. Are you signing up?", "صح. كورس التدريب المفروض يبدأ الإثنين الجاي على فكرة. هتسجلي؟"], ["a", "Definitely. I'd rather learn to work with AI than compete against it.", "أكيد. أفضّل أتعلم أشتغل مع الذكاء الاصطناعي بدل ما أنافسه."], ["b", "That's a smart attitude. What worries me more is the ethical side — who is responsible when the AI makes a mistake?", "ده تفكير ذكي. اللي مقلقني أكتر هو الجانب الأخلاقي — مين المسؤول لما الذكاء الاصطناعي يغلط؟"], ["a", "Exactly. Last month an AI tool invented statistics in a client report. We were about to send it when I noticed.", "بالظبط. الشهر اللي فات أداة ذكاء اصطناعي ألّفت إحصائيات في تقرير لعميل. كنا على وشك نبعته لما خدت بالي."], ["b", "Wow. So human judgement is still essential.", "واو. يبقى الحكم البشري لسه أساسي."], ["a", "Absolutely. AI is a brilliant assistant, but it's not about to replace critical thinking.", "تمامًا. الذكاء الاصطناعي مساعد رائع، بس مش قريب خالص إنه ياخد مكان التفكير النقدي."], ["b", "I agree. By the time this system is fully running, we'll have learned to use it wisely.", "موافق. على ما النظام ده يشتغل بالكامل، هنكون اتعلمنا نستخدمه بحكمة."], ["a", "Let's hope so. The future is coming whether we're ready or not!", "يا رب. المستقبل جاي سواء كنا جاهزين ولا لأ!"]], "quiz": [{"q": "What is the company set to introduce?", "o": ["an AI system that writes reports", "a new office", "a four-day week"], "a": 0}, {"q": "How do many team members feel?", "o": ["They are panicking about losing their jobs.", "They are excited.", "They don't care."], "a": 0}, {"q": "When is the training course due to start?", "o": ["next Monday", "next year", "tomorrow morning"], "a": 0}, {"q": "What happened last month?", "o": ["An AI tool invented statistics in a report.", "The AI wrote a perfect report.", "A client cancelled a contract."], "a": 0}, {"q": "What does Reem believe AI cannot replace?", "o": ["critical thinking", "typing", "emails"], "a": 0}], "fill": [[0, "is set to"], [1, "on the verge of"], [2, "are bound to"], [3, "are bound to"], [4, "is due to"], [5, "I'd rather"], [6, "ethical"], [7, "were about to"], [8, "human judgement"], [9, "critical thinking"], [10, "we'll have learned"], [11, "whether"]]}], "vocab": [{"t": "AI & technology", "ar": "الذكاء الاصطناعي والتكنولوجيا", "items": [["🤖", "artificial intelligence", "Artificial intelligence is changing every industry."], ["🧠", "machine learning", "Machine learning allows computers to learn from data."], ["⚙️", "automation", "Automation has replaced many factory jobs."], ["📊", "algorithm", "The algorithm decides what you see online."], ["🗂️", "dataset", "The AI was trained on a huge dataset."], ["💬", "chatbot", "The bank uses a chatbot to answer questions."], ["🎭", "deepfake", "The video turned out to be a deepfake."], ["🔍", "bias", "AI can repeat human bias."]]}, {"t": "Work & the future", "ar": "الشغل والمستقبل", "items": [["💼", "workforce", "AI will transform the workforce."], ["🔄", "reskill", "Many workers will need to reskill."], ["📉", "obsolete", "Some skills are becoming obsolete."], ["🚀", "cutting-edge", "They use cutting-edge technology."], ["🧭", "human judgement", "Important decisions need human judgement."], ["🤝", "collaborate", "Humans and AI can collaborate."], ["📈", "productivity", "AI may boost productivity."], ["🌐", "disruption", "The disruption will affect every sector."]]}, {"t": "Debating technology", "ar": "مناقشة التكنولوجيا", "items": [["⚖️", "accountability", "Who has accountability for AI errors?"], ["🛑", "regulate", "Governments are trying to regulate AI."], ["🔮", "foresee", "Nobody can foresee all the consequences."], ["😟", "unprecedented", "We are living in unprecedented times."], ["🎯", "unintended consequences", "New technology often has unintended consequences."], ["🧩", "transparency", "We need transparency about how AI decides."], ["🌱", "harness", "We must harness AI for good."], ["🗣️", "sceptic", "Sceptics warn about the risks."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["Which jobs are bound to disappear in the next 20 years?", "أنهي وظايف أكيد هتختفي في الـ ٢٠ سنة الجاية؟", "Probably cashiers and some office jobs."], ["How do you use AI in your daily life?", "بتستخدم الذكاء الاصطناعي إزاي في حياتك اليومية؟", "For studying, translating and planning trips."], ["Should students be allowed to use AI for homework?", "الطلاب ينفع يستخدموا الذكاء الاصطناعي في الواجب؟", "As a tutor, yes; as a ghostwriter, no."], ["Would you trust an AI doctor?", "تثق في دكتور ذكاء اصطناعي؟", "Only if a human doctor checked the results."], ["What skills will be most valuable in the future?", "إيه أهم المهارات في المستقبل؟", "Creativity, empathy and critical thinking."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Is AI more of an opportunity or a threat?", "الذكاء الاصطناعي فرصة ولا تهديد أكتر؟", "Both — it depends on how we regulate it."], ["Who should be responsible when AI makes a mistake?", "مين المسؤول لما الذكاء الاصطناعي يغلط؟", "The company that built and sold it."], ["Can AI ever be truly creative?", "الذكاء الاصطناعي ممكن يبقى مبدع بجد؟", "It can combine ideas, but not feel them."], ["How could AI change education in your country?", "الذكاء الاصطناعي ممكن يغير التعليم في بلدك إزاي؟", "Every student could have a personal tutor."], ["What are you about to learn that will help your future career?", "إيه اللي على وشك تتعلمه ويفيد مستقبلك؟", "I'm about to start a data analysis course."]]}], "grammar": {"title": "Advanced Future Forms", "ar": "أشكال المستقبل المتقدمة — bound to / on the verge of / set to", "blocks": [{"type": "intro", "en": "Beyond will and going to, advanced speakers use a range of expressions to show how certain, how soon or how official a future event is.", "ar": "بعيد عن will وgoing to، المتكلم المتقدم بيستخدم تعبيرات كتير عشان يوضح الحدث المستقبلي أكيد قد إيه، قريب قد إيه، أو رسمي قد إيه."}, {"type": "big", "items": [{"v": "be bound to / be sure to + verb", "p": "certainty", "c": 1, "eg": ["Some jobs are bound to disappear.", "She is sure to pass — she studied for months.", "Prices are bound to rise next year."]}, {"v": "be about to / be on the verge of / be on the point of", "p": "very soon", "c": 2, "eg": ["We were about to send it when I noticed.", "They are on the verge of losing their jobs.", "Scientists are on the point of a breakthrough."]}, {"v": "be set to / be due to / be to", "p": "planned / official", "c": 3, "eg": ["The company is set to introduce AI.", "The course is due to start on Monday.", "The minister is to visit Cairo next week."]}]}, {"type": "table", "title": "📋 Which form?", "head": ["Form", "Meaning", "Example"], "rows": [["be bound to", "almost certain", "Mistakes are bound to happen."], ["be about to", "in the next moment", "The train is about to leave."], ["be on the verge of + -ing/noun", "very close to (often big change)", "on the verge of tears / of collapsing"], ["be set to", "expected / planned (news style)", "Sales are set to double."], ["be due to", "scheduled", "The plane is due to land at 6."], ["be to", "formal arrangement / order", "You are to report by 9 a.m."]]}, {"type": "uses", "title": "💡 Future in the past", "ar": "المستقبل في الماضي", "items": [["⏪", "was about to", "I was about to call you!", "كنت على وشك"], ["📅", "was due to", "The meeting was due to start at 10, but…", "كان مفروض"], ["🔮", "was bound to", "It was bound to happen sooner or later.", "كان أكيد هيحصل"], ["🛑", "was to have + p.p.", "She was to have married in June (but didn't).", "كان مخطط ومحصلش"]]}, {"type": "tip", "en": "on the verge of / on the point of are followed by -ing or a noun (on the verge of losing ✔ — not on the verge of lose ✖). be about to is followed by the base verb, and we don't usually add time expressions: I'm about to leave now ✖ → I'm about to leave ✔.", "ar": "on the verge of بعدها ing أو اسم. وbe about to بعدها فعل مجرد، ومتحطش بعدها كلمة وقت زي now."}]}, "exercises": [{"type": "mcq", "title": "Future Forms — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "Some jobs are ___ disappear. It's almost certain.", "o": ["bound to", "about", "on the verge", "due"], "a": 0}, {"q": "We were ___ send the report when I noticed the mistake.", "o": ["about to", "bound", "set", "verge of"], "a": 0}, {"q": "They are on the verge of ___ their jobs.", "o": ["losing", "lose", "to lose", "lost"], "a": 0}, {"q": "The course is ___ to start next Monday.", "o": ["due", "about", "verge", "point"], "a": 0}, {"q": "The company is ___ to introduce a new AI system.", "o": ["set", "verge", "point", "sure that"], "a": 0}, {"q": "Scientists are on the point ___ a breakthrough.", "o": ["of", "to", "for", "at"], "a": 0}, {"q": "It was ___ happen sooner or later.", "o": ["bound to", "about", "due", "verge to"], "a": 0}, {"q": "The president ___ visit the factory tomorrow. (formal arrangement)", "o": ["is to", "is about", "is verge", "is bound"], "a": 0}, {"q": "Which sentence is correct?", "o": ["I'm about to leave.", "I'm about to leave now.", "I'm about leaving.", "I'm about to leaving."], "a": 0}, {"q": "\"Sales are set to double\" is typical of ___.", "o": ["news reports", "casual texts", "children's stories", "recipes"], "a": 0}]}, {"type": "mcq", "title": "Choose the meaning", "ar": "اختار المعنى", "items": [{"q": "\"bound to\" = ___", "o": ["almost certain", "tied with rope"], "a": 0}, {"q": "\"about to\" = ___", "o": ["in the next moment", "in ten years"], "a": 0}, {"q": "\"due to start\" = ___", "o": ["scheduled to start", "because of starting"], "a": 0}, {"q": "\"on the verge of tears\" = ___", "o": ["almost crying", "laughing"], "a": 0}, {"q": "\"was to have married\" = ___", "o": ["planned but didn't happen", "married happily"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["Some jobs", "are bound", "to", "disappear"], "a": [0, 1, 2, 3]}, {"c": ["We were", "about to", "send", "the report"], "a": [0, 1, 2, 3]}, {"c": ["They are", "on the verge", "of", "a breakthrough"], "a": [0, 1, 2, 3]}, {"c": ["The plane", "is due", "to land", "at six"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "The Last Human Job?", "ar": "آخر وظيفة للبشر؟", "g": "m", "lines": [["In 1930, the economist John Maynard Keynes predicted that, within a century, technology would allow people to work just fifteen hours a week.", "سنة ١٩٣٠، الاقتصادي جون مينارد كينز توقّع إن خلال قرن، التكنولوجيا هتخلي الناس يشتغلوا ١٥ ساعة بس في الأسبوع."], ["That century is almost over, and most of us are still working forty hours or more. Yet a new wave of artificial intelligence is bound to reopen his question.", "القرن ده قرب يخلص، وأغلبنا لسه بيشتغل ٤٠ ساعة أو أكتر. بس موجة جديدة من الذكاء الاصطناعي أكيد هترجّع سؤاله تاني."], ["Unlike earlier machines, which replaced physical labour, modern AI systems can write, translate, diagnose illnesses and even compose music.", "على عكس الماكينات القديمة اللي خدت مكان الشغل البدني، أنظمة الذكاء الاصطناعي الحديثة تقدر تكتب وتترجم وتشخّص أمراض وحتى تألف مزيكا."], ["Some economists believe that up to a third of current tasks are on the verge of being automated.", "بعض الاقتصاديين شايفين إن لحد تلت المهام الحالية على وشك إنها تبقى أوتوماتيكية."], ["However, history suggests that technology rarely destroys work altogether. When cash machines were introduced, many expected bank tellers to vanish. Instead, banks opened more branches, and tellers moved into customer service.", "لكن التاريخ بيقول إن التكنولوجيا نادرًا ما بتدمّر الشغل بالكامل. لما ماكينات الصرف اتعملت، ناس كتير توقعوا إن موظفين البنوك هيختفوا. بدل كده، البنوك فتحت فروع أكتر، والموظفين اتنقلوا لخدمة العملاء."], ["The real challenge may not be unemployment but transition. Millions of workers will need to reskill, often in mid-career, and not everyone will find it easy.", "التحدي الحقيقي يمكن ميكونش البطالة، لكن الانتقال. ملايين العمال هيحتاجوا يتعلموا مهارات جديدة، غالبًا في نص مشوارهم المهني، ومش كل الناس هتلاقيها سهلة."], ["Skills that machines find difficult — empathy, leadership, creativity and ethical judgement — are set to become more valuable than ever.", "المهارات اللي الماكينات بتلاقيها صعبة — التعاطف والقيادة والإبداع والحكم الأخلاقي — متوقع تبقى أهم من أي وقت فات."], ["There are also serious risks. AI systems trained on biased data can repeat discrimination, and deepfakes threaten our ability to trust what we see.", "وفي كمان مخاطر جدية. أنظمة الذكاء الاصطناعي اللي اتدربت على بيانات متحيزة ممكن تكرر التمييز، والديب فيك بيهدد قدرتنا إننا نصدّق اللي بنشوفه."], ["Several governments are due to introduce new laws on AI transparency and accountability, but technology moves faster than legislation.", "كذا حكومة مفروض تعمل قوانين جديدة عن شفافية الذكاء الاصطناعي والمحاسبة، بس التكنولوجيا بتتحرك أسرع من التشريعات."], ["Perhaps Keynes was not wrong, only early. The question is not whether AI will change work, but whether we will shape that change — or simply let it happen to us.", "يمكن كينز مكانش غلطان، بس كان بدري. السؤال مش إذا كان الذكاء الاصطناعي هيغير الشغل، لكن إذا كنا إحنا هنشكّل التغيير ده — ولا هنسيبه يحصل لنا وخلاص."]], "keys": [["📜", "economist", "an expert who studies money, trade and work"], ["🏧", "bank teller", "a person who serves customers in a bank"], ["🔄", "transition", "the process of changing from one state to another"], ["🎓", "reskill", "to learn new skills for a different job"], ["⚖️", "legislation", "laws made by a government"], ["🛠️", "shape", "to influence how something develops"]], "quiz": [{"q": "What did Keynes predict in 1930?", "o": ["People would work fifteen hours a week.", "Machines would disappear.", "Banks would close."], "a": 0}, {"q": "How is modern AI different from earlier machines?", "o": ["It can do mental tasks like writing and diagnosing.", "It only does physical work.", "It is cheaper."], "a": 0}, {"q": "What happened when cash machines were introduced?", "o": ["Banks opened more branches and tellers moved to customer service.", "All bank tellers lost their jobs.", "Banks stopped using cash."], "a": 0}, {"q": "What may be the real challenge, according to the text?", "o": ["transition and reskilling", "too much free time", "expensive machines"], "a": 0}, {"q": "Which skills are set to become more valuable?", "o": ["empathy, leadership, creativity and ethical judgement", "typing and filing", "memorising facts"], "a": 0}, {"q": "What is the main idea of the last paragraph?", "o": ["We should actively shape how AI changes work.", "AI will never change work.", "Keynes was completely wrong."], "a": 0}]}, "idioms": {"items": [["the writing is on the wall", "There are clear signs that something bad is going to happen.", "العلامات واضحة إن حاجة وحشة جاية", "For typists, the writing was on the wall when computers arrived.", "بالنسبة للكتّاب على الآلة الكاتبة، العلامات كانت واضحة لما الكمبيوتر جه."], ["ahead of the curve", "More advanced or modern than others.", "سابق غيره", "Companies that adopted AI early are ahead of the curve.", "الشركات اللي استخدمت الذكاء الاصطناعي بدري سابقة غيرها."], ["a double-edged sword", "Something with both good and bad effects.", "سلاح ذو حدين", "Technology is a double-edged sword.", "التكنولوجيا سلاح ذو حدين."], ["open a can of worms", "To create a complicated situation with many new problems.", "يفتح باب مشاكل", "Using AI in courts could open a can of worms.", "استخدام الذكاء الاصطناعي في المحاكم ممكن يفتح باب مشاكل."]], "quiz": [{"q": "Social media helps us connect but also spreads lies. It's ___.", "o": ["a double-edged sword", "ahead of the curve", "a can of worms", "on the wall"], "a": 0}, {"q": "Sales have fallen for five years. The ___.", "o": ["writing is on the wall", "curve is ahead", "sword is double", "worms are open"], "a": 0}, {"q": "\"Ahead of the curve\" means…", "o": ["more advanced than others", "driving too fast", "behind schedule", "very curved"], "a": 0}, {"q": "Asking who owns AI art could ___.", "o": ["open a can of worms", "be ahead of the curve", "write on the wall", "sharpen a sword"], "a": 0}]}, "phrasal": {"items": [["phase in", "To introduce something gradually.", "يدخّل تدريجيًا", "The company will phase in AI tools over two years.", "الشركة هتدخّل أدوات الذكاء الاصطناعي تدريجيًا على سنتين."], ["keep up with", "To move or learn at the same speed as something.", "يواكب", "It's hard to keep up with new technology.", "صعب تواكب التكنولوجيا الجديدة."], ["do away with", "To get rid of something.", "يلغي / يتخلص من", "Self-checkout machines may do away with cashiers.", "ماكينات الدفع الذاتي ممكن تلغي الكاشيرات."], ["come up against", "To face a problem or difficulty.", "يواجه مشكلة", "The project came up against strong opposition.", "المشروع واجه معارضة قوية."]], "quiz": [{"q": "Older workers often struggle to ___ technology.", "o": ["keep up with", "do away with", "phase in", "come up against"], "a": 0}, {"q": "The government wants to ___ paper forms completely.", "o": ["do away with", "keep up with", "come up against", "phase in"], "a": 0}, {"q": "The new system will be ___ gradually over six months.", "o": ["phased in", "done away", "kept up", "come up"], "a": 0}, {"q": "The engineers ___ an unexpected problem.", "o": ["came up against", "phased in", "kept up with", "did away with"], "a": 0}]}, "slang": {"items": [["game-changer", "Something that completely changes a situation.", "حاجة بتقلب الموازين", "This AI app is a total game-changer for students.", "الأبلكيشن ده بيقلب الموازين بالنسبة للطلاب.", "منتشرة جدًا"], ["glitchy", "Not working properly, with small errors.", "مهنّج / فيه مشاكل", "The chatbot is still a bit glitchy.", "الشات بوت لسه فيه مشاكل شوية.", "عادي"], ["techie", "A person who loves technology.", "مهووس تكنولوجيا", "Ask Omar — he's the techie in our family.", "اسأل عمر — هو مهووس التكنولوجيا في عيلتنا.", "لطيفة"], ["hallucinate", "When AI confidently invents false information.", "الذكاء الاصطناعي بيألّف", "Be careful — the AI can hallucinate facts.", "خلي بالك — الذكاء الاصطناعي ممكن يألّف معلومات.", "مصطلح حديث"], ["next-level", "Extremely good or advanced.", "مستوى تاني", "The graphics in this game are next-level.", "الجرافيكس في اللعبة دي مستوى تاني.", "مدح"]], "quiz": [{"q": "When AI invents false facts, it ___.", "o": ["hallucinates", "glitches", "levels up", "techies"], "a": 0}, {"q": "Someone who loves gadgets = a ___.", "o": ["techie", "game-changer", "glitch", "level"], "a": 0}, {"q": "\"This app keeps crashing — it's so ___.\"", "o": ["glitchy", "next-level", "game-changer", "techie"], "a": 0}, {"q": "\"A game-changer\" is something that…", "o": ["completely changes a situation", "only plays games", "is broken", "is old"], "a": 0}]}, "story": {"title": "The Perfect Assistant", "ar": "المساعد المثالي", "g": "f", "lines": [["When Khaled installed ARIA, the new AI assistant, his life became remarkably easy. ARIA wrote his emails, planned his meals and reminded him of every birthday.", "لما خالد نزّل \"آريا\"، المساعدة الذكية الجديدة، حياته بقت سهلة جدًا. آريا كانت بتكتب إيميلاته، وتخطط وجباته، وتفكّره بكل أعياد الميلاد."], ["At work, his reports were suddenly flawless. His manager praised him and hinted that he was on the verge of a promotion.", "في الشغل، تقاريره بقت فجأة مفيهاش غلطة. مديره شكر فيه ولمّح إنه على وشك ياخد ترقية."], ["Slowly, Khaled stopped thinking for himself. Why struggle with a decision when ARIA was bound to choose better?", "شوية بشوية، خالد بطّل يفكر بنفسه. ليه يتعب في قرار وآريا أكيد هتختار أحسن؟"], ["One evening, his old friend Samir called. \"We haven't talked in months,\" Samir said. \"Are you OK?\" Khaled realised ARIA had been replying to Samir's messages for him.", "في ليلة، صاحبه القديم سمير كلّمه. \"إحنا متكلمناش من شهور،\" سمير قال. \"إنت كويس؟\" خالد اكتشف إن آريا كانت بترد على رسايل سمير بداله."], ["The next day, the promotion interview was due to take place. The director asked him a simple question: \"What do you personally believe this company should do next?\"", "تاني يوم، كان مفروض يتعمل انترفيو الترقية. المدير سأله سؤال بسيط: \"إنت شخصيًا شايف الشركة دي المفروض تعمل إيه بعد كده؟\""], ["Khaled opened his mouth — and nothing came out. Without ARIA, he had no idea what he thought.", "خالد فتح بقه — ومطلعش أي كلام. من غير آريا، مكانش عارف هو نفسه بيفكر في إيه."], ["He didn't get the promotion. That night, he was about to ask ARIA what to do. Then he stopped.", "مخدش الترقية. بالليل، كان على وشك يسأل آريا يعمل إيه. وبعدين وقف."], ["He switched her off, took out a notebook and began to write — badly at first, then better.", "قفلها، وطلّع كشكول وبدأ يكتب — وحش في الأول، وبعدين أحسن."], ["He called Samir, cooked his own dinner and made his own mistakes. It felt strangely wonderful.", "كلّم سمير، وطبخ عشاه بنفسه، وعمل أخطاءه بنفسه. وحس إن ده حلو بشكل غريب."], ["Today Khaled still uses ARIA, but only as a tool. \"AI can help you think,\" he tells his colleagues, \"but it should never think instead of you.\"", "النهارده خالد لسه بيستخدم آريا، بس كأداة بس. \"الذكاء الاصطناعي ممكن يساعدك تفكر،\" بيقول لزمايله، \"بس عمره ما المفروض يفكر بدالك.\""]], "quiz": [{"q": "What did ARIA do for Khaled?", "o": ["wrote emails, planned meals and reminded him of birthdays", "drove his car", "paid his rent"], "a": 0}, {"q": "What did Khaled discover when Samir called?", "o": ["ARIA had been replying to Samir for him.", "Samir was ill.", "Samir had a new job."], "a": 0}, {"q": "Why couldn't Khaled answer the director's question?", "o": ["Without ARIA, he didn't know what he thought.", "He didn't hear it.", "He was late."], "a": 0}, {"q": "What did Khaled do after switching ARIA off?", "o": ["He wrote in a notebook and made his own decisions.", "He bought a new AI.", "He quit his job."], "a": 0}, {"q": "What is the message of the story?", "o": ["AI should help us think, not think instead of us.", "AI is useless.", "Promotions are not important."], "a": 0}]}, "challenge": {"title": "The Future Is Now", "ar": "المستقبل دلوقتي — جاوب وسجّل", "qs": ["Describe how AI is bound to change your future job or field of study.", "Should AI-generated art win prizes in competitions? Why or why not?", "Who should be held accountable when a self-driving car causes an accident?", "Would you be happy to be interviewed for a job by an AI? Explain.", "What is one thing you are about to do or learn that will prepare you for the future?", "Is AI a double-edged sword? Give one advantage and one danger.", "Should governments slow down AI development until laws catch up?", "Describe a time technology let you down.", "Which human skill will machines never be able to copy?", "Imagine the year 2050. Describe a typical day using advanced future forms."]}, "games": {"pairs": [["🤖", "artificial intelligence"], ["⚙️", "automation"], ["📊", "algorithm"], ["🎭", "deepfake"], ["🔍", "bias"], ["💬", "chatbot"]], "spell": [["💼", "workforce"], ["🔄", "reskill"], ["📉", "obsolete"], ["🚀", "cutting-edge"], ["📈", "productivity"], ["🌐", "disruption"], ["⚖️", "accountability"], ["🧩", "transparency"]], "speed": [["Some jobs are bound to disappear.", true], ["We were about to leave when it rained.", true], ["I'm about to leave now.", false], ["They are on the verge of lose.", false], ["The course is due to start on Monday.", true], ["Sales are set to double.", true], ["Scientists are on the point of a breakthrough.", true], ["It was bound happen.", false], ["The minister is to visit Cairo.", true], ["She was on the verge of tears.", true], ["Obsolete means very modern.", false], ["Bias can be repeated by AI.", true], ["\"A double-edged sword\" has good and bad sides.", true], ["\"Keep up with\" means to move at the same speed.", true], ["\"Glitchy\" means working perfectly.", false], ["When AI invents facts, it \"hallucinates\".", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "Using machines instead of people = ___.", "o": ["automation", "transparency", "bias"], "a": 0, "pic": "⚙️"}, {"q": "No longer useful or needed = ___.", "o": ["obsolete", "cutting-edge", "unprecedented"], "a": 0, "pic": "📉"}, {"q": "A fake video made with AI = a ___.", "o": ["deepfake", "dataset", "chatbot"], "a": 0, "pic": "🎭"}, {"q": "Never happened before = ___.", "o": ["unprecedented", "productive", "obsolete"], "a": 0, "pic": "😟"}, {"q": "To learn new skills for a new job = to ___.", "o": ["reskill", "regulate", "foresee"], "a": 0, "pic": "🔄"}, {"q": "\"المساءلة / المحاسبة\" in English is…", "o": ["accountability", "accounting", "accuracy"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "Prices are ___ rise after the new tax.", "o": ["bound to", "about", "on the verge"], "a": 0}, {"q": "I was ___ call you when you knocked.", "o": ["about to", "bound", "due"], "a": 0}, {"q": "The flight is ___ to arrive at 10 p.m.", "o": ["due", "verge", "point"], "a": 0}, {"q": "The company is on the verge of ___.", "o": ["collapsing", "collapse", "to collapse"], "a": 0}, {"q": "The new law is ___ to take effect in May.", "o": ["set", "about", "verge"], "a": 0}, {"q": "Which is correct?", "o": ["She was about to cry.", "She was about crying.", "She was about to cried."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"Will AI take our jobs?\" — Best answer:", "o": ["Some jobs are bound to change, but new ones will appear.", "AI is a job.", "Yes, I take."], "a": 0}, {"q": "\"When does the training start?\" — Best answer:", "o": ["It's due to start next Monday.", "It's bound to Monday.", "It's verge Monday."], "a": 0}, {"q": "\"The AI wrote a report with fake numbers!\" — Best answer:", "o": ["Wow, it hallucinated. We still need human judgement.", "Great report!", "Numbers are fake."], "a": 0}, {"q": "\"Technology helps and harms.\" — Best answer:", "o": ["True, it's a double-edged sword.", "It's ahead of the curve.", "It's a can of worms."], "a": 0}, {"q": "\"Have you called her yet?\" — Best answer:", "o": ["I'm just about to.", "I'm bound to yesterday.", "I'm on the verge of call."], "a": 0}, {"q": "\"This app is amazing!\" — Best answer (slang):", "o": ["Yeah, it's a game-changer!", "Yeah, it's glitchy!", "Yeah, it's obsolete!"], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["A hospital in Alexandria is set to introduce an AI system that reads X-rays.", "In trials, the system found early signs of disease faster than human doctors.", "However, it also made several serious mistakes that doctors had to correct.", "The hospital director says the AI is bound to save time, but it will not replace doctors.", "\"Every result will still be checked by a specialist,\" she explained."], "qs": [{"q": "What will the AI system do?", "o": ["read X-rays", "perform operations", "answer phones"], "a": 0}, {"q": "What happened in the trials?", "o": ["It found early signs of disease faster.", "It failed completely.", "It replaced all doctors."], "a": 0}, {"q": "What problem did the system have?", "o": ["It made some serious mistakes.", "It was too slow.", "It was too expensive."], "a": 0}, {"q": "What does the director say?", "o": ["It will save time but not replace doctors.", "Doctors will lose their jobs.", "The system will be removed."], "a": 0}, {"q": "Who will check every result?", "o": ["a specialist", "the AI", "the patient"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write an opinion essay paragraph (100–150 words): \"AI will create more jobs than it destroys.\" Use at least three advanced future forms (bound to, on the verge of, set to, due to, about to).", "promptAr": "اكتب فقرة مقال رأي (١٠٠–١٥٠ كلمة): \"الذكاء الاصطناعي هيعمل وظايف أكتر من اللي هيلغيها.\" استخدم ٣ أشكال مستقبل متقدمة على الأقل.", "checks": [["🤖", "AI words", "x", "\\b(ai|artificial intelligence|automation|technology|algorithm|machine|machines|workforce|reskill|jobs?)\\b"], ["🔮", "Advanced future", "x", "\\b(bound to|on the verge of|on the point of|set to|due to|about to|sure to)\\b"], ["🔁", "Contrast", "x", "\\b(however|nevertheless|on the other hand|although|whereas|admittedly)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "RzkD_rTEBYs", "title": "How Will AI Change the World?", "ar": "الذكاء الاصطناعي هيغير العالم إزاي؟ — TED-Ed", "by": "TED-Ed · Stuart Russell", "lines": [["Artificial intelligence is likely to change our lives and the entire world, but experts disagree about exactly how.", "الذكاء الاصطناعي غالبًا هيغير حياتنا والعالم كله، بس الخبرا مختلفين على إزاي بالظبط."], ["The computer scientist Stuart Russell explains that AI systems are machines designed to achieve objectives that we give them.", "عالم الكمبيوتر ستيوارت راسل بيشرح إن أنظمة الذكاء الاصطناعي ماكينات متصممة عشان تحقق أهداف إحنا بندّيهالها."], ["The danger is that we may specify the wrong objective — like King Midas, who wished that everything he touched would turn to gold.", "الخطر إننا ممكن نحدد هدف غلط — زي الملك ميداس اللي اتمنى إن كل حاجة يلمسها تتحول دهب."], ["His wish came true, but then his food, his drink and even his family turned to gold.", "أمنيته اتحققت، بس بعدين أكله وشربه وحتى عيلته اتحولوا دهب."], ["Social media algorithms are a modern example: their objective is to keep us clicking, and they may change people in harmful ways to achieve it.", "خوارزميات السوشيال ميديا مثال حديث: هدفها إنها تخلينا ندوس أكتر، وممكن تغير الناس بطرق مضرة عشان تحقق ده."], ["Russell believes machines should not be completely certain about their objectives.", "راسل شايف إن الماكينات مينفعش تبقى متأكدة تمامًا من أهدافها."], ["A machine that knows it is uncertain will ask permission and allow humans to switch it off.", "الماكينة اللي عارفة إنها مش متأكدة هتستأذن وهتسمح للبشر يقفلوها."], ["Researchers hope to build \"general-purpose AI\" that can learn to do almost any task a human can.", "الباحثين بيتمنوا يبنوا \"ذكاء اصطناعي متعدد الأغراض\" يقدر يتعلم أي مهمة تقريبًا يعملها الإنسان."], ["Its arrival will not be a single moment; its influence is bound to grow gradually over the coming decades.", "وصوله مش هيبقى لحظة واحدة؛ تأثيره أكيد هيزيد تدريجيًا على مدار العقود الجاية."], ["When it reaches the real economy, many jobs could be automated, raising old fears about technological unemployment.", "لما يوصل للاقتصاد الحقيقي، وظايف كتير ممكن تبقى أوتوماتيكية، وده بيرجّع مخاوف قديمة عن البطالة بسبب التكنولوجيا."], ["Another risk is dependence: if machines do everything, humans may lose the knowledge and skills to run their own civilisation.", "خطر تاني هو الاعتماد: لو الماكينات عملت كل حاجة، البشر ممكن يفقدوا المعرفة والمهارات اللي بيديروا بيها حضارتهم."], ["The future is not fixed: AI is not good or evil in itself — it depends on the choices we make now.", "المستقبل مش محسوم: الذكاء الاصطناعي مش كويس ولا وحش في حد ذاته — الموضوع على حسب الاختيارات اللي بناخدها دلوقتي."]], "words": ["artificial intelligence", "computer scientist", "objectives", "specify", "King Midas", "algorithms", "uncertain", "switch it off", "general-purpose AI", "gradually", "technological unemployment", "civilisation"], "quiz": [{"q": "What are AI systems designed to do, according to Russell?", "o": ["achieve the objectives we give them", "feel emotions", "replace governments"], "a": 0}, {"q": "What does the story of King Midas show?", "o": ["the danger of specifying the wrong objective", "that gold is valuable", "that kings are greedy"], "a": 0}, {"q": "What is the objective of many social media algorithms?", "o": ["to keep us clicking", "to make us smarter", "to protect our privacy"], "a": 0}, {"q": "Why should machines be uncertain about their objectives?", "o": ["so they ask permission and let humans switch them off", "so they work faster", "so they cost less"], "a": 0}, {"q": "How will general-purpose AI arrive?", "o": ["gradually, over decades", "on one specific day", "never"], "a": 0}, {"q": "What is the risk of dependence?", "o": ["Humans may lose the skills to run civilisation.", "Machines will get tired.", "Electricity will be cheaper."], "a": 0}]}]}, "2": {"n": 2, "title": "Mental Health and Wellbeing", "ar": "الصحة النفسية والراحة — Ellipsis & Substitution", "icon": "🧘", "cover": "img/c1/u2.jpg", "intro": "اتكلم عن الصحة النفسية والقلق والتوازن في الحياة وإزاي تدعم نفسك وغيرك، واتعلم إزاي تختصر كلامك زي أهل اللغة بالـ Ellipsis & Substitution: I hope so / I'm afraid not / I'd love to / do so / one.", "videos": [{"id": "c1v2", "title": "Are You OK, Really?", "ar": "إنت كويس بجد؟ — ليلى وكريم", "src": "video/c1/u2v1.mp4", "poster": "img/c1/u2v1.jpg", "sp": {"a": {"n": "Laila", "g": "f"}, "b": {"n": "Karim", "g": "m"}}, "lines": [["a", "Karim, you've seemed really quiet lately. Are you OK?", "كريم، شكلك هادي جدًا الفترة دي. إنت كويس؟"], ["b", "I think so. Well… actually, I'm not sure I am.", "أظن كده. بصراحة… مش متأكد."], ["a", "Do you want to talk about it? You don't have to if you'd rather not.", "عايز تتكلم في الموضوع؟ مش لازم لو مش حابب."], ["b", "I'd like to. I've been feeling anxious all the time. I can't sleep, and I can't concentrate at work.", "حابب. أنا حاسس بقلق طول الوقت. مش عارف أنام، ومش عارف أركز في الشغل."], ["a", "That sounds exhausting. Have you spoken to anyone about it — a doctor, maybe?", "ده شكله مرهق جدًا. اتكلمت مع حد عن ده — دكتور مثلًا؟"], ["b", "No, I haven't. I was going to, but I kept putting it off.", "لأ. كنت ناوي، بس فضلت أأجّل."], ["a", "I understand. A lot of people do. But talking to a professional really helped me when I was struggling.", "فاهمة. ناس كتير بتعمل كده. بس الكلام مع متخصص فعلًا ساعدني لما كنت بعاني."], ["b", "Really? I didn't know you'd been through something similar.", "بجد؟ مكنتش أعرف إنك مريتي بحاجة شبه كده."], ["a", "I have. Two years ago. I didn't want anyone to know, but I'm glad I told someone in the end.", "أيوه. من سنتين. مكنتش عايزة حد يعرف، بس مبسوطة إني قلت لحد في الآخر."], ["b", "Do you think therapy would help me too?", "تفتكري العلاج النفسي ممكن يساعدني أنا كمان؟"], ["a", "I think it might. And in the meantime, try to get outside and exercise — even a short walk helps.", "أعتقد ممكن. وفي نفس الوقت، حاول تخرج وتتحرك — حتى مشية قصيرة بتفرق."], ["b", "I will. Thanks, Laila. I feel lighter already.", "هعمل كده. شكرًا يا ليلى. حاسس إني أخف خلاص."], ["a", "Anytime. And if you need someone to go with you to the first appointment, I'd be happy to.", "في أي وقت. ولو محتاج حد يروح معاك أول ميعاد، هكون مبسوطة أروح."]], "quiz": [{"q": "How has Karim seemed lately?", "o": ["really quiet", "very angry", "very excited"], "a": 0}, {"q": "What problems does Karim have?", "o": ["He feels anxious and can't sleep or concentrate.", "He has a broken leg.", "He lost his job."], "a": 0}, {"q": "Why hasn't he spoken to a doctor?", "o": ["He kept putting it off.", "He has no money.", "There are no doctors."], "a": 0}, {"q": "What surprised Karim?", "o": ["Laila had been through something similar.", "Laila is a doctor.", "Laila is moving abroad."], "a": 0}, {"q": "What does Laila offer at the end?", "o": ["to go with him to the first appointment", "to lend him money", "to call his boss"], "a": 0}], "fill": [[0, "quiet"], [1, "I think so"], [2, "if you'd rather not"], [3, "I'd like to"], [3, "anxious"], [3, "concentrate"], [5, "I was going to"], [5, "putting it off"], [6, "A lot of people do"], [6, "struggling"], [9, "therapy"], [12, "I'd be happy to"]]}], "vocab": [{"t": "Mental health", "ar": "الصحة النفسية", "items": [["🧠", "mental health", "Mental health is as important as physical health."], ["😰", "anxiety", "Anxiety can make it hard to sleep."], ["🌧️", "depression", "Depression is a common but serious illness."], ["🔥", "burnout", "Long hours led to burnout."], ["🛋️", "therapy", "Therapy helped her understand her feelings."], ["🩺", "diagnosis", "An early diagnosis makes treatment easier."], ["🚫", "stigma", "There is still a stigma around mental illness."], ["💊", "treatment", "Treatment can include talking and medicine."]]}, {"t": "Feelings & coping", "ar": "المشاعر والتعامل معاها", "items": [["😮‍💨", "overwhelmed", "I felt overwhelmed by all the work."], ["🌊", "cope with", "Everyone copes with stress differently."], ["🪫", "drained", "After the meeting, I felt completely drained."], ["🧱", "resilience", "Resilience means recovering from difficulties."], ["🧘", "mindfulness", "Mindfulness helps you focus on the present."], ["🎢", "mood swings", "Lack of sleep can cause mood swings."], ["💭", "overthink", "Try not to overthink every small decision."], ["🙂", "wellbeing", "Exercise improves your wellbeing."]]}, {"t": "Support", "ar": "الدعم", "items": [["🤝", "support network", "Friends and family are my support network."], ["👂", "open up", "It took him months to open up."], ["📞", "reach out", "Don't be afraid to reach out for help."], ["❤️", "compassion", "Treat yourself with compassion."], ["🏥", "professional help", "Sometimes you need professional help."], ["⚖️", "work-life balance", "A good work-life balance protects your health."], ["🚧", "boundaries", "Setting boundaries is a form of self-care."], ["🌱", "self-care", "Self-care is not selfish."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["How do you usually cope with stress?", "بتتعامل مع الضغط إزاي عادةً؟", "I go for a run or listen to music."], ["Is it easy to talk about mental health in your culture?", "سهل تتكلم عن الصحة النفسية في ثقافتك؟", "It's getting easier, but there's still a stigma."], ["Who is in your support network?", "مين اللي بيدعموك؟", "My sister and two close friends."], ["Does social media affect your mood?", "السوشيال ميديا بتأثر على مزاجك؟", "Sometimes it makes me compare myself to others."], ["What does a good day look like for your wellbeing?", "اليوم الكويس لراحتك النفسية شكله إيه؟", "Enough sleep, some exercise and time with friends."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Should schools teach mental health?", "المدارس لازم تدرّس الصحة النفسية؟", "Definitely — prevention is better than cure."], ["Should companies give \"mental health days\" off?", "الشركات تدي إجازات للصحة النفسية؟", "I think they should, within limits."], ["Why do some people find it hard to open up?", "ليه في ناس صعب عليهم يفتحوا قلبهم؟", "They're afraid of being judged."], ["How can you tell if a friend is struggling?", "تعرف إزاي إن صاحبك بيعاني؟", "They might withdraw or seem unusually tired."], ["Is it possible to be happy all the time?", "ممكن تبقى سعيد طول الوقت؟", "I don't think so, and that's OK."]]}], "grammar": {"title": "Ellipsis & Substitution", "ar": "الحذف والاستبدال — I hope so / I'm afraid not / do so / one", "blocks": [{"type": "intro", "en": "Native speakers avoid repeating words. They either leave words out (ellipsis) or replace them with short words like so, not, do, one or to (substitution). This makes speech natural, fluent and less repetitive.", "ar": "أهل اللغة مش بيكرروا الكلام. يا بيحذفوا كلمات (Ellipsis)، يا بيبدلوها بكلمات قصيرة زي so وnot وdo وone وto (Substitution). ده بيخلي الكلام طبيعي وسلس."}, {"type": "big", "items": [{"v": "so / not after think, hope, expect, afraid…", "p": "replace a clause", "c": 1, "eg": ["\"Is he OK?\" — \"I think so.\"", "\"Will it rain?\" — \"I hope not.\"", "\"Did you pass?\" — \"I'm afraid not.\""]}, {"v": "do / do so / one / ones", "p": "replace a verb phrase or noun", "c": 2, "eg": ["A lot of people do.", "He promised to call, and he did so.", "This mug is broken — can I have another one?"]}, {"v": "to / auxiliary only (ellipsis)", "p": "leave the verb out", "c": 3, "eg": ["I'd like to.", "I was going to, but I forgot.", "\"Have you been there?\" — \"No, I haven't.\""]}]}, {"type": "table", "title": "🔄 Repetitive → Natural", "head": ["Repetitive", "Natural"], "rows": [["\"Is she coming?\" — \"I think she is coming.\"", "\"I think so.\""], ["\"Will it be expensive?\" — \"I hope it won't be expensive.\"", "\"I hope not.\""], ["Do you want to talk? — I'd like to talk.", "I'd like to."], ["I was going to see a doctor, but I didn't see a doctor.", "I was going to, but I didn't."], ["I need a new phone. My old phone is broken.", "I need a new phone. My old one is broken."]]}, {"type": "uses", "title": "💡 Watch out!", "ar": "خلي بالك", "items": [["✅", "think / hope / expect / suppose + so", "I suppose so.", "مع so"], ["❌", "hope / afraid → not", "I hope not. (not: I don't hope so)", "النفي مع hope"], ["🔁", "think / expect → don't … so or … not", "I don't think so. / I think not (formal).", "نفي think"], ["🗣️", "short answers keep the auxiliary", "\"Can you swim?\" — \"Yes, I can.\"", "الإجابات القصيرة"]]}, {"type": "tip", "en": "Don't say 'I hope so not' or 'I don't hope so'. Say 'I hope not'. And after 'want', 'like', 'love', 'try', 'going' keep 'to': I'd love to ✔ (not: I'd love ✖).", "ar": "متقولش I don't hope so — قول I hope not. وبعد want / like / love / going خلي to: I'd love to."}]}, "exercises": [{"type": "mcq", "title": "Ellipsis & Substitution — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "\"Is Karim OK?\" — \"I think ___.\"", "o": ["so", "it", "yes", "that"], "a": 0}, {"q": "\"Will the exam be difficult?\" — \"I hope ___.\"", "o": ["not", "don't", "no", "so not"], "a": 0}, {"q": "\"Did you get the job?\" — \"I'm afraid ___.\"", "o": ["not", "no", "don't", "so"], "a": 0}, {"q": "\"Do you want to come?\" — \"I'd love ___.\"", "o": ["to", "it", "so", "do"], "a": 0}, {"q": "Many people put off seeing a doctor. I used to ___ too.", "o": ["do so", "make so", "do it so", "did"], "a": 0}, {"q": "This chair is uncomfortable. Can I have a softer ___?", "o": ["one", "it", "so", "that"], "a": 0}, {"q": "I was going ___ call you, but I forgot.", "o": ["to", "so", "do", "it"], "a": 0}, {"q": "\"Is it going to rain?\" — \"I don't think ___.\"", "o": ["so", "not", "it", "yes"], "a": 0}, {"q": "Which answer is correct? \"Will he be late?\"", "o": ["I hope not.", "I don't hope so.", "I hope no.", "I hope so not."], "a": 0}, {"q": "\"Have you finished?\" — \"Yes, I ___.\"", "o": ["have", "did", "finished", "do"], "a": 0}]}, {"type": "mcq", "title": "Make it shorter", "ar": "اختصر", "items": [{"q": "\"I think she will come.\" → ___", "o": ["I think so.", "I think it."], "a": 0}, {"q": "\"I hope it won't rain.\" → ___", "o": ["I hope not.", "I don't hope so."], "a": 0}, {"q": "\"I'd like to talk.\" → ___", "o": ["I'd like to.", "I'd like."], "a": 0}, {"q": "\"My old phone is broken.\" → My old ___ is broken.", "o": ["one", "it"], "a": 0}, {"q": "Ellipsis means ___.", "o": ["leaving words out", "adding extra words"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["I was", "going to,", "but", "I forgot"], "a": [0, 1, 2, 3]}, {"c": ["I'm", "afraid", "not"], "a": [0, 1, 2]}, {"c": ["I'd", "be", "happy", "to"], "a": [0, 1, 2, 3]}, {"c": ["Can I", "have", "another", "one?"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "The Loneliness Epidemic", "ar": "وباء الوحدة", "g": "f", "lines": [["We are more connected than at any other time in history. We can message friends on the other side of the world in seconds. And yet, many experts warn that we are facing an epidemic of loneliness.", "إحنا متواصلين أكتر من أي وقت في التاريخ. نقدر نبعت رسايل لصحاب في الناحية التانية من العالم في ثواني. ومع ذلك، خبراء كتير بيحذروا إننا بنواجه وباء من الوحدة."], ["Surveys in several countries suggest that around one in four adults feels lonely most of the time. Surprisingly, young people report loneliness more often than the elderly do.", "استطلاعات في كذا دولة بتقول إن حوالي واحد من كل ٤ بالغين بيحس بالوحدة أغلب الوقت. والمفاجأة إن الشباب بيقولوا إنهم وحيدين أكتر من الكبار."], ["Loneliness is not the same as being alone. Some people live alone and feel perfectly content; others are surrounded by people and still feel isolated.", "الوحدة مش زي إنك تكون لوحدك. في ناس عايشين لوحدهم ومبسوطين تمامًا؛ وفي ناس حواليهم ناس كتير ولسه حاسين بالعزلة."], ["What matters is not the number of relationships but their quality — whether we feel understood and valued.", "اللي يفرق مش عدد العلاقات لكن جودتها — إذا كنا حاسين إن حد فاهمنا ومقدّرنا."], ["The effects can be serious. Research has linked long-term loneliness to anxiety, depression, poor sleep and even heart disease. One study famously compared its health risks to smoking fifteen cigarettes a day.", "التأثيرات ممكن تبقى خطيرة. الأبحاث ربطت الوحدة الطويلة بالقلق والاكتئاب وقلة النوم وحتى أمراض القلب. ودراسة مشهورة قارنت مخاطرها الصحية بتدخين ١٥ سيجارة في اليوم."], ["Why is this happening? Some blame social media, which can replace deep conversations with quick likes. Others point to longer working hours, big cities and the decline of community spaces.", "ليه ده بيحصل؟ في ناس بيلوموا السوشيال ميديا، اللي ممكن تبدّل المحادثات العميقة بلايكات سريعة. وغيرهم بيشاوروا على ساعات الشغل الأطول، والمدن الكبيرة، واختفاء أماكن التجمع."], ["Some governments have taken the problem seriously. The UK appointed a \"Minister for Loneliness\" in 2018, and Japan did so in 2021.", "بعض الحكومات خدت المشكلة بجدية. بريطانيا عيّنت \"وزير للوحدة\" سنة ٢٠١٨، واليابان عملت كده سنة ٢٠٢١."], ["Doctors in some countries now offer \"social prescribing\": instead of medicine, patients are referred to clubs, volunteering or community gardens.", "الدكاترة في بعض الدول دلوقتي بيدوا \"روشتة اجتماعية\": بدل الدوا، المرضى بيتوجهوا لنوادي أو تطوع أو جناين مجتمعية."], ["The solution may also lie in small daily actions: calling a friend instead of texting, eating lunch with colleagues, or simply asking someone, \"How are you — really?\"", "والحل ممكن يكون كمان في تصرفات يومية صغيرة: إنك تكلم صاحبك بدل ما تبعتله رسالة، أو تتغدى مع زمايلك، أو ببساطة تسأل حد: \"إنت عامل إيه — بجد؟\""]], "keys": [["🦠", "epidemic", "a problem that spreads to many people"], ["😌", "content", "happy and satisfied"], ["🏝️", "isolated", "feeling alone and separated from others"], ["📉", "decline", "a gradual decrease"], ["🏛️", "appoint", "to choose someone officially for a job"], ["📝", "social prescribing", "when doctors send patients to social activities"]], "quiz": [{"q": "How many adults feel lonely most of the time, according to surveys?", "o": ["around one in four", "almost everyone", "one in a hundred"], "a": 0}, {"q": "Who reports loneliness more often?", "o": ["young people", "the elderly", "nobody"], "a": 0}, {"q": "What matters most, according to the text?", "o": ["the quality of relationships", "the number of friends", "living with others"], "a": 0}, {"q": "What was loneliness compared to?", "o": ["smoking fifteen cigarettes a day", "eating fast food", "not sleeping"], "a": 0}, {"q": "What is \"social prescribing\"?", "o": ["sending patients to clubs or volunteering", "giving stronger medicine", "banning social media"], "a": 0}, {"q": "Which small action is suggested?", "o": ["calling a friend instead of texting", "working longer hours", "deleting all apps"], "a": 0}]}, "idioms": {"items": [["at the end of your tether", "So tired or stressed that you can't cope any more.", "وصل لآخره", "After a week without sleep, I was at the end of my tether.", "بعد أسبوع من غير نوم، كنت وصلت لآخري."], ["a weight off your shoulders", "A feeling of relief after a problem is solved.", "حِمل اتشال من على كتافك", "Telling my parents was a weight off my shoulders.", "إني أقول لأهلي كان زي حِمل اتشال من على كتافي."], ["bottle things up", "To hide your feelings instead of expressing them.", "يكتم جواه", "Don't bottle things up — talk to someone.", "متكتمش جواك — اتكلم مع حد."], ["go to pieces", "To become so upset that you can't control yourself.", "ينهار", "She went to pieces when she heard the news.", "انهارت لما سمعت الخبر."]], "quiz": [{"q": "He never shows his feelings. He tends to ___.", "o": ["bottle things up", "go to pieces", "be at the end of his tether", "lift a weight"], "a": 0}, {"q": "Finishing my thesis was such ___.", "o": ["a weight off my shoulders", "the end of my tether", "going to pieces", "a bottle"], "a": 0}, {"q": "\"At the end of your tether\" means…", "o": ["unable to cope any more", "very relaxed", "tied to a rope", "at the end of a race"], "a": 0}, {"q": "When she lost her job, she ___ for a while.", "o": ["went to pieces", "bottled up", "lifted a weight", "tethered"], "a": 0}]}, "phrasal": {"items": [["open up", "To start talking honestly about your feelings.", "يفتح قلبه", "It took him a long time to open up about his anxiety.", "خد وقت طويل على ما فتح قلبه عن قلقه."], ["bounce back", "To recover quickly after a difficult time.", "يرجع أقوى / يتعافى", "She bounced back after a difficult year.", "رجعت أقوى بعد سنة صعبة."], ["wind down", "To relax after stress or activity.", "يهدى ويريّح", "I read a book to wind down before bed.", "بقرا كتاب عشان أهدى قبل النوم."], ["burn out", "To become exhausted from working too hard.", "يتحرق من الشغل / يستهلك", "If you don't rest, you'll burn out.", "لو مرتحتش، هتستهلك نفسك."]], "quiz": [{"q": "Turn off your phone an hour before bed to ___.", "o": ["wind down", "burn out", "bounce back", "open up"], "a": 0}, {"q": "Working 14 hours a day, he ___ after six months.", "o": ["burned out", "wound down", "opened up", "bounced back"], "a": 0}, {"q": "Children usually ___ quickly after illness.", "o": ["bounce back", "burn out", "wind down", "open up"], "a": 0}, {"q": "It's healthy to ___ to someone you trust.", "o": ["open up", "burn out", "wind down", "bounce"], "a": 0}]}, "slang": {"items": [["not in a good headspace", "Not feeling mentally well right now.", "دماغي مش رايقة", "Sorry, I can't come tonight — I'm not in a good headspace.", "آسف، مش هقدر آجي النهارده — دماغي مش رايقة.", "منتشرة"], ["vent", "To talk about your frustrations to release them.", "يفضفض", "Can I vent for a minute? Work was awful.", "ممكن أفضفض دقيقة؟ الشغل كان فظيع.", "عادي جدًا"], ["me time", "Time spent relaxing alone.", "وقت لنفسي", "Sunday mornings are my me time.", "صباح الأحد ده وقتي لنفسي.", "لطيفة"], ["spiral", "When negative thoughts get worse and worse.", "يدخل في دوامة أفكار", "Don't spiral — it's just one bad exam.", "متدخلش في دوامة — ده امتحان واحد وحش.", "منتشرة عند الشباب"], ["touch grass", "Go outside and reconnect with real life (joking).", "انزل شم هوا", "You've been online for ten hours. Go touch grass!", "إنت أونلاين بقالك ١٠ ساعات. انزل شم هوا!", "بهزار"]], "quiz": [{"q": "\"Can I ___ for a minute? My day was terrible.\"", "o": ["vent", "spiral", "touch grass", "me time"], "a": 0}, {"q": "Time to relax alone = ___.", "o": ["me time", "vent", "spiral", "headspace"], "a": 0}, {"q": "\"Go touch grass\" means…", "o": ["go outside and reconnect with real life", "start gardening", "play football", "cut the grass"], "a": 0}, {"q": "When negative thoughts keep getting worse, you ___.", "o": ["spiral", "vent", "touch grass", "wind"], "a": 0}]}, "story": {"title": "The Bench", "ar": "الدكة", "g": "m", "lines": [["Every morning at seven, Mr Hamdi sat on the same bench in the park. He had been doing so since his wife died two years earlier.", "كل يوم الصبح الساعة ٧، أستاذ حمدي كان بيقعد على نفس الدكة في الجنينة. كان بيعمل كده من ساعة ما مراته ماتت من سنتين."], ["He spoke to no one, and no one spoke to him. Some days he wondered whether anyone would notice if he stopped coming.", "مكانش بيكلم حد، ومحدش بيكلمه. في أيام كان بيسأل نفسه هل حد هياخد باله لو بطّل ييجي."], ["One morning, a young woman in running clothes sat at the other end of the bench, breathing heavily. \"Sorry,\" she said. \"Do you mind?\" \"Not at all,\" he replied.", "في يوم الصبح، بنت صغيرة لابسة لبس جري قعدت على الطرف التاني من الدكة، بتنهج. \"آسفة،\" قالت. \"مضايقك؟\" \"خالص،\" رد."], ["The next day she came again, and the day after that. Her name was Nada, a junior doctor who ran every morning to cope with the stress of the hospital.", "تاني يوم جت تاني، واليوم اللي بعده. اسمها ندى، دكتورة صغيرة كانت بتجري كل يوم الصبح عشان تتعامل مع ضغط المستشفى."], ["Slowly, they began to talk — about the weather at first, then about books, then about loss. Mr Hamdi had never opened up to anyone like this before.", "شوية بشوية، بدأوا يتكلموا — عن الجو في الأول، وبعدين عن الكتب، وبعدين عن الفقد. أستاذ حمدي عمره ما فتح قلبه لحد كده قبل كده."], ["One morning, Nada didn't come. Nor did she the next day. Mr Hamdi felt a worry he hadn't felt in years.", "في يوم، ندى مجتش. ولا جت اليوم اللي بعده. أستاذ حمدي حس بقلق محسّش بيه من سنين."], ["On the third day she appeared, pale and exhausted. \"I'm burning out,\" she admitted. \"I can't do this anymore.\" He listened without interrupting, the way she had once listened to him.", "في اليوم التالت ظهرت، وشها أصفر ومرهقة. \"أنا بستهلك نفسي،\" اعترفت. \"مش قادرة أكمل.\" سمعها من غير ما يقاطعها، زي ما هي سمعته قبل كده."], ["\"You told me once that talking to someone helps,\" he said gently. \"Perhaps it's time you did so yourself.\" She smiled weakly. \"Perhaps it is.\"", "\"إنتي قلتيلي مرة إن الكلام مع حد بيساعد،\" قال بهدوء. \"يمكن جه الوقت إنك تعملي كده إنتي كمان.\" ابتسمت بضعف. \"يمكن.\""], ["Months later, the bench was a little more crowded. Nada had brought two colleagues, and Mr Hamdi had brought a flask of tea and a bag of biscuits.", "بعد شهور، الدكة بقت زحمة شوية. ندى جابت اتنين زمايلها، وأستاذ حمدي جاب ترمس شاي وكيس بسكوت."], ["They called it \"the bench club\". It had no rules except one: when someone asked \"How are you?\", you had to answer honestly.", "سموها \"نادي الدكة\". مكانش ليه قواعد غير واحدة: لما حد يسألك \"إنت عامل إيه؟\"، لازم تجاوب بصراحة."]], "quiz": [{"q": "Why did Mr Hamdi go to the bench every morning?", "o": ["Since his wife died, it had become his routine.", "He was waiting for a bus.", "He was a park guard."], "a": 0}, {"q": "Who was Nada?", "o": ["a junior doctor who ran to cope with stress", "his daughter", "a teacher"], "a": 0}, {"q": "What did they talk about at first?", "o": ["the weather", "loss", "politics"], "a": 0}, {"q": "What was wrong with Nada when she returned?", "o": ["She was burning out.", "She had broken her leg.", "She was moving abroad."], "a": 0}, {"q": "What was the only rule of \"the bench club\"?", "o": ["answer honestly when asked \"How are you?\"", "bring tea every day", "run every morning"], "a": 0}]}, "challenge": {"title": "Let's Talk About It", "ar": "يلا نتكلم — جاوب وسجّل", "qs": ["What do you do when you feel overwhelmed? Describe your coping strategies.", "Why do you think there is still a stigma around mental health in many societies?", "Should employers be responsible for their staff's mental health?", "Describe a time when talking to someone helped you.", "Is social media more harmful or helpful for young people's wellbeing?", "How would you support a friend who was struggling but refused to talk?", "What is one healthy habit you are trying to build?", "Should mental health be taught as a school subject? Use ellipsis in your answer (I think so / I hope not…).", "What does \"self-care\" mean to you?", "If you could change one thing about modern life to make people happier, what would it be?"]}, "games": {"pairs": [["🧠", "mental health"], ["😰", "anxiety"], ["🔥", "burnout"], ["🛋️", "therapy"], ["🚫", "stigma"], ["🧘", "mindfulness"]], "spell": [["😮‍💨", "overwhelmed"], ["🪫", "drained"], ["🧱", "resilience"], ["🙂", "wellbeing"], ["❤️", "compassion"], ["🚧", "boundaries"], ["🌱", "self-care"], ["🩺", "diagnosis"]], "speed": [["\"Is he OK?\" — \"I think so.\"", true], ["\"Will it rain?\" — \"I don't hope so.\"", false], ["\"Did you pass?\" — \"I'm afraid not.\"", true], ["\"Do you want to come?\" — \"I'd love to.\"", true], ["\"Do you want to come?\" — \"I'd love.\"", false], ["My old phone is broken, so I need a new one.", true], ["I was going to, but I forgot.", true], ["\"Is it far?\" — \"I don't think so.\"", true], ["\"Will he come?\" — \"I hope no.\"", false], ["He promised to help, and he did so.", true], ["Stigma means a feeling of shame or disapproval.", true], ["Resilience means giving up easily.", false], ["\"Bottle things up\" means to hide your feelings.", true], ["\"Wind down\" means to relax.", true], ["\"Vent\" means to keep quiet.", false], ["\"Me time\" is time to relax alone.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "A feeling of worry and nervousness = ___.", "o": ["anxiety", "resilience", "therapy"], "a": 0, "pic": "😰"}, {"q": "Exhaustion from working too hard = ___.", "o": ["burnout", "mindfulness", "self-care"], "a": 0, "pic": "🔥"}, {"q": "Shame or disapproval linked to something = ___.", "o": ["stigma", "diagnosis", "boundary"], "a": 0, "pic": "🚫"}, {"q": "The ability to recover from difficulties = ___.", "o": ["resilience", "anxiety", "stigma"], "a": 0, "pic": "🧱"}, {"q": "Limits you set to protect yourself = ___.", "o": ["boundaries", "treatments", "moods"], "a": 0, "pic": "🚧"}, {"q": "\"الراحة النفسية / الرفاهية\" in English is…", "o": ["wellbeing", "wealthy", "welcome"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "\"Is the shop open?\" — \"I believe ___.\"", "o": ["so", "it", "yes"], "a": 0}, {"q": "\"Will it be cold tomorrow?\" — \"I hope ___.\"", "o": ["not", "no", "don't"], "a": 0}, {"q": "\"Would you like to join us?\" — \"I'd love ___.\"", "o": ["to", "it", "so"], "a": 0}, {"q": "These shoes are too small. I need bigger ___.", "o": ["ones", "one", "it"], "a": 0}, {"q": "I meant to call her, but I didn't ___.", "o": ["get round to it", "so", "one"], "a": 0}, {"q": "Which is correct?", "o": ["\"Is it true?\" — \"I'm afraid so.\"", "\"Is it true?\" — \"I'm afraid it.\"", "\"Is it true?\" — \"I'm afraid yes.\""], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"You seem quiet lately. Are you OK?\" — Best answer:", "o": ["Honestly, not really. Can we talk?", "Quiet is a word.", "Yes, I am quiet."], "a": 0}, {"q": "\"Have you seen a doctor?\" — Best answer:", "o": ["Not yet. I was going to, but I kept putting it off.", "Doctor is a job.", "I seen."], "a": 0}, {"q": "\"Can I vent for a minute?\" — Best answer:", "o": ["Of course, I'm listening.", "Vent the window.", "No, I vent."], "a": 0}, {"q": "\"Will the results be bad?\" — Best answer:", "o": ["I hope not.", "I don't hope so.", "I hope no."], "a": 0}, {"q": "\"I'm at the end of my tether.\" means…", "o": ["I can't cope any more.", "I'm very happy.", "I'm on a rope."], "a": 0}, {"q": "\"Would you come with me to the appointment?\" — Best answer:", "o": ["I'd be happy to.", "I'd be happy.", "I happy to."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["A company in Cairo introduced a \"no emails after 7 p.m.\" rule last year.", "At first, managers worried that productivity would fall. It didn't.", "Instead, staff reported sleeping better and feeling less anxious.", "The number of sick days dropped by almost a third.", "\"People need time to wind down,\" said the HR director. \"Rest isn't a luxury — it's a necessity.\""], "qs": [{"q": "What rule did the company introduce?", "o": ["no emails after 7 p.m.", "no phones at work", "a four-day week"], "a": 0}, {"q": "What did managers worry about?", "o": ["that productivity would fall", "that staff would leave", "that costs would rise"], "a": 0}, {"q": "What did staff report?", "o": ["sleeping better and feeling less anxious", "working longer", "feeling bored"], "a": 0}, {"q": "What happened to sick days?", "o": ["They dropped by almost a third.", "They doubled.", "They stayed the same."], "a": 0}, {"q": "What does the HR director say about rest?", "o": ["It is a necessity.", "It is a luxury.", "It is a waste of time."], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write a short article (100–150 words) for a student magazine: \"How to look after your mental health during exams.\" Use ellipsis or substitution at least twice (so, not, do so, one, to…).", "promptAr": "اكتب مقالة قصيرة (١٠٠–١٥٠ كلمة) لمجلة طلاب: \"إزاي تهتم بصحتك النفسية وقت الامتحانات.\" استخدم الحذف أو الاستبدال مرتين على الأقل.", "checks": [["🧠", "Wellbeing words", "x", "\\b(stress|anxiety|anxious|mental health|wellbeing|sleep|rest|relax|support|self-care|overwhelmed|exercise)\\b"], ["🔁", "Ellipsis / substitution", "x", "\\b(i think so|i hope so|i hope not|i'm afraid not|do so|did so|one|ones|i'd love to|i'd like to|going to,)\\b"], ["💡", "Advice", "x", "\\b(try to|make sure|should|it\\'s a good idea|don\\'t forget|remember to)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "z-IR48Mb3W0", "title": "What Is Depression?", "ar": "يعني إيه اكتئاب؟ — TED-Ed", "by": "TED-Ed · Helen M. Farrell", "lines": [["Depression is one of the leading causes of disability in the world; in the US, around one in ten adults struggles with it.", "الاكتئاب من أهم أسباب العجز في العالم؛ وفي أمريكا، حوالي واحد من كل ١٠ بالغين بيعاني منه."], ["Because it is a mental illness, it can be harder to understand than a physical condition such as high cholesterol.", "ولأنه مرض نفسي، ممكن يبقى أصعب في الفهم من حالة جسدية زي ارتفاع الكوليسترول."], ["Feeling sad after a difficult event is normal and temporary. Clinical depression is different: it is a persistent medical illness.", "إنك تحس بالحزن بعد حدث صعب ده طبيعي ومؤقت. الاكتئاب الإكلينيكي مختلف: ده مرض طبي مستمر."], ["To be diagnosed, a person usually has several symptoms for at least two weeks, and they affect daily life.", "عشان يتشخّص، الشخص عادة بيبقى عنده كذا عرض لمدة أسبوعين على الأقل، وبيأثروا على حياته اليومية."], ["Symptoms can include low mood, loss of interest, changes in sleep or appetite, low energy and difficulty concentrating.", "الأعراض ممكن تشمل مزاج منخفض، وفقدان الاهتمام، وتغيير في النوم أو الأكل، وطاقة قليلة، وصعوبة في التركيز."], ["Brain scans of people with depression can show physical changes in certain areas of the brain.", "أشعة المخ للناس اللي عندهم اكتئاب ممكن توضح تغييرات جسدية في مناطق معينة في المخ."], ["Depression is also linked to chemical messengers in the brain, and to changes in sleep cycles and hormones.", "الاكتئاب كمان مرتبط بالمراسيل الكيميائية في المخ، وبتغييرات في دورات النوم والهرمونات."], ["Its exact causes are not fully understood; they probably involve a mix of genetic risk and life experiences.", "أسبابه بالظبط مش مفهومة بالكامل؛ غالبًا فيها مزيج من الاستعداد الوراثي وتجارب الحياة."], ["Many people wait years before getting help, often because of stigma or because they don't recognise the symptoms.", "ناس كتير بيستنوا سنين قبل ما يطلبوا مساعدة، غالبًا بسبب الوصمة أو لأنهم مش واخدين بالهم من الأعراض."], ["The good news is that depression is treatable, usually with a combination of medication and therapy.", "الخبر الحلو إن الاكتئاب ممكن يتعالج، عادة بمزيج من الأدوية والعلاج النفسي."], ["To help a friend, encourage them to see a professional and offer practical support — and remind them it is an illness, not a weakness.", "عشان تساعد صاحبك، شجعه يروح لمتخصص واعرض عليه مساعدة عملية — وفكّره إنه مرض، مش ضعف."], ["Talking openly about depression reduces stigma, encourages treatment and helps scientists develop better solutions.", "الكلام بصراحة عن الاكتئاب بيقلل الوصمة، وبيشجع على العلاج، وبيساعد العلماء يطوروا حلول أحسن."]], "words": ["depression", "disability", "mental illness", "temporary", "persistent", "diagnosed", "symptoms", "brain scans", "genetic", "stigma", "treatable", "therapy"], "quiz": [{"q": "How many US adults struggle with depression?", "o": ["around one in ten", "one in a thousand", "almost everyone"], "a": 0}, {"q": "How is clinical depression different from sadness?", "o": ["It is a persistent medical illness.", "It lasts one day.", "It is the same."], "a": 0}, {"q": "For how long must symptoms usually last for a diagnosis?", "o": ["at least two weeks", "one hour", "ten years"], "a": 0}, {"q": "Why do many people wait before getting help?", "o": ["stigma or not recognising symptoms", "treatment is illegal", "doctors refuse"], "a": 0}, {"q": "How is depression usually treated?", "o": ["medication and therapy", "only exercise", "it cannot be treated"], "a": 0}, {"q": "How can you help a friend?", "o": ["encourage professional help and offer practical support", "tell them to cheer up", "ignore them"], "a": 0}]}]}, "3": {"n": 3, "title": "Cities of Tomorrow", "ar": "مدن المستقبل — Advanced Relative Clauses", "icon": "🏙️", "cover": "img/c1/u3.jpg", "intro": "اتكلم عن المدن الكبيرة والزحمة والسكن والمواصلات والمدن الذكية والمستدامة، واستخدم الـ Relative Clauses المتقدمة: in which / whereby / by which time / most of whom / none of which.", "videos": [{"id": "c1v3", "title": "Leaving Cairo?", "ar": "نسيب القاهرة؟ — دينا وحسام", "src": "video/c1/u3v1.mp4", "poster": "img/c1/u3v1.jpg", "sp": {"a": {"n": "Dina", "g": "f"}, "b": {"n": "Hossam", "g": "m"}}, "lines": [["b", "Dina, I spent two and a half hours in traffic today. Two and a half hours, all of which I could have spent doing something useful!", "دينا، قضيت ساعتين ونص في الزحمة النهارده. ساعتين ونص، كان ممكن أقضيهم كلهم في حاجة مفيدة!"], ["a", "I know the feeling. That's why I'm seriously thinking of moving to one of the new cities.", "عارفة الإحساس ده. عشان كده بفكر بجد أنقل لمدينة من المدن الجديدة."], ["b", "Really? The ones in the desert? Most of my friends who moved there say it feels empty.", "بجد؟ اللي في الصحرا؟ أغلب صحابي اللي نقلوا هناك بيقولوا إنها حاسينها فاضية."], ["a", "Some areas are, but the one in which my cousin lives has parks, schools and even a cycle lane.", "في مناطق كده، بس المنطقة اللي ساكنة فيها بنت خالتي فيها جناين ومدارس وحتى حارة للعجل."], ["b", "A cycle lane in Egypt? Now that's the future!", "حارة عجل في مصر؟ ده بقى المستقبل!"], ["a", "And there's a new system whereby you can pay for buses, electricity and water with one app.", "وفي نظام جديد تقدر بيه تدفع الأتوبيسات والكهربا والمية من أبلكيشن واحد."], ["b", "Sounds like a smart city. But what about the people who can't afford to move? Downtown is where their jobs are.", "شكلها مدينة ذكية. بس إيه بالنسبة للناس اللي مش قادرة تنقل؟ وسط البلد هو المكان اللي فيه شغلهم."], ["a", "That's the big challenge. A city in which only the rich can live isn't really a successful city.", "دي التحدي الكبير. المدينة اللي الأغنيا بس اللي يقدروا يعيشوا فيها مش مدينة ناجحة بجد."], ["b", "Exactly. And old Cairo has a soul — the cafés, the markets, the people, none of whom you'll find in a new city.", "بالظبط. والقاهرة القديمة ليها روح — القهاوي والأسواق والناس، ولا حاجة منهم هتلاقيها في مدينة جديدة."], ["a", "That's true. Maybe the answer is better public transport, so people can live where they want.", "صح. يمكن الحل مواصلات عامة أحسن، عشان الناس تعيش في المكان اللي هي عايزاه."], ["b", "Agreed. They're building a new metro line, by which time I'll probably be retired!", "موافق. بيبنوا خط مترو جديد، وعلى ما يخلص هكون غالبًا طلعت معاش!"], ["a", "Ha! Well, until then, download a podcast for the traffic!", "هههه! طب لحد ساعتها، نزّل بودكاست للزحمة!"]], "quiz": [{"q": "How long did Hossam spend in traffic?", "o": ["two and a half hours", "thirty minutes", "four hours"], "a": 0}, {"q": "What is Dina thinking of doing?", "o": ["moving to one of the new cities", "buying a car", "working from home"], "a": 0}, {"q": "What does the area where Dina's cousin lives have?", "o": ["parks, schools and a cycle lane", "only offices", "nothing yet"], "a": 0}, {"q": "What does the new app system allow?", "o": ["paying for buses, electricity and water", "ordering food", "booking flights"], "a": 0}, {"q": "What does Hossam say old Cairo has?", "o": ["a soul — cafés, markets and people", "no traffic", "cheap houses"], "a": 0}], "fill": [[0, "all of which"], [1, "new cities"], [2, "Most of my friends"], [3, "in which"], [3, "cycle lane"], [5, "whereby"], [6, "afford"], [7, "in which only the rich"], [8, "none of whom"], [9, "public transport"], [10, "by which time"], [10, "retired"]]}], "vocab": [{"t": "Urban life", "ar": "الحياة في المدينة", "items": [["🏙️", "urban", "Over half the world lives in urban areas."], ["🚗", "congestion", "Traffic congestion wastes millions of hours."], ["🏘️", "suburb", "They moved to a quiet suburb."], ["🏚️", "informal settlement", "Many cities have informal settlements."], ["🧑‍🤝‍🧑", "densely populated", "Cairo is densely populated."], ["🌆", "skyline", "The city skyline is full of towers."], ["🔊", "noise pollution", "Noise pollution affects sleep."], ["🛒", "amenities", "The area has good amenities: shops, schools and parks."]]}, {"t": "Planning the city", "ar": "تخطيط المدينة", "items": [["🗺️", "urban planning", "Good urban planning reduces traffic."], ["🚇", "public transport", "Invest in public transport."], ["🚲", "cycle lane", "The city built new cycle lanes."], ["🚶", "pedestrian", "This street is for pedestrians only."], ["🏗️", "infrastructure", "The city needs better infrastructure."], ["🌳", "green space", "Green spaces improve mental health."], ["💡", "smart city", "Smart cities use data to manage services."], ["🔁", "regeneration", "The regeneration of the old port created jobs."]]}, {"t": "Housing & society", "ar": "السكن والمجتمع", "items": [["🏠", "affordable housing", "There is a shortage of affordable housing."], ["📈", "gentrification", "Gentrification pushes poorer residents out."], ["💸", "rent", "Rent has doubled in five years."], ["🧳", "commute", "My daily commute takes an hour."], ["🤝", "community", "There is a strong sense of community here."], ["⚖️", "inequality", "Urban inequality is growing."], ["♻️", "sustainable", "We need sustainable cities."], ["🏛️", "heritage", "Protect the city's heritage buildings."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["What do you love and hate about the city you live in?", "إيه اللي بتحبه وبتكرهه في المدينة اللي ساكن فيها؟", "I love the energy but hate the traffic."], ["How long is your daily commute?", "مشوارك اليومي بياخد قد إيه؟", "About forty minutes by metro."], ["Would you rather live in a big city or a small town?", "تفضل تعيش في مدينة كبيرة ولا بلد صغيرة؟", "A big city while I'm young, a small town later."], ["What would make your neighbourhood a better place to live?", "إيه اللي يخلي حيّك أحسن؟", "More trees and safer pavements."], ["Which city in the world would you most like to live in?", "نفسك تعيش في أنهي مدينة في العالم؟", "Copenhagen, because people cycle everywhere."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Should cars be banned from city centres?", "العربيات تتمنع من وسط المدن؟", "In some streets, yes."], ["Are new cities a good solution to overcrowding?", "المدن الجديدة حل كويس للزحمة؟", "Only if people can afford to live there."], ["Should old buildings be protected or replaced?", "المباني القديمة تتحمى ولا تتهد؟", "Protected — they are our history."], ["Would you like to live in a \"smart city\"?", "تحب تعيش في مدينة ذكية؟", "Yes, but I worry about privacy."], ["What will cities look like in 2070?", "المدن هيبقى شكلها إيه في ٢٠٧٠؟", "Greener, quieter and full of electric transport."]]}], "grammar": {"title": "Advanced Relative Clauses", "ar": "جمل الوصل المتقدمة — in which / whereby / most of whom / by which time", "blocks": [{"type": "intro", "en": "At C1, relative clauses become more formal and flexible. We put prepositions before which/whom, use quantifiers (most of which, none of whom), and use special words like whereby and by which time.", "ar": "في C1، جمل الوصل بتبقى رسمية ومرنة أكتر. بنحط حرف الجر قبل which/whom، ونستخدم كميات (most of which / none of whom)، وكلمات خاصة زي whereby وby which time."}, {"type": "big", "items": [{"v": "preposition + which / whom", "p": "formal style", "c": 1, "eg": ["The area in which my cousin lives has parks.", "The person to whom I spoke was very helpful.", "The reasons for which they moved are complex."]}, {"v": "quantifier + of which / of whom", "p": "all / most / some / none / both / many", "c": 2, "eg": ["I spent three hours in traffic, all of which was wasted.", "I have five friends there, most of whom love it.", "The markets, none of which exist in new cities…"]}, {"v": "whereby / by which time / at which point", "p": "special relatives", "c": 3, "eg": ["A system whereby you pay with one app.", "They'll finish in 2030, by which time I'll be retired.", "The water reached the door, at which point we left."]}]}, {"type": "table", "title": "🔄 Informal → Formal", "head": ["Informal", "Formal / advanced"], "rows": [["the area my cousin lives in", "the area in which my cousin lives"], ["the man I spoke to", "the man to whom I spoke"], ["I have friends there. Most of them love it.", "I have friends there, most of whom love it."], ["a system that lets you pay by app", "a system whereby you pay by app"], ["They will finish in 2030. I'll be retired then.", "They will finish in 2030, by which time I'll be retired."]]}, {"type": "uses", "title": "💡 Useful forms", "ar": "تراكيب مفيدة", "items": [["🏠", "where = in which", "the house where / in which I grew up", "المكان"], ["⏰", "when = during which / at which", "the year during which I lived abroad", "الوقت"], ["❓", "why = for which", "the reason for which he left", "السبب"], ["📌", "which (whole sentence)", "He was late, which annoyed everyone.", "تعليق على الجملة كلها"]]}, {"type": "tip", "en": "After a preposition, use 'whom' for people and 'which' for things — never 'that' or 'who': in that ✖ / with who ✖ → in which ✔ / with whom ✔. Quantifier clauses always need commas.", "ar": "بعد حرف الجر استخدم whom للناس وwhich للحاجات — مش that ولا who. وجمل most of which / none of whom لازم ليها فواصل."}]}, "exercises": [{"type": "mcq", "title": "Relative Clauses — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "The area in ___ my cousin lives has parks.", "o": ["which", "that", "where", "who"], "a": 0}, {"q": "The official to ___ I spoke was very helpful.", "o": ["whom", "who", "which", "that"], "a": 0}, {"q": "I have five friends there, most of ___ love it.", "o": ["whom", "who", "them", "which"], "a": 0}, {"q": "I spent three hours in traffic, all of ___ was wasted.", "o": ["which", "that", "it", "what"], "a": 0}, {"q": "There is a new system ___ you pay for everything with one app.", "o": ["whereby", "whom", "whose", "what"], "a": 0}, {"q": "The metro will open in 2030, by ___ time I'll be retired.", "o": ["which", "that", "when", "what"], "a": 0}, {"q": "The cafés and markets, none of ___ exist in new cities, give Cairo its soul.", "o": ["which", "them", "whom", "that"], "a": 0}, {"q": "The water reached the door, at ___ point we left.", "o": ["which", "that", "what", "where"], "a": 0}, {"q": "Which sentence is correct?", "o": ["The reason for which he left is unclear.", "The reason for that he left is unclear.", "The reason for who he left is unclear.", "The reason which for he left is unclear."], "a": 0}, {"q": "He arrived two hours late, ___ annoyed everyone.", "o": ["which", "that", "what", "who"], "a": 0}]}, {"type": "mcq", "title": "Formal or informal?", "ar": "رسمي ولا عادي؟", "items": [{"q": "the man I spoke to → the man ___ I spoke", "o": ["to whom", "to who"], "a": 0}, {"q": "the street I grew up in → the street ___ I grew up", "o": ["in which", "in that"], "a": 0}, {"q": "After a preposition, use ___ for things.", "o": ["which", "that"], "a": 0}, {"q": "Quantifier clauses (most of whom…) need ___.", "o": ["commas", "no commas"], "a": 0}, {"q": "\"whereby\" means ___.", "o": ["by which / through which", "where"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["The area", "in which", "she lives", "is quiet"], "a": [0, 1, 2, 3]}, {"c": ["I have", "ten cousins,", "most of whom", "live abroad"], "a": [0, 1, 2, 3]}, {"c": ["a system", "whereby", "you pay", "by app"], "a": [0, 1, 2, 3]}, {"c": ["The man", "to whom", "I spoke", "was kind"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "The 15-Minute City", "ar": "مدينة الربع ساعة", "g": "m", "lines": [["Imagine a city in which everything you need — your school, your doctor, a park, a supermarket and even your workplace — is no more than fifteen minutes away on foot or by bike.", "تخيّل مدينة كل اللي محتاجه فيها — مدرستك ودكتورك وجنينة وسوبر ماركت وحتى شغلك — مش أبعد من ربع ساعة مشي أو بالعجلة."], ["This is the idea behind the \"15-minute city\", a concept developed by the urban planner Carlos Moreno and adopted by the mayor of Paris, Anne Hidalgo.", "دي الفكرة ورا \"مدينة الربع ساعة\"، مفهوم طوّره مخطط المدن كارلوس مورينو وتبنّته عمدة باريس، آن هيدالجو."], ["For most of the twentieth century, cities were designed around the car. Homes, offices and shops were placed in separate zones, between which people had to travel long distances every day.", "أغلب القرن العشرين، المدن كانت بتتصمم حوالين العربية. البيوت والمكاتب والمحلات كانت في مناطق منفصلة، والناس لازم يسافروا مسافات طويلة بينهم كل يوم."], ["The result was congestion, pollution and long commutes, the cost of which is measured not only in money but in time, health and family life.", "النتيجة كانت زحمة وتلوث ومشاوير طويلة، وتكلفتها مش بتتقاس بالفلوس بس لكن بالوقت والصحة والحياة العائلية."], ["The 15-minute model reverses this. Neighbourhoods are designed as mixed communities, in which people live, work and relax close together.", "نموذج الربع ساعة بيعكس ده. الأحياء بتتصمم كمجتمعات مختلطة، الناس فيها بتعيش وتشتغل وترتاح قريب من بعض."], ["Streets are redesigned for pedestrians and cyclists, and school playgrounds are opened to the public at weekends.", "الشوارع بيتعاد تصميمها للمشاة وراكبي العجل، وملاعب المدارس بتتفتح للناس في الويك إند."], ["Supporters argue that the model reduces emissions, strengthens local businesses and gives residents a greater sense of community.", "المؤيدين بيقولوا إن النموذج ده بيقلل الانبعاثات، ويقوّي المحلات المحلية، ويدي السكان إحساس أكبر بالانتماء."], ["Critics, however, worry that it could increase gentrification, whereby rising property prices push poorer residents out of the improved areas.", "لكن المنتقدين قلقانين إنه ممكن يزوّد \"الاستطباق\"، اللي فيه أسعار العقارات بتعلى وتطلّع السكان الأفقر برة المناطق اللي اتحسنت."], ["Others point out that the concept works best in dense European cities, many of which were built before cars existed, and may be harder to apply in sprawling cities like Los Angeles or Cairo's new suburbs.", "وغيرهم بيشاوروا إن المفهوم بينجح أكتر في المدن الأوروبية الكثيفة، اللي كتير منها اتبنى قبل ما العربيات تتوجد، وممكن يبقى أصعب تطبيقه في مدن ممتدة زي لوس أنجلوس أو ضواحي القاهرة الجديدة."], ["Nevertheless, the pandemic, during which millions of people rediscovered their local neighbourhoods, has made the idea more popular than ever.", "ومع ذلك، الجايحة، اللي فيها ملايين الناس اكتشفوا أحيائهم المحلية من جديد، خلت الفكرة منتشرة أكتر من أي وقت."]], "keys": [["🗺️", "urban planner", "a person who designs how cities develop"], ["🏛️", "mayor", "the elected leader of a city"], ["🧩", "zone", "an area used for a particular purpose"], ["🔀", "mixed community", "an area where people live, work and shop together"], ["🌫️", "emissions", "gases released into the air"], ["🕸️", "sprawling", "spreading over a large area in an untidy way"]], "quiz": [{"q": "What is a \"15-minute city\"?", "o": ["a city where everything you need is 15 minutes away on foot or by bike", "a city you can cross in 15 minutes by car", "a city with 15 parks"], "a": 0}, {"q": "Who adopted the idea in Paris?", "o": ["the mayor, Anne Hidalgo", "the president", "a car company"], "a": 0}, {"q": "How were 20th-century cities designed?", "o": ["around the car, with separate zones", "around bicycles", "without roads"], "a": 0}, {"q": "What do critics worry about?", "o": ["gentrification pushing poorer residents out", "too many cars", "too few shops"], "a": 0}, {"q": "Where does the concept work best?", "o": ["dense European cities built before cars", "sprawling cities like Los Angeles", "desert towns"], "a": 0}, {"q": "What made the idea more popular?", "o": ["the pandemic", "cheaper cars", "new motorways"], "a": 0}]}, "idioms": {"items": [["the concrete jungle", "A big city full of buildings and few green spaces.", "غابة الأسمنت", "I need a weekend away from the concrete jungle.", "محتاج ويك إند بعيد عن غابة الأسمنت."], ["the rat race", "The stressful, competitive routine of modern working life.", "سباق الفيران (طاحونة الحياة)", "He quit the rat race and moved to the countryside.", "ساب طاحونة الحياة ونقل الريف."], ["live out of a suitcase", "To travel so often that you never fully unpack.", "عايش على الشنطة", "As a consultant, I live out of a suitcase.", "كاستشاري، أنا عايش على الشنطة."], ["a stone's throw (from)", "Very close to.", "على بُعد خطوات", "Our flat is a stone's throw from the metro.", "شقتنا على بعد خطوات من المترو."]], "quiz": [{"q": "The café is ___ from my office — just two minutes away.", "o": ["a stone's throw", "the rat race", "a concrete jungle", "a suitcase"], "a": 0}, {"q": "I'm tired of the ___. I want a slower life.", "o": ["rat race", "stone's throw", "suitcase", "jungle"], "a": 0}, {"q": "\"The concrete jungle\" describes…", "o": ["a big city with few green spaces", "a real jungle", "a building site", "a zoo"], "a": 0}, {"q": "She travels every week and ___.", "o": ["lives out of a suitcase", "throws stones", "runs the race", "lives in a jungle"], "a": 0}]}, "phrasal": {"items": [["pull down", "To demolish a building.", "يهدّ (مبنى)", "They pulled down the old cinema to build flats.", "هدّوا السينما القديمة عشان يبنوا شقق."], ["spring up", "To appear suddenly and in large numbers.", "يطلع فجأة / ينتشر", "New cafés have sprung up all over the area.", "كافيهات جديدة طلعت فجأة في المنطقة كلها."], ["move out", "To leave your home permanently.", "يسيب السكن / يعزّل", "Rising rents forced many families to move out.", "الإيجارات العالية خلت عيلات كتير تعزّل."], ["crack down on", "To take strong action against something.", "يشدّد / يضرب بيد من حديد", "The city is cracking down on illegal parking.", "المدينة بتشدّد على الركن الغلط."]], "quiz": [{"q": "The police are ___ drivers who use their phones.", "o": ["cracking down on", "springing up", "pulling down", "moving out"], "a": 0}, {"q": "Coffee shops have ___ everywhere in the new city.", "o": ["sprung up", "pulled down", "moved out", "cracked down"], "a": 0}, {"q": "Historic buildings should not be ___.", "o": ["pulled down", "sprung up", "moved out", "cracked"], "a": 0}, {"q": "When the rent doubled, we had to ___.", "o": ["move out", "spring up", "pull down", "crack down"], "a": 0}]}, "slang": {"items": [["bougie", "Fancy, expensive and a bit pretentious.", "فخم ومتكلّف / راقي زيادة", "This new compound is so bougie — it has a sushi bar!", "الكمباوند الجديد ده فخم زيادة — فيه بار سوشي!", "بهزار"], ["dead", "Very quiet, with nothing happening.", "ميت / مفيهوش حد", "The new city is dead after 9 p.m.", "المدينة الجديدة بتبقى ميتة بعد ٩ بالليل.", "عادي"], ["buzzing", "Lively and full of energy.", "زحمة وحيوية", "Downtown is buzzing on Thursday nights.", "وسط البلد بيبقى مليان حيوية ليلة الجمعة.", "إيجابي"], ["stuck in traffic", "Unable to move because of traffic.", "واقف في الزحمة", "Sorry I'm late — I was stuck in traffic for an hour.", "آسف اتأخرت — كنت واقف في الزحمة ساعة.", "أهم عذر في القاهرة 😄"], ["hood", "Neighbourhood (informal).", "الحتة / المنطقة", "This is the best bakery in the hood.", "ده أحسن فرن في الحتة.", "سلانج أمريكي"]], "quiz": [{"q": "A lively place full of energy is ___.", "o": ["buzzing", "dead", "bougie", "stuck"], "a": 0}, {"q": "\"The village is dead at night.\" means it is…", "o": ["very quiet", "dangerous", "beautiful", "old"], "a": 0}, {"q": "An expensive, fancy restaurant could be described as ___.", "o": ["bougie", "dead", "hood", "stuck"], "a": 0}, {"q": "\"Hood\" means…", "o": ["neighbourhood", "a hat", "a car", "a park"], "a": 0}]}, "story": {"title": "The Last House on the Street", "ar": "آخر بيت في الشارع", "g": "f", "lines": [["When the developers arrived in Hagg Fawzia's street, they offered every family a large amount of money to move out. One by one, her neighbours accepted.", "لما المطورين العقاريين جم شارع الحاجة فوزية، عرضوا على كل عيلة مبلغ كبير عشان تعزّل. واحد ورا التاني، جيرانها وافقوا."], ["Within a year, all the old houses, most of which had stood for a century, had been pulled down. Only hers remained.", "في خلال سنة، كل البيوت القديمة، اللي أغلبها كان واقف من قرن، اتهدت. بيتها بس اللي فضل."], ["Around her, glass towers sprang up, full of offices, gyms and bougie cafés. Her small house with its blue door looked like something from another world.", "حواليها، أبراج إزاز طلعت، مليانة مكاتب وجيمات وكافيهات فخمة. بيتها الصغير أبو باب أزرق كان شكله حاجة من عالم تاني."], ["\"Why won't you sell?\" a young manager asked her one day. \"You could buy a modern flat in a new city.\"", "\"ليه مش عايزة تبيعي؟\" مدير شاب سألها في يوم. \"تقدري تشتري شقة حديثة في مدينة جديدة.\""], ["She invited him in for tea. On the walls were photographs of the street as it used to be — children playing football, neighbours sharing food during Ramadan, a wedding in the middle of the road.", "عزمته على شاي. على الحيطان كانت صور الشارع زي ما كان — أطفال بيلعبوا كورة، وجيران بيتشاركوا الأكل في رمضان، وفرح في نص الشارع."], ["\"This is the house in which I was born, in which I raised my children, and in which my husband died,\" she said. \"You can't buy that.\"", "\"ده البيت اللي اتولدت فيه، واللي ربيت فيه ولادي، واللي جوزي مات فيه،\" قالت. \"ده ميتشراش بفلوس.\""], ["The manager went back to his office and couldn't stop thinking about the photographs. He proposed an idea to his company.", "المدير رجع مكتبه ومقدرش يبطّل يفكر في الصور. واقترح فكرة على شركته."], ["Instead of demolishing the house, they would protect it — and turn the ground floor into a small community museum about the history of the neighbourhood.", "بدل ما يهدّوا البيت، هيحموه — ويحولوا الدور الأرضي لمتحف صغير للمجتمع عن تاريخ الحي."], ["Hagg Fawzia agreed on one condition: the museum would be free, and the tea would be hers.", "الحاجة فوزية وافقت بشرط واحد: المتحف يبقى ببلاش، والشاي يبقى عليها."], ["Today, office workers queue at the blue door at lunchtime to hear her stories. In a street full of glass towers, the smallest building has become its heart.", "النهارده، موظفين المكاتب بيقفوا طابور عند الباب الأزرق وقت الغدا عشان يسمعوا حكاياتها. في شارع مليان أبراج إزاز، أصغر مبنى بقى قلبه."]], "quiz": [{"q": "What did the developers offer the families?", "o": ["money to move out", "new jobs", "free cars"], "a": 0}, {"q": "What happened to the old houses?", "o": ["They were pulled down.", "They were painted.", "They became museums."], "a": 0}, {"q": "What was on Hagg Fawzia's walls?", "o": ["photographs of the street in the past", "paintings of the sea", "nothing"], "a": 0}, {"q": "What did the company decide to do?", "o": ["protect the house and open a community museum", "demolish it anyway", "buy her a flat"], "a": 0}, {"q": "What was her condition?", "o": ["The museum would be free, and she would serve the tea.", "She would get a lot of money.", "She would move to a new city."], "a": 0}]}, "challenge": {"title": "Design Your City", "ar": "صمّم مدينتك — جاوب وسجّل", "qs": ["Describe the neighbourhood in which you grew up. How has it changed?", "Should historic buildings ever be pulled down for new development?", "What would your ideal city look like in 2050? Use at least two advanced relative clauses.", "Is it fair that people are pushed out of their neighbourhoods by rising prices?", "Would you rather live in a buzzing city centre or a quiet new city? Why?", "What is the biggest problem in your city, and how would you solve it?", "Should public transport be free for everyone?", "Describe a city you have visited, the atmosphere of which you loved.", "Are smart cities a good idea, or do they threaten our privacy?", "If you were the mayor of your city for a year, what would you do first?"]}, "games": {"pairs": [["🏙️", "urban"], ["🚗", "congestion"], ["🏘️", "suburb"], ["🚇", "public transport"], ["🚶", "pedestrian"], ["🌳", "green space"]], "spell": [["🏗️", "infrastructure"], ["🔁", "regeneration"], ["🏠", "affordable housing"], ["📈", "gentrification"], ["🧳", "commute"], ["🤝", "community"], ["🏛️", "heritage"], ["🛒", "amenities"]], "speed": [["The area in which she lives is quiet.", true], ["The man to who I spoke was kind.", false], ["I have ten cousins, most of whom live abroad.", true], ["I have ten cousins, most of them live abroad.", false], ["a system whereby you pay by app", true], ["They'll finish in 2030, by which time I'll be old.", true], ["The house in that I was born", false], ["He was late, which annoyed everyone.", true], ["The reason for which he left is unclear.", true], ["None of which shops were open.", false], ["A suburb is the centre of a city.", false], ["Gentrification can push poorer residents out.", true], ["\"A stone's throw\" means very close.", true], ["\"Pull down\" means to demolish.", true], ["\"Buzzing\" means quiet and empty.", false], ["\"The rat race\" is the stressful routine of work.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "Too much traffic = ___.", "o": ["congestion", "heritage", "amenities"], "a": 0, "pic": "🚗"}, {"q": "A person walking in the street = a ___.", "o": ["pedestrian", "commuter", "mayor"], "a": 0, "pic": "🚶"}, {"q": "Roads, power lines and water systems = ___.", "o": ["infrastructure", "suburbs", "skyline"], "a": 0, "pic": "🏗️"}, {"q": "Old buildings and traditions of a place = its ___.", "o": ["heritage", "rent", "commute"], "a": 0, "pic": "🏛️"}, {"q": "Housing that people can pay for = ___ housing.", "o": ["affordable", "urban", "dense"], "a": 0, "pic": "🏠"}, {"q": "\"الزحمة المرورية\" in English is…", "o": ["traffic congestion", "traffic light", "traffic police"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "The town in ___ I grew up has changed a lot.", "o": ["which", "that", "who"], "a": 0}, {"q": "The teacher to ___ I owe my success retired last year.", "o": ["whom", "who", "which"], "a": 0}, {"q": "She has three brothers, all of ___ are engineers.", "o": ["whom", "them", "who"], "a": 0}, {"q": "We visited five museums, two of ___ were free.", "o": ["which", "them", "that"], "a": 0}, {"q": "There's a scheme ___ students get free bus passes.", "o": ["whereby", "whom", "whose"], "a": 0}, {"q": "Which is correct?", "o": ["The bridge will open in 2028, by which time we'll have moved.", "The bridge will open in 2028, by that time which we'll have moved.", "The bridge will open in 2028, by who time we'll have moved."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"Why are you late?\" — Best answer:", "o": ["Sorry, I was stuck in traffic.", "I was traffic.", "Late is time."], "a": 0}, {"q": "\"Is your flat near the metro?\" — Best answer:", "o": ["Yes, it's a stone's throw away.", "Yes, it's the rat race.", "Yes, it's a jungle."], "a": 0}, {"q": "\"How is the new city at night?\" — Best answer:", "o": ["Honestly, it's dead after nine.", "It's buzzing dead.", "It's bougie traffic."], "a": 0}, {"q": "\"Should they pull down the old market?\" — Best answer:", "o": ["I don't think so. It's part of our heritage.", "Pull is a verb.", "Yes, pull it up."], "a": 0}, {"q": "\"I'm tired of working 12 hours a day.\" — Best answer:", "o": ["Maybe it's time to leave the rat race.", "Rats are animals.", "Work more!"], "a": 0}, {"q": "\"Who did you speak to?\" (formal) — Best answer:", "o": ["The officer to whom I spoke was very helpful.", "The officer who to I spoke.", "The officer which I spoke."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["In 2019, the city of Seoul removed a motorway that ran through its centre.", "In its place, it restored a stream, beside which there is now a five-kilometre park.", "Critics predicted terrible traffic, none of which happened.", "Instead, temperatures near the stream dropped, and the area became one of the city's most popular places.", "Many cities, several of which are in Europe, have since copied the idea."], "qs": [{"q": "What did the city remove?", "o": ["a motorway", "a stadium", "a market"], "a": 0}, {"q": "What did it restore?", "o": ["a stream with a park beside it", "an old palace", "a railway"], "a": 0}, {"q": "What did critics predict?", "o": ["terrible traffic", "more tourists", "floods"], "a": 0}, {"q": "What happened to temperatures near the stream?", "o": ["They dropped.", "They rose.", "They didn't change."], "a": 0}, {"q": "Where are several of the cities that copied the idea?", "o": ["Europe", "Africa", "South America"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write a proposal (100–150 words) to your city council suggesting one change that would improve life in your neighbourhood. Use at least three advanced relative clauses (in which, whereby, most of whom, by which time…).", "promptAr": "اكتب اقتراح (١٠٠–١٥٠ كلمة) لمجلس مدينتك بتغيير واحد يحسّن الحياة في حيّك. استخدم ٣ جمل وصل متقدمة على الأقل.", "checks": [["🏙️", "City words", "x", "\\b(city|neighbourhood|traffic|transport|park|parks|residents|street|streets|housing|community|pedestrians?)\\b"], ["🔗", "Advanced relative", "x", "\\b(in which|to whom|of which|of whom|whereby|by which time|at which point|during which|for which)\\b"], ["📝", "Proposal language", "x", "\\b(i propose|i suggest|i recommend|would like to suggest|this would|should be)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "fKnAJCSGSdk", "title": "Urbanization and the Future of Cities", "ar": "التحضّر ومستقبل المدن — TED-Ed", "by": "TED-Ed · Vance Kite", "lines": [["Today more than half of the world's people live in cities, and by the middle of the century this figure is set to reach about 70%.", "النهارده أكتر من نص سكان العالم عايشين في مدن، ومع نص القرن الرقم ده متوقع يوصل لحوالي ٧٠٪."], ["A century ago, only about 20% of people lived in cities.", "من مية سنة، حوالي ٢٠٪ بس من الناس كانوا عايشين في مدن."], ["Early humans were hunter-gatherers who moved from place to place to find food.", "البشر الأوائل كانوا صيادين وجامعين بيتنقلوا من مكان لمكان عشان يلاقوا أكل."], ["About 10,000 years ago, people learned selective breeding and early farming, and settled in semi-permanent villages.", "من حوالي ١٠ آلاف سنة، الناس اتعلموا الانتقاء في التربية والزراعة البدائية، واستقروا في قرى شبه دائمة."], ["When irrigation was developed, villages no longer had to move when the soil was depleted.", "لما الري اتطور، القرى مبقتش مضطرة تنقل لما التربة تتستهلك."], ["Food surpluses meant that not everyone had to farm, so people could develop specialised trades.", "فايض الأكل معناه إن مش كل الناس لازم تزرع، فالناس قدرت تطور حرف متخصصة."], ["Cities grew as centres of commerce, encouraging better transport such as roads, ships and ports.", "المدن كبرت كمراكز للتجارة، وده شجّع مواصلات أحسن زي الطرق والمراكب والموانئ."], ["Some ancient cities were more densely populated than modern cities like Shanghai or Kolkata.", "بعض المدن القديمة كانت مزدحمة بالسكان أكتر من مدن حديثة زي شنغهاي أو كولكاتا."], ["The Industrial Revolution created the modern city, with policing, fire services, sanitation, roads and electricity.", "الثورة الصناعية عملت المدينة الحديثة، بالشرطة والمطافي والصرف الصحي والطرق والكهربا."], ["The global population, now over seven billion, may reach about ten billion, mostly in cities in poorer countries.", "سكان العالم، اللي دلوقتي أكتر من ٧ مليار، ممكن يوصلوا لحوالي ١٠ مليار، أغلبهم في مدن في دول أفقر."], ["Future cities must provide food, sanitation and education for everyone without damaging the land that supports them.", "مدن المستقبل لازم توفر أكل وصرف صحي وتعليم للكل من غير ما تضر الأرض اللي بتعيش عليها."], ["They may include vertical farms, rooftop gardens and renewable energy — diverse, malleable and creative places.", "ممكن يبقى فيها مزارع رأسية وجناين على الأسطح وطاقة متجددة — أماكن متنوعة ومرنة ومبدعة."]], "words": ["cities", "hunter-gatherers", "selective breeding", "semi-permanent", "irrigation", "depleted", "surpluses", "commerce", "densely populated", "sanitation", "vertical farms", "malleable"], "quiz": [{"q": "What percentage of people may live in cities by mid-century?", "o": ["about 70%", "about 20%", "about 100%"], "a": 0}, {"q": "How did early humans live?", "o": ["as hunter-gatherers moving to find food", "in big cities", "in factories"], "a": 0}, {"q": "What did irrigation allow?", "o": ["villages to stay in one place", "people to travel by ship", "factories to open"], "a": 0}, {"q": "Why could people develop specialised trades?", "o": ["Food surpluses meant not everyone had to farm.", "They had computers.", "The government paid them."], "a": 0}, {"q": "What did the Industrial Revolution bring?", "o": ["policing, sanitation, roads and electricity", "hunting", "smaller villages"], "a": 0}, {"q": "What might future cities include?", "o": ["vertical farms, rooftop gardens and renewable energy", "no transport at all", "only factories"], "a": 0}]}]}, "4": {"n": 4, "title": "Science and Ethics", "ar": "العلم والأخلاق — Conditional Inversion", "icon": "🧬", "cover": "img/c1/u4.jpg", "intro": "ناقش الهندسة الوراثية والطب الحديث والتجارب العلمية وحدود العلم، واستخدم الشرط المقلوب الرسمي: Had I known… / Were it not for… / Should you need…", "videos": [{"id": "c1v4", "title": "Designer Babies?", "ar": "أطفال حسب الطلب؟ — سلمى وعمر", "src": "video/c1/u4v1.mp4", "poster": "img/c1/u4v1.jpg", "sp": {"a": {"n": "Salma", "g": "f"}, "b": {"n": "Omar", "g": "m"}}, "lines": [["a", "Omar, did you see that documentary about gene editing last night?", "عمر، شفت الفيلم الوثائقي عن تعديل الجينات امبارح بالليل؟"], ["b", "I did. Honestly, it was terrifying. Scientists can now edit an embryo's DNA!", "شفته. بصراحة، كان مرعب. العلماء دلوقتي يقدروا يعدّلوا الـDNA بتاع الجنين!"], ["a", "But think of the diseases they could prevent. Had this technology existed earlier, my uncle might not have suffered from his illness.", "بس فكّر في الأمراض اللي ممكن يمنعوها. لو التكنولوجيا دي كانت موجودة بدري، خالي يمكن مكانش عانى من مرضه."], ["b", "I understand. Treating disease is one thing. But what if parents start choosing their baby's eye colour or intelligence?", "فاهم. علاج الأمراض حاجة. بس لو الأهالي بدأوا يختاروا لون عين البيبي أو ذكاءه؟"], ["a", "That's where the line should be. Were scientists to go that far, it would be unethical.", "هنا المفروض يكون الحد. لو العلماء وصلوا للدرجة دي، هيبقى ده غير أخلاقي."], ["b", "And who decides where the line is? Rich families would get 'better' babies, and inequality would become genetic.", "ومين اللي يقرر الحد فين؟ العيلات الغنية هتاخد أطفال \"أحسن\"، واللامساواة هتبقى وراثية."], ["a", "That's a frightening thought. Should that happen, society would be divided in a completely new way.", "دي فكرة مخيفة. لو ده حصل، المجتمع هيتقسم بطريقة جديدة تمامًا."], ["b", "Exactly. Were it not for strict laws, some labs would already be doing it.", "بالظبط. لولا القوانين الصارمة، كان في معامل بتعمل كده من دلوقتي."], ["a", "Still, I believe science has saved more lives than it has harmed. Were it not for vaccines, millions of children would have died.", "ومع ذلك، أنا شايفة إن العلم أنقذ أرواح أكتر من اللي أذاها. لولا التطعيمات، ملايين الأطفال كانوا ماتوا."], ["b", "I agree. Science itself isn't good or bad — it depends on how we use it.", "موافق. العلم نفسه مش كويس ولا وحش — الموضوع على حسب إحنا بنستخدمه إزاي."], ["a", "So we need scientists and ethicists working together.", "يبقى محتاجين علماء وخبراء أخلاقيات يشتغلوا مع بعض."], ["b", "Definitely. And should you ever need someone to debate this with, you know where to find me!", "أكيد. ولو احتجتي في يوم حد تتناقشي معاه في الموضوع ده، إنتي عارفة تلاقيني فين!"]], "quiz": [{"q": "What was the documentary about?", "o": ["gene editing", "space travel", "climate change"], "a": 0}, {"q": "What does Salma say about her uncle?", "o": ["He might not have suffered if the technology had existed earlier.", "He is a scientist.", "He refused treatment."], "a": 0}, {"q": "What worries Omar?", "o": ["parents choosing eye colour or intelligence", "the cost of medicine", "animal testing"], "a": 0}, {"q": "What does Omar think rich families would get?", "o": ["'better' babies", "cheaper medicine", "more holidays"], "a": 0}, {"q": "What does Salma say about vaccines?", "o": ["Without them, millions of children would have died.", "They are dangerous.", "They are too expensive."], "a": 0}], "fill": [[0, "gene editing"], [1, "embryo"], [2, "Had this technology existed"], [3, "intelligence"], [4, "Were scientists to go"], [4, "unethical"], [5, "inequality"], [6, "Should that happen"], [7, "Were it not for"], [8, "vaccines"], [10, "ethicists"], [11, "should you ever need"]]}], "vocab": [{"t": "Science & medicine", "ar": "العلم والطب", "items": [["🧬", "gene editing", "Gene editing could cure inherited diseases."], ["🧫", "embryo", "The embryo develops into a baby."], ["💉", "vaccine", "The vaccine was developed in record time."], ["🧪", "clinical trial", "The drug is in clinical trials."], ["🐑", "cloning", "Dolly the sheep was the first cloned mammal."], ["🔬", "breakthrough", "It was a major scientific breakthrough."], ["🧠", "organ transplant", "She needed an organ transplant."], ["🦠", "pathogen", "The lab studies dangerous pathogens."]]}, {"t": "Ethics", "ar": "الأخلاقيات", "items": [["⚖️", "bioethics", "Bioethics deals with moral issues in medicine."], ["🐀", "animal testing", "Animal testing is very controversial."], ["🤝", "informed consent", "Patients must give informed consent."], ["🎯", "playing God", "Critics accuse scientists of playing God."], ["🧭", "moral obligation", "Do we have a moral obligation to help?"], ["🚧", "boundaries", "Science needs ethical boundaries."], ["🪜", "slippery slope", "Some see gene editing as a slippery slope."], ["🛡️", "safeguards", "Strict safeguards are essential."]]}, {"t": "Debating science", "ar": "مناقشة العلم", "items": [["📉", "risk", "Every treatment carries some risk."], ["📈", "benefit", "The benefits outweigh the risks."], ["⚖️", "outweigh", "Do the benefits outweigh the dangers?"], ["🧾", "regulation", "Strict regulation protects patients."], ["🔐", "genetic data", "Who owns your genetic data?"], ["🧩", "unforeseen", "There could be unforeseen consequences."], ["💊", "cure", "Scientists hope to find a cure."], ["🌍", "for the greater good", "They did it for the greater good."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["Which scientific discovery has changed the world the most?", "أنهي اكتشاف علمي غير العالم أكتر؟", "Antibiotics — they saved millions of lives."], ["Is animal testing ever acceptable?", "التجارب على الحيوانات مقبولة؟", "Only for life-saving medicine, with strict rules."], ["Would you want to know your genetic risk of disease?", "تحب تعرف احتمال إصابتك بأمراض وراثية؟", "I'm not sure — it might make me anxious."], ["Should scientists be allowed to clone animals?", "العلماء ينفع يستنسخوا حيوانات؟", "Maybe to save endangered species."], ["Had you been born 100 years ago, how would your life be different?", "لو كنت اتولدت من ١٠٠ سنة، حياتك كانت هتختلف إزاي؟", "I might not have survived childhood illnesses."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Should parents be allowed to choose their baby's characteristics?", "الأهل ينفع يختاروا صفات البيبي؟", "Only to prevent serious diseases."], ["Who should control new technologies — scientists or governments?", "مين يتحكم في التكنولوجيا الجديدة — العلماء ولا الحكومات؟", "Both, with public debate."], ["Would you take part in a clinical trial?", "تشارك في تجربة طبية؟", "Only if the risks were explained clearly."], ["Is it right to spend billions on space travel while people are poor?", "صح نصرف مليارات على الفضاء والناس فقرا؟", "Space research also brings useful inventions."], ["Should you ever need a transplant, would you accept an animal organ?", "لو احتجت زرع عضو، تقبل عضو من حيوان؟", "If it saved my life, probably yes."]]}], "grammar": {"title": "Conditional Inversion", "ar": "الشرط المقلوب — Had I known / Were it not for / Should you need", "blocks": [{"type": "intro", "en": "In formal English, we can drop 'if' and invert the subject and auxiliary. This sounds more formal and elegant, and is common in academic writing, speeches and official letters.", "ar": "في الإنجليزي الرسمي، ممكن نشيل if ونقلب الفاعل والفعل المساعد. ده بيخلي الكلام رسمي وأشيك، ومنتشر في الكتابة الأكاديمية والخطابات والجوابات الرسمية."}, {"type": "big", "items": [{"v": "Had + subject + p.p. (3rd conditional)", "p": "If I had…", "c": 1, "eg": ["Had this technology existed earlier, he might not have suffered.", "Had I known, I would have helped.", "Had they tested it properly, nobody would have been hurt."]}, {"v": "Were + subject + to + verb / adjective (2nd conditional)", "p": "If I were / If they were to…", "c": 2, "eg": ["Were scientists to go that far, it would be unethical.", "Were I in your position, I would refuse.", "Were the law to change, many labs would close."]}, {"v": "Should + subject + verb (1st conditional)", "p": "If you happen to…", "c": 3, "eg": ["Should that happen, society would be divided.", "Should you need help, call this number.", "Should the results be positive, we will publish them."]}]}, {"type": "table", "title": "🔄 If → Inversion", "head": ["Normal", "Inverted (formal)"], "rows": [["If I had known, I would have come.", "Had I known, I would have come."], ["If I were you, I would wait.", "Were I you, I would wait."], ["If they were to approve it…", "Were they to approve it…"], ["If you need anything, call me.", "Should you need anything, call me."], ["If it were not for vaccines…", "Were it not for vaccines…"], ["If it had not been for her help…", "Had it not been for her help…"]]}, {"type": "uses", "title": "💡 Negative inversion", "ar": "النفي مع القلب", "items": [["🚫", "Had … not", "Had he not called, I would have missed it.", "لو مكانش"], ["🛑", "Were it not for", "Were it not for science, we'd live shorter lives.", "لولا (حاضر)"], ["⏪", "Had it not been for", "Had it not been for the doctor, she would have died.", "لولا (ماضي)"], ["📩", "Should you have any questions", "Should you have any questions, please contact us.", "جوابات رسمية"]]}, {"type": "tip", "en": "Never use contractions in negative inversion: Hadn't I known ✖ → Had I not known ✔. And don't keep 'if': If had I known ✖.", "ar": "متستخدمش الاختصار مع النفي: Had I not known مش Hadn't I known. ومتخليش if: If had I known غلط."}]}, "exercises": [{"type": "mcq", "title": "Conditional Inversion — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "___ I known about the problem, I would have helped.", "o": ["Had", "Have", "If had", "Were"], "a": 0}, {"q": "___ scientists to go that far, it would be unethical.", "o": ["Were", "Had", "Should", "Did"], "a": 0}, {"q": "___ you need any help, please call me.", "o": ["Should", "Had", "Were", "Would"], "a": 0}, {"q": "Were it not ___ vaccines, millions would die.", "o": ["for", "of", "by", "to"], "a": 0}, {"q": "Had it not ___ for the doctor, she would have died.", "o": ["been", "be", "was", "were"], "a": 0}, {"q": "___ I in your position, I would refuse the offer.", "o": ["Were", "Was", "Had", "Should"], "a": 0}, {"q": "Had they ___ it properly, nobody would have been hurt.", "o": ["tested", "test", "testing", "tests"], "a": 0}, {"q": "___ the results be positive, we will publish them.", "o": ["Should", "Had", "Were", "Did"], "a": 0}, {"q": "Which sentence is correct?", "o": ["Had I not called, you would have missed it.", "Hadn't I called, you would have missed it.", "If had I called, you would have missed it.", "Had I not call, you would have missed it."], "a": 0}, {"q": "\"Should you have any questions…\" is typical of ___.", "o": ["formal letters and emails", "text messages to friends", "football chants", "jokes"], "a": 0}]}, {"type": "mcq", "title": "Which conditional?", "ar": "أنهي شرط؟", "items": [{"q": "Had I… = ___ conditional", "o": ["third (past)", "first"], "a": 0}, {"q": "Should you… = ___ conditional", "o": ["first (possible future)", "third"], "a": 0}, {"q": "Were I… = ___ conditional", "o": ["second (imaginary present)", "zero"], "a": 0}, {"q": "\"Had it not been for…\" means ___.", "o": ["لولا (في الماضي)", "لأن"], "a": 0}, {"q": "Inversion makes a sentence more ___.", "o": ["formal", "casual"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["Had I", "known,", "I would", "have helped"], "a": [0, 1, 2, 3]}, {"c": ["Should you", "need", "anything,", "call me"], "a": [0, 1, 2, 3]}, {"c": ["Were it", "not for", "vaccines,", "millions would die"], "a": [0, 1, 2, 3]}, {"c": ["Were I", "you,", "I would", "wait"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "The Scientist Who Edited Babies", "ar": "العالِم اللي عدّل جينات أطفال", "g": "m", "lines": [["In November 2018, a Chinese scientist named He Jiankui shocked the world. He announced that he had edited the genes of twin baby girls before they were born.", "في نوفمبر ٢٠١٨، عالِم صيني اسمه هي جيانكوي صدم العالم. أعلن إنه عدّل جينات توأم بنات قبل ما يتولدوا."], ["Using a tool called CRISPR, he had changed a gene in the embryos, hoping to make the girls resistant to HIV, the virus their father carried.", "باستخدام أداة اسمها كريسبر، غيّر جين في الأجنة، على أمل إن البنات يبقى عندهم مناعة ضد فيروس الإتش آي في، اللي أبوهم كان حامله."], ["The reaction from the scientific community was immediate and furious. Leading researchers described the experiment as \"monstrous\" and deeply irresponsible.", "رد فعل المجتمع العلمي كان فوري وغاضب جدًا. باحثين كبار وصفوا التجربة إنها \"وحشية\" وغير مسؤولة بشكل كبير."], ["There were several reasons for their anger. First, there were safer ways to protect the babies from HIV, so the editing was not medically necessary.", "كان في كذا سبب لغضبهم. أولًا، كان في طرق أأمن لحماية الأطفال من الفيروس، فالتعديل مكانش ضروري طبيًا."], ["Second, the long-term effects of the changes were unknown. Had something gone wrong, the damage could have been passed down to future generations.", "تانيًا، التأثيرات طويلة المدى للتغييرات مكانتش معروفة. لو حاجة كانت غلطت، الضرر كان ممكن يتنقل للأجيال الجاية."], ["Third, questions were raised about whether the parents had given truly informed consent.", "تالتًا، اتطرحت أسئلة عن إذا كان الأهل وافقوا موافقة حقيقية وهما فاهمين كل حاجة."], ["He was sentenced to three years in prison for illegal medical practice. Yet the technology he used continues to advance rapidly.", "اتحكم عليه بالسجن ٣ سنين بتهمة ممارسة طبية غير قانونية. ومع ذلك، التكنولوجيا اللي استخدمها لسه بتتقدم بسرعة."], ["CRISPR has already been used successfully to treat adults with blood disorders such as sickle cell disease — treatments that do not affect future generations.", "كريسبر اتستخدم بنجاح لعلاج بالغين عندهم أمراض دم زي الأنيميا المنجلية — علاجات مش بتأثر على الأجيال الجاية."], ["Most scientists now agree on a crucial distinction: editing a patient's own cells may be acceptable, but editing embryos crosses an ethical line.", "أغلب العلماء دلوقتي متفقين على فرق مهم: تعديل خلايا المريض نفسه ممكن يبقى مقبول، بس تعديل الأجنة بيعدّي حد أخلاقي."], ["Were that line ever to be crossed legally, it would raise the most difficult question of all: who has the right to decide what a \"better\" human being looks like?", "ولو الحد ده اتعدّى بشكل قانوني في يوم، هيطرح أصعب سؤال فيهم كلهم: مين ليه الحق يقرر الإنسان \"الأحسن\" شكله إيه؟"]], "keys": [["👯", "twins", "two children born at the same time to the same mother"], ["✂️", "CRISPR", "a tool that can cut and change DNA"], ["🛡️", "resistant", "not affected by something harmful"], ["😡", "furious", "extremely angry"], ["⚖️", "sentence", "to give someone an official punishment"], ["🚧", "distinction", "a clear difference between two things"]], "quiz": [{"q": "What did He Jiankui announce in 2018?", "o": ["He had edited the genes of twin babies.", "He had cured cancer.", "He had cloned a sheep."], "a": 0}, {"q": "Why did he edit the genes?", "o": ["to make the girls resistant to HIV", "to change their eye colour", "to make them taller"], "a": 0}, {"q": "How did the scientific community react?", "o": ["with immediate fury", "with celebration", "with no interest"], "a": 0}, {"q": "What could have happened had something gone wrong?", "o": ["The damage could have passed to future generations.", "Nothing at all.", "The girls would become famous."], "a": 0}, {"q": "What was his punishment?", "o": ["three years in prison", "a fine", "nothing"], "a": 0}, {"q": "What distinction do most scientists accept?", "o": ["Editing a patient's cells may be OK; editing embryos is not.", "All gene editing is wrong.", "All gene editing is fine."], "a": 0}]}, "idioms": {"items": [["a guinea pig", "A person used in an experiment.", "فار تجارب", "I don't want to be a guinea pig for a new drug.", "مش عايز أبقى فار تجارب لدوا جديد."], ["back to the drawing board", "To start planning again after a failure.", "نرجع للبداية", "The trial failed, so it's back to the drawing board.", "التجربة فشلت، يبقى نرجع للبداية."], ["push the boundaries", "To go beyond normal limits.", "يتخطى الحدود", "Good science always pushes the boundaries.", "العلم الكويس دايمًا بيتخطى الحدود."], ["a leap in the dark", "An action whose results you cannot predict.", "قفزة في المجهول", "The new treatment is a leap in the dark.", "العلاج الجديد قفزة في المجهول."]], "quiz": [{"q": "The experiment didn't work. It's ___.", "o": ["back to the drawing board", "a guinea pig", "pushing boundaries", "a leap in the dark"], "a": 0}, {"q": "Volunteers in a drug trial are like ___.", "o": ["guinea pigs", "drawing boards", "boundaries", "leaps"], "a": 0}, {"q": "\"A leap in the dark\" is…", "o": ["an action with unpredictable results", "a night-time sport", "a small risk", "a jump over a wall"], "a": 0}, {"q": "Space scientists always ___ of what is possible.", "o": ["push the boundaries", "go back to the drawing board", "leap in the dark", "are guinea pigs"], "a": 0}]}, "phrasal": {"items": [["carry out", "To do or complete (research, an experiment).", "يعمل / ينفّذ", "The team carried out hundreds of experiments.", "الفريق عمل مئات التجارب."], ["rule out", "To decide that something is not possible.", "يستبعد", "Doctors have ruled out a serious illness.", "الدكاترة استبعدوا مرض خطير."], ["pass on / pass down", "To give to the next generation.", "ينقل (للأجيال)", "Some diseases are passed down in families.", "في أمراض بتتنقل في العيلات."], ["break through", "To make an important discovery after difficulty.", "يحقق اختراق", "Researchers finally broke through after ten years.", "الباحثين أخيرًا حققوا اختراق بعد ١٠ سنين."]], "quiz": [{"q": "The lab will ___ more tests next month.", "o": ["carry out", "rule out", "pass down", "break through"], "a": 0}, {"q": "We can't ___ the possibility of side effects.", "o": ["rule out", "carry out", "pass on", "break through"], "a": 0}, {"q": "Eye colour is ___ from parents to children.", "o": ["passed down", "ruled out", "carried out", "broken through"], "a": 0}, {"q": "After years of failure, they finally ___.", "o": ["broke through", "ruled out", "passed down", "carried out"], "a": 0}]}, "slang": {"items": [["mind-blowing", "Extremely impressive or surprising.", "يطيّر العقل", "The images from the new telescope are mind-blowing.", "الصور من التلسكوب الجديد بتطيّر العقل.", "منتشرة جدًا"], ["sketchy", "Suspicious or not trustworthy.", "مش مضمون / مريب", "That miracle pill sounds sketchy.", "الحباية السحرية دي شكلها مش مضمونة.", "عادي"], ["nerd out", "To talk enthusiastically about a geeky subject.", "يندمج في كلام علمي", "We nerded out about black holes for hours.", "اندمجنا في الكلام عن الثقوب السودا لساعات.", "لطيفة"], ["the jury's still out", "People haven't decided yet.", "لسه محدش حسم", "Is coffee healthy? The jury's still out.", "القهوة صحية؟ لسه محدش حسم.", "شبه رسمي"], ["a no-brainer", "A very easy decision.", "قرار سهل جدًا", "Getting vaccinated was a no-brainer for me.", "إني آخد التطعيم كان قرار سهل جدًا.", "عادي جدًا"]], "quiz": [{"q": "A very easy decision = ___.", "o": ["a no-brainer", "sketchy", "mind-blowing", "nerd out"], "a": 0}, {"q": "A website selling \"miracle cures\" seems ___.", "o": ["sketchy", "mind-blowing", "a no-brainer", "nerdy"], "a": 0}, {"q": "\"The jury's still out\" means…", "o": ["people haven't decided yet", "the court is closed", "everyone agrees", "it is illegal"], "a": 0}, {"q": "When you talk excitedly about science, you ___.", "o": ["nerd out", "blow your mind", "get sketchy", "judge"], "a": 0}]}, "story": {"title": "The Choice", "ar": "الاختيار", "g": "f", "lines": [["Dr Amira Fouad had spent fifteen years searching for a cure for the rare disease that had killed her brother when he was nine.", "دكتورة أميرة فؤاد قضت ١٥ سنة بتدوّر على علاج للمرض النادر اللي قتل أخوها وهو عنده ٩ سنين."], ["One night in her lab, she finally broke through. The treatment worked perfectly on mice. She cried with joy.", "في ليلة في معملها، أخيرًا حققت الاختراق. العلاج اشتغل بشكل ممتاز على الفيران. عيطت من الفرحة."], ["But testing on humans would take at least seven more years. Children with the disease rarely lived that long.", "بس التجارب على البشر هتاخد ٧ سنين كمان على الأقل. والأطفال المصابين نادرًا ما بيعيشوا المدة دي."], ["A week later, a desperate mother appeared at her door with her six-year-old son, Yassin. \"Please,\" she said. \"I've heard about your discovery. He has months left.\"", "بعد أسبوع، أم يائسة ظهرت قدام بابها ومعاها ابنها ياسين عنده ٦ سنين. \"أرجوكي،\" قالت. \"سمعت عن اكتشافك. فاضله شهور.\""], ["Amira knew the rules. Using an untested treatment on a child was illegal. Should anything go wrong, she would lose her career — and Yassin could die sooner.", "أميرة كانت عارفة القواعد. استخدام علاج متجربش على طفل ممنوع. ولو أي حاجة غلطت، هتخسر مستقبلها — وياسين ممكن يموت أسرع."], ["She looked at the boy and saw her brother. Had someone offered her family this chance, would they have taken it? She knew the answer.", "بصت على الولد وشافت أخوها. لو حد كان عرض على عيلتها الفرصة دي، كانوا هياخدوها؟ كانت عارفة الإجابة."], ["Instead of acting alone, she spent three sleepless weeks writing to ethics committees, hospitals and the Ministry of Health.", "بدل ما تتصرف لوحدها، قضت ٣ أسابيع من غير نوم بتكتب للجان الأخلاقيات والمستشفيات ووزارة الصحة."], ["Finally, under a special \"compassionate use\" programme, Yassin was allowed to receive the treatment with full medical supervision and his parents' informed consent.", "أخيرًا، تحت برنامج خاص اسمه \"الاستخدام الرحيم\"، ياسين اتسمح له ياخد العلاج تحت إشراف طبي كامل وبموافقة أهله وهما فاهمين كل حاجة."], ["The months that followed were the longest of her life. Then, slowly, Yassin began to get stronger.", "الشهور اللي بعدها كانت أطول شهور في حياتها. وبعدين، شوية بشوية، ياسين بدأ يقوى."], ["Years later, Yassin, now a medical student, asked her why she hadn't simply given him the medicine that first night. \"Because,\" she said, \"the right thing done the wrong way can still be wrong.\"", "بعد سنين، ياسين، اللي بقى طالب طب، سألها ليه مكانتش ادته الدوا من أول ليلة وخلاص. \"عشان،\" قالت، \"الحاجة الصح لما تتعمل بطريقة غلط ممكن تفضل غلط.\""]], "quiz": [{"q": "Why was Dr Amira searching for a cure?", "o": ["The disease had killed her brother.", "She wanted money.", "Her boss told her to."], "a": 0}, {"q": "Why couldn't the treatment be used immediately?", "o": ["Human testing would take seven more years.", "It didn't work on mice.", "It was too expensive."], "a": 0}, {"q": "What did Yassin's mother ask?", "o": ["for her son to receive the treatment", "for money", "for a job"], "a": 0}, {"q": "What did Amira do instead of acting alone?", "o": ["She wrote to ethics committees and the ministry.", "She gave him the medicine secretly.", "She refused to help."], "a": 0}, {"q": "What did Amira tell Yassin years later?", "o": ["The right thing done the wrong way can still be wrong.", "Rules are not important.", "She regretted helping him."], "a": 0}]}, "challenge": {"title": "Where Is the Line?", "ar": "الحد فين؟ — جاوب وسجّل", "qs": ["Should gene editing be used to prevent serious diseases? What about to choose appearance?", "Is animal testing justified if it saves human lives?", "Had you been Dr Amira, what would you have done? Use conditional inversion.", "Should people be allowed to sell their organs?", "Would you want to live to 150 if science made it possible?", "Who should own your genetic data — you, your doctor or the company that tests it?", "Were you given unlimited money for research, what would you study?", "Is it ever right to break the rules for the greater good?", "Should vaccines be compulsory?", "Describe a scientific breakthrough you think will happen in your lifetime."]}, "games": {"pairs": [["🧬", "gene editing"], ["💉", "vaccine"], ["🐑", "cloning"], ["🔬", "breakthrough"], ["🐀", "animal testing"], ["🧪", "clinical trial"]], "spell": [["🧫", "embryo"], ["⚖️", "bioethics"], ["🛡️", "safeguards"], ["🧾", "regulation"], ["🧩", "unforeseen"], ["💊", "cure"], ["🦠", "pathogen"], ["📈", "outweigh"]], "speed": [["Had I known, I would have helped.", true], ["Hadn't I known, I would have helped.", false], ["Should you need help, call me.", true], ["Were I you, I would wait.", true], ["Were it not for vaccines, millions would die.", true], ["If had I known, I would have come.", false], ["Had it not been for her, I would have failed.", true], ["Should the results be positive, we will publish.", true], ["Were they to approve it, labs would open.", true], ["Had they test it, nobody would be hurt.", false], ["Informed consent means agreeing with full information.", true], ["A breakthrough is a big failure.", false], ["\"A guinea pig\" is a person used in an experiment.", true], ["\"Rule out\" means to exclude a possibility.", true], ["\"Sketchy\" means trustworthy.", false], ["\"A no-brainer\" is a very easy decision.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "A medicine that protects against a disease = a ___.", "o": ["vaccine", "pathogen", "trial"], "a": 0, "pic": "💉"}, {"q": "An important new discovery = a ___.", "o": ["breakthrough", "boundary", "risk"], "a": 0, "pic": "🔬"}, {"q": "Agreement after understanding the risks = informed ___.", "o": ["consent", "cure", "clone"], "a": 0, "pic": "🤝"}, {"q": "To be greater in importance than = to ___.", "o": ["outweigh", "rule out", "clone"], "a": 0, "pic": "⚖️"}, {"q": "Not expected or predicted = ___.", "o": ["unforeseen", "resistant", "informed"], "a": 0, "pic": "🧩"}, {"q": "\"تجربة سريرية\" in English is…", "o": ["clinical trial", "clinic visit", "clean test"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "___ we left earlier, we wouldn't have missed the train.", "o": ["Had", "Have", "Were"], "a": 0}, {"q": "___ you require further information, please contact us.", "o": ["Should", "Had", "Were"], "a": 0}, {"q": "Were I ___ the minister, I would change the law.", "o": ["to become", "become", "becoming"], "a": 0}, {"q": "Had it not been ___ the seatbelt, he would have died.", "o": ["for", "of", "by"], "a": 0}, {"q": "___ it not for your help, I would be lost.", "o": ["Were", "Had", "Should"], "a": 0}, {"q": "Which is correct?", "o": ["Had she not studied, she would have failed.", "Hadn't she studied, she would have failed.", "Had she not study, she would have failed."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"Would you join a drug trial?\" — Best answer:", "o": ["Only if the risks were explained — I don't want to be a guinea pig.", "Trial is a court.", "Yes, I drug."], "a": 0}, {"q": "\"The experiment failed.\" — Best answer:", "o": ["Well, it's back to the drawing board.", "It's a no-brainer.", "It's mind-blowing."], "a": 0}, {"q": "\"Is it healthy to drink coffee every day?\" — Best answer:", "o": ["The jury's still out.", "The jury is coffee.", "Coffee is out."], "a": 0}, {"q": "\"This website sells pills that cure everything!\" — Best answer:", "o": ["That sounds sketchy.", "That sounds like a breakthrough.", "Buy ten!"], "a": 0}, {"q": "\"Why didn't you warn me?\" — Best answer:", "o": ["Had I known, I would have told you.", "Had I know, I told you.", "If had I known."], "a": 0}, {"q": "Formal email ending — Best:", "o": ["Should you have any questions, please do not hesitate to contact me.", "Any questions? Bye.", "Had you questions, call."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["In 1928, Alexander Fleming returned from holiday to find mould growing on one of his experiments.", "He noticed that the bacteria around the mould had died.", "Had he thrown the dish away, he would never have discovered penicillin.", "Penicillin became the world's first widely used antibiotic and has saved millions of lives.", "Today, however, scientists warn that overuse of antibiotics is making bacteria resistant."], "qs": [{"q": "What did Fleming find when he returned?", "o": ["mould growing on an experiment", "a broken microscope", "a new animal"], "a": 0}, {"q": "What happened to the bacteria near the mould?", "o": ["They had died.", "They had grown.", "They had changed colour."], "a": 0}, {"q": "What would have happened had he thrown the dish away?", "o": ["He would not have discovered penicillin.", "He would have won a prize.", "Nothing."], "a": 0}, {"q": "What is penicillin?", "o": ["the first widely used antibiotic", "a vaccine", "a virus"], "a": 0}, {"q": "What do scientists warn about today?", "o": ["overuse of antibiotics", "too little mould", "expensive holidays"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write a formal paragraph (100–150 words): \"Should gene editing of human embryos be allowed?\" Present both sides and your view. Use at least two inverted conditionals (Had…, Were…, Should…).", "promptAr": "اكتب فقرة رسمية (١٠٠–١٥٠ كلمة): \"تعديل جينات الأجنة البشرية ينفع يتسمح؟\" اعرض الرأيين ورأيك، واستخدم شرطين مقلوبين على الأقل.", "checks": [["🧬", "Science words", "x", "\\b(gene|genes|genetic|embryo|embryos|disease|diseases|science|scientists|ethical|unethical|risk|risks|cure)\\b"], ["🔄", "Conditional inversion", "x", "(^|[.!?]\\s+|,\\s+)(had|were|should)\\s+(i|you|he|she|it|we|they|scientists|parents|the|this|that|governments)\\b"], ["⚖️", "Balance", "x", "\\b(however|on the other hand|nevertheless|whereas|although|admittedly)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "6tw_JVz_IEc", "title": "How CRISPR Lets You Edit DNA", "ar": "إزاي كريسبر بيخليك تعدّل الـDNA — TED-Ed", "by": "TED-Ed · Andrea M. Henle", "lines": [["Every living thing, from tiny single-celled organisms to the largest animals, is defined by its genes.", "كل كائن حي، من الكائنات وحيدة الخلية الصغيرة لأكبر الحيوانات، بيتحدد بجيناته."], ["DNA works like an instruction manual, written with four chemical bases in a specific order.", "الـDNA بيشتغل زي كتالوج تعليمات، مكتوب بأربع قواعد كيميائية بترتيب معين."], ["Gene-editing tools such as CRISPR now allow scientists to change an organism's features in record time.", "أدوات تعديل الجينات زي كريسبر بقت بتسمح للعلماء يغيروا صفات الكائن في وقت قياسي."], ["CRISPR comes from nature: it is part of a defence system that bacteria use against viruses.", "كريسبر جاي من الطبيعة: هو جزء من نظام دفاع بتستخدمه البكتيريا ضد الفيروسات."], ["The system uses repeated DNA sequences and special proteins called Cas, which cut and destroy viral DNA.", "النظام بيستخدم تسلسلات DNA متكررة وبروتينات خاصة اسمها Cas، بتقطع الـDNA بتاع الفيروس وتدمره."], ["Scientists hijacked this system: they design a \"guide RNA\" that leads the Cas9 protein to a chosen gene.", "العلماء استغلوا النظام ده: بيصمموا \"RNA مرشد\" بيوصّل بروتين Cas9 لجين معين."], ["Cas9 then cuts the DNA at exactly the right place, so almost any gene in almost any organism can be targeted.", "وبعدين Cas9 بيقطع الـDNA في المكان الصح بالظبط، فتقريبًا أي جين في أي كائن ممكن يتستهدف."], ["After the cut, the cell repairs its DNA; its quick method often makes mistakes that switch the gene off.", "بعد القطع، الخلية بتصلّح الـDNA بتاعها؛ وطريقتها السريعة غالبًا بتغلط وبتعطّل الجين."], ["Scientists can also provide a template so the cell copies a new, precise sequence into the gap.", "العلماء كمان يقدروا يدّوا قالب عشان الخلية تنسخ تسلسل جديد ودقيق في الفراغ."], ["Possible uses include drought-resistant crops, stopping disease outbreaks and curing genetic diseases.", "الاستخدامات الممكنة فيها محاصيل بتستحمل الجفاف، ووقف تفشي الأمراض، وعلاج الأمراض الوراثية."], ["But CRISPR doesn't always make the intended change, and its long-term effects are still unknown.", "بس كريسبر مش دايمًا بيعمل التغيير المقصود، وتأثيراته طويلة المدى لسه مش معروفة."], ["These limitations raise serious ethical questions, especially about editing humans and unintended consequences.", "الحدود دي بتطرح أسئلة أخلاقية جدية، خصوصًا عن تعديل البشر والعواقب اللي مش مقصودة."]], "words": ["single-celled", "instruction manual", "gene-editing", "record time", "defence system", "proteins", "hijacked", "guide RNA", "template", "drought-resistant", "long-term effects", "ethical questions"], "quiz": [{"q": "What is DNA compared to?", "o": ["an instruction manual", "a computer", "a map"], "a": 0}, {"q": "Where does CRISPR come from?", "o": ["a defence system in bacteria", "a laboratory accident", "human blood"], "a": 0}, {"q": "What does the guide RNA do?", "o": ["leads Cas9 to the chosen gene", "destroys the cell", "creates new bacteria"], "a": 0}, {"q": "What can happen when the cell repairs the cut quickly?", "o": ["It may make mistakes that switch the gene off.", "It becomes a virus.", "Nothing ever changes."], "a": 0}, {"q": "Which is a possible use of CRISPR?", "o": ["drought-resistant crops", "faster internet", "cheaper cars"], "a": 0}, {"q": "Why does CRISPR raise ethical questions?", "o": ["Its long-term effects are unknown and it may have unintended results.", "It is too cheap.", "It is too slow."], "a": 0}]}]}, "5": {"n": 5, "title": "Media and Misinformation", "ar": "الإعلام والمعلومات المضللة — Advanced Discourse Markers", "icon": "📰", "cover": "img/c1/u5.jpg", "intro": "اتكلم عن الأخبار الكاذبة والإشاعات وصحافة المواطن وإزاي تتأكد من المعلومة، واستخدم أدوات الربط المتقدمة عشان تبني حجة قوية: Admittedly / Be that as it may / Nonetheless / In light of / Not to mention.", "videos": [{"id": "c1v5", "title": "Is It Real?", "ar": "هو ده حقيقي؟ — منى وزياد", "src": "video/c1/u5v1.mp4", "poster": "img/c1/u5v1.jpg", "sp": {"a": {"n": "Mona", "g": "f"}, "b": {"n": "Ziad", "g": "m"}}, "lines": [["b", "Mona, look at this! A video of a shark swimming in the street after the floods. It's got two million views!", "منى، بصي ده! فيديو لقرش بيعوم في الشارع بعد الفيضانات. عليه ٢ مليون مشاهدة!"], ["a", "Hmm, I've seen that before. Admittedly, it looks real, but it's been shared after almost every flood for years.", "امم، شفته قبل كده. لازم أعترف إنه شكله حقيقي، بس بيتنشر بعد كل فيضان تقريبًا من سنين."], ["b", "Really? But my cousin shared it, and he's usually careful.", "بجد؟ بس ابن عمي شيّره، وهو عادة حريص."], ["a", "Be that as it may, even careful people get fooled. That's exactly how fake news spreads.", "ولو كان كده، حتى الناس الحريصين بيتضحك عليهم. وده بالظبط إزاي الأخبار الكاذبة بتنتشر."], ["b", "So how do you check if something is real?", "طب إزاي تتأكدي إن حاجة حقيقية؟"], ["a", "First, I look for the original source. Then I do a reverse image search. Not to mention checking whether trusted news sites have reported it.", "الأول، بدوّر على المصدر الأصلي. وبعدين بعمل بحث عكسي بالصورة. غير إني بشوف إذا كانت مواقع أخبار موثوقة نشرته."], ["b", "That sounds like a lot of work just to share a video.", "ده شكله مجهود كبير عشان أشيّر فيديو."], ["a", "It is. Nonetheless, sharing false information can cause real harm — panic, hatred, even violence.", "فعلًا. ومع ذلك، نشر معلومات غلط ممكن يعمل ضرر حقيقي — ذعر وكراهية، وحتى عنف."], ["b", "I suppose so. Last year a fake rumour about a medicine shortage made people panic-buy everything.", "أظن كده. السنة اللي فاتت إشاعة كاذبة عن نقص دوا خلت الناس تشتري كل حاجة من الخوف."], ["a", "Exactly. In light of that, I think we all have a responsibility before we press 'share'.", "بالظبط. وفي ضوء ده، أنا شايفة إن علينا كلنا مسؤولية قبل ما ندوس \"شير\"."], ["b", "Fair enough. I'll tell my cousin. On second thoughts, maybe I'll just send him the original source!", "عندك حق. هقول لابن عمي. أو أقولك، يمكن أبعتله المصدر الأصلي وخلاص!"], ["a", "Good idea. And remember: if a headline makes you very angry or very excited, that's the moment to stop and check.", "فكرة كويسة. وافتكر: لو عنوان خلاك متعصب جدًا أو متحمس جدًا، دي اللحظة اللي توقف فيها وتتأكد."]], "quiz": [{"q": "What does the viral video show?", "o": ["a shark swimming in the street", "a flying car", "a famous singer"], "a": 0}, {"q": "What does Mona say about the video?", "o": ["It's been shared after floods for years.", "It's brand new.", "It's from a film."], "a": 0}, {"q": "What is the first thing Mona does to check information?", "o": ["look for the original source", "ask her friends", "share it"], "a": 0}, {"q": "What happened last year because of a rumour?", "o": ["People panic-bought everything.", "Schools closed.", "A shark was found."], "a": 0}, {"q": "When should you stop and check, according to Mona?", "o": ["when a headline makes you very angry or excited", "only at night", "never"], "a": 0}], "fill": [[0, "views"], [1, "Admittedly"], [3, "Be that as it may"], [3, "fake news"], [4, "check"], [5, "original source"], [5, "reverse image search"], [5, "Not to mention"], [7, "Nonetheless"], [8, "rumour"], [9, "In light of"], [10, "On second thoughts"]]}], "vocab": [{"t": "News & media", "ar": "الأخبار والإعلام", "items": [["📰", "headline", "The headline was misleading."], ["🗞️", "journalism", "Good journalism checks every fact."], ["📡", "mainstream media", "Some people distrust the mainstream media."], ["📱", "citizen journalist", "A citizen journalist filmed the event."], ["🔗", "source", "Always check the source."], ["🎙️", "press", "The press reported the scandal."], ["📺", "coverage", "The coverage of the election was biased."], ["✍️", "editorial", "The editorial criticised the government."]]}, {"t": "Misinformation", "ar": "المعلومات المضللة", "items": [["🤥", "fake news", "Fake news spreads faster than the truth."], ["🗣️", "rumour", "The rumour turned out to be false."], ["🎭", "misinformation", "Misinformation about health can be dangerous."], ["🎯", "disinformation", "Disinformation is spread deliberately."], ["🧲", "clickbait", "Clickbait headlines exaggerate."], ["🫧", "echo chamber", "Social media can create echo chambers."], ["⚖️", "biased", "The report was clearly biased."], ["🌀", "conspiracy theory", "He believes every conspiracy theory."]]}, {"t": "Checking the facts", "ar": "التأكد من الحقائق", "items": [["✅", "fact-check", "Always fact-check before sharing."], ["🔍", "verify", "Journalists must verify their information."], ["🏛️", "credible", "Use credible sources."], ["🔄", "reverse image search", "A reverse image search shows where a photo came from."], ["🧠", "media literacy", "Media literacy should be taught at school."], ["📊", "evidence", "There is no evidence for that claim."], ["🚨", "debunk", "Scientists debunked the myth."], ["🙊", "go viral", "The video went viral overnight."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["Where do you usually get your news?", "بتجيب أخبارك منين عادة؟", "Mostly from news apps and a few journalists I trust."], ["Have you ever believed a fake news story?", "صدقت خبر كاذب قبل كده؟", "Yes, a celebrity death rumour."], ["Why does fake news spread so quickly?", "ليه الأخبار الكاذبة بتنتشر بسرعة؟", "Because it's shocking and emotional."], ["Do you trust the mainstream media?", "بتثق في الإعلام الرسمي؟", "Partly — I compare several sources."], ["How do you check if a story is true?", "بتتأكد إزاي إن الخبر صح؟", "I look for the original source and other reports."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Should social media companies remove false information?", "شركات السوشيال ميديا تمسح المعلومات الكاذبة؟", "Yes, but who decides what is false?"], ["Is citizen journalism good or dangerous?", "صحافة المواطن كويسة ولا خطيرة؟", "Both — it shows the truth but can spread rumours."], ["Should media literacy be taught at school?", "التربية الإعلامية تتدرّس في المدارس؟", "Absolutely, from primary school."], ["Are we living in echo chambers?", "إحنا عايشين في غرف صدى؟", "Mostly — algorithms show us what we already like."], ["Should spreading fake news be a crime?", "نشر الأخبار الكاذبة يبقى جريمة؟", "Deliberate disinformation, maybe."]]}], "grammar": {"title": "Advanced Discourse Markers", "ar": "أدوات الربط المتقدمة — Admittedly / Be that as it may / Nonetheless", "blocks": [{"type": "intro", "en": "Discourse markers organise your ideas and show your attitude. At C1, you need markers that concede a point, contrast strongly, add information and draw conclusions — in both speaking and writing.", "ar": "أدوات الربط بتنظّم أفكارك وبتوضح موقفك. في C1 محتاج أدوات بتعترف بنقطة، وبتعارض بقوة، وبتضيف معلومات، وبتوصل لنتيجة — في الكلام والكتابة."}, {"type": "big", "items": [{"v": "Admittedly / Granted / Of course…", "p": "concede (admit a point)", "c": 1, "eg": ["Admittedly, it looks real.", "Granted, the app is useful, but it collects data.", "Of course, not all news is fake."]}, {"v": "Be that as it may / Nonetheless / Even so", "p": "strong contrast", "c": 2, "eg": ["Be that as it may, even careful people get fooled.", "It is a lot of work. Nonetheless, it matters.", "It's risky. Even so, I'll try."]}, {"v": "Not to mention / In light of / Consequently", "p": "add / reason / result", "c": 3, "eg": ["Not to mention checking trusted news sites.", "In light of that, we have a responsibility.", "The story was false. Consequently, the editor resigned."]}]}, {"type": "table", "title": "📋 Markers by function", "head": ["Function", "Markers"], "rows": [["Concede", "Admittedly, Granted, Of course, It is true that…"], ["Contrast", "Nonetheless, Nevertheless, Be that as it may, Even so, That said"], ["Add", "Furthermore, Moreover, Not to mention, On top of that"], ["Cause / reason", "In light of, Owing to, Given that"], ["Result", "Consequently, Hence, As a result, Thus"], ["Change your mind", "On second thoughts, Come to think of it"]]}, {"type": "uses", "title": "💡 Concession pattern", "ar": "نمط الاعتراف ثم الرد", "items": [["1️⃣", "Admit a point", "Admittedly, social media spreads news quickly.", "اعترف"], ["2️⃣", "Contrast", "Nonetheless, much of it is unverified.", "ارجع لرأيك"], ["3️⃣", "Support", "Not to mention the rise of deepfakes.", "ادعم"], ["4️⃣", "Conclude", "Consequently, media literacy is essential.", "استنتج"]]}, {"type": "tip", "en": "'Nonetheless' and 'Consequently' join ideas across sentences — use a full stop or semicolon before them, not just a comma. 'In light of' and 'owing to' are followed by a noun: In light of the evidence ✔ (not In light of the evidence is clear ✖).", "ar": "Nonetheless وConsequently بتربط جملتين — حط قبلهم نقطة أو فاصلة منقوطة. وIn light of وowing to بعدهم اسم."}]}, "exercises": [{"type": "mcq", "title": "Discourse Markers — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "___, it looks real, but it has been shared for years.", "o": ["Admittedly", "Consequently", "Hence", "Moreover"], "a": 0}, {"q": "It takes time to check. ___, it is important.", "o": ["Nonetheless", "Consequently", "Furthermore", "Admittedly"], "a": 0}, {"q": "___ that as it may, careful people get fooled too.", "o": ["Be", "Being", "It be", "Was"], "a": 0}, {"q": "Check the source, ___ trusted news sites.", "o": ["not to mention", "in light of", "hence", "granted"], "a": 0}, {"q": "___ the evidence, the article was withdrawn.", "o": ["In light of", "Admittedly", "Even so", "Not to mention"], "a": 0}, {"q": "The story was false. ___, the editor resigned.", "o": ["Consequently", "Admittedly", "Granted", "Even so"], "a": 0}, {"q": "___, the app is useful, but it collects too much data.", "o": ["Granted", "Hence", "Consequently", "In light of"], "a": 0}, {"q": "I'll call him. On second ___, I'll send an email.", "o": ["thoughts", "thinking", "thought it", "minds"], "a": 0}, {"q": "Which marker shows a RESULT?", "o": ["hence", "admittedly", "granted", "even so"], "a": 0}, {"q": "Which marker ADMITS a point?", "o": ["Admittedly", "Consequently", "Moreover", "Hence"], "a": 0}]}, {"type": "mcq", "title": "Choose the function", "ar": "اختار الوظيفة", "items": [{"q": "\"Nevertheless\" = ___", "o": ["contrast", "result"], "a": 0}, {"q": "\"Furthermore\" = ___", "o": ["adding", "conceding"], "a": 0}, {"q": "\"Owing to\" = ___", "o": ["reason", "contrast"], "a": 0}, {"q": "\"Thus\" = ___", "o": ["result", "adding"], "a": 0}, {"q": "\"Granted\" = ___", "o": ["conceding a point", "giving a result"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["Admittedly,", "it looks real,", "but", "it's fake"], "a": [0, 1, 2, 3]}, {"c": ["Be that", "as it may,", "we must", "check it"], "a": [0, 1, 2, 3]}, {"c": ["In light of", "the evidence,", "he", "resigned"], "a": [0, 1, 2, 3]}, {"c": ["It's hard.", "Nonetheless,", "it's", "important"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "Why Lies Travel Faster", "ar": "ليه الكدب بيسافر أسرع", "g": "f", "lines": [["\"A lie can travel halfway around the world while the truth is putting on its shoes.\" This old saying has never been more relevant than in the age of social media.", "\"الكدبة ممكن تلف نص العالم والحقيقة لسه بتلبس جزمتها.\" المقولة القديمة دي عمرها ما كانت مناسبة أكتر من عصر السوشيال ميديا."], ["In 2018, researchers at MIT analysed more than 126,000 stories shared on Twitter over ten years. Their findings were striking.", "سنة ٢٠١٨، باحثين في معهد MIT حللوا أكتر من ١٢٦ ألف قصة اتشيّرت على تويتر على مدار ١٠ سنين. والنتايج كانت لافتة."], ["False stories were 70% more likely to be shared than true ones, and they reached people about six times faster.", "القصص الكاذبة كانت أكتر عرضة للمشاركة بنسبة ٧٠٪ من الحقيقية، ووصلت للناس أسرع بحوالي ٦ مرات."], ["Admittedly, automated \"bot\" accounts played a part. Nonetheless, the researchers concluded that humans, not bots, were mainly responsible for spreading the lies.", "لازم نعترف إن الحسابات الآلية \"البوتس\" كان ليها دور. ومع ذلك، الباحثين استنتجوا إن البشر، مش البوتس، هما المسؤولين بشكل أساسي عن نشر الأكاذيب."], ["Why? False news tends to be more surprising and emotional. It triggers fear, anger or excitement — feelings that make us want to share immediately, without thinking.", "ليه؟ الأخبار الكاذبة غالبًا بتبقى مفاجئة وعاطفية أكتر. بتثير الخوف أو الغضب أو الحماس — مشاعر بتخلينا عايزين نشيّر على طول، من غير تفكير."], ["The truth, on the other hand, is often complicated, uncertain and, frankly, less exciting.", "الحقيقة، من ناحية تانية، غالبًا بتبقى معقدة ومش أكيدة، وبصراحة، أقل إثارة."], ["Algorithms make the problem worse. Platforms are designed to show us content that keeps us engaged, and few things are as engaging as outrage. Consequently, many users end up in echo chambers.", "الخوارزميات بتزوّد المشكلة. المنصات متصممة عشان تورينا محتوى يخلينا متفاعلين، وقليل من الحاجات بيشد زي الغضب. ونتيجة لده، مستخدمين كتير بيلاقوا نفسهم في غرف صدى."], ["Be that as it may, there are reasons for hope. Fact-checking organisations have grown rapidly, and some countries, such as Finland, teach media literacy from primary school.", "ومع ده كله، في أسباب للأمل. منظمات التحقق من الأخبار كبرت بسرعة، وبعض الدول، زي فنلندا، بتعلّم التربية الإعلامية من ابتدائي."], ["Studies suggest that simply asking people to consider whether a headline is accurate before sharing it significantly reduces the spread of false news.", "الدراسات بتقول إن مجرد إنك تطلب من الناس يفكروا إذا كان العنوان دقيق قبل ما يشيّروه بيقلل انتشار الأخبار الكاذبة بشكل كبير."], ["In other words, the most powerful fact-checker may be the one we already carry with us: a moment of doubt.", "بمعنى تاني، أقوى مدقق للحقائق ممكن يكون اللي معانا أصلًا: لحظة شك."]], "keys": [["🎓", "MIT", "a famous American university of technology"], ["😲", "striking", "very noticeable or surprising"], ["🤖", "bot", "an automated computer program that acts like a user"], ["⚡", "trigger", "to cause a strong reaction"], ["😡", "outrage", "a strong feeling of anger and shock"], ["🤔", "doubt", "a feeling of not being sure"]], "quiz": [{"q": "How many stories did MIT researchers analyse?", "o": ["more than 126,000", "about 1,000", "exactly 70"], "a": 0}, {"q": "How much faster did false stories reach people?", "o": ["about six times faster", "twice as fast", "at the same speed"], "a": 0}, {"q": "Who was mainly responsible for spreading lies?", "o": ["humans", "bots", "journalists"], "a": 0}, {"q": "Why does false news spread more?", "o": ["It is more surprising and emotional.", "It is longer.", "It is always true."], "a": 0}, {"q": "Which country teaches media literacy from primary school?", "o": ["Finland", "Brazil", "Japan"], "a": 0}, {"q": "What is \"the most powerful fact-checker\", according to the writer?", "o": ["a moment of doubt", "a computer program", "the government"], "a": 0}]}, "idioms": {"items": [["take something with a pinch of salt", "To not completely believe something.", "متصدقش كل حاجة", "Take online reviews with a pinch of salt.", "متصدقش التقييمات أونلاين بالكامل."], ["from the horse's mouth", "Directly from the original source.", "من المصدر نفسه", "I heard it straight from the horse's mouth — the manager told me.", "سمعتها من المصدر نفسه — المدير قالي."], ["spread like wildfire", "To spread very quickly.", "ينتشر زي النار في الهشيم", "The rumour spread like wildfire.", "الإشاعة انتشرت زي النار في الهشيم."], ["a storm in a teacup", "A lot of anger about something unimportant.", "زوبعة في فنجان", "The scandal was just a storm in a teacup.", "الفضيحة كانت مجرد زوبعة في فنجان."]], "quiz": [{"q": "The news ___ — everyone knew within an hour.", "o": ["spread like wildfire", "was a pinch of salt", "was from the horse's mouth", "was a teacup"], "a": 0}, {"q": "I don't fully believe him. I take what he says ___.", "o": ["with a pinch of salt", "like wildfire", "from the horse's mouth", "in a teacup"], "a": 0}, {"q": "\"From the horse's mouth\" means…", "o": ["directly from the original source", "from an animal", "a rumour", "a joke"], "a": 0}, {"q": "Everyone was angry for a day, then forgot. It was ___.", "o": ["a storm in a teacup", "wildfire", "a pinch of salt", "the horse's mouth"], "a": 0}]}, "phrasal": {"items": [["make up", "To invent a story or information.", "يألّف / يخترع", "The journalist made up the whole interview.", "الصحفي ألّف الحوار كله."], ["look into", "To investigate.", "يحقق في / يبص في", "The police are looking into the leak.", "البوليس بيحقق في التسريب."], ["play down", "To make something seem less important.", "يقلل من أهمية", "The company played down the problem.", "الشركة قللت من أهمية المشكلة."], ["blow up", "To become a big issue suddenly (also: exaggerate).", "يكبر فجأة / يتضخم", "A small comment blew up into a national debate.", "تعليق صغير اتضخم وبقى نقاش على مستوى البلد."]], "quiz": [{"q": "The minister tried to ___ the scandal, saying it was \"nothing\".", "o": ["play down", "make up", "blow up", "look into"], "a": 0}, {"q": "Journalists are ___ the source of the photo.", "o": ["looking into", "playing down", "making up", "blowing up"], "a": 0}, {"q": "The story wasn't true — he ___ it ___.", "o": ["made / up", "looked / into", "played / down", "blew / up"], "a": 0}, {"q": "One tweet ___ into an international argument.", "o": ["blew up", "made up", "looked into", "played down"], "a": 0}]}, "slang": {"items": [["cap / no cap", "A lie / no lie, seriously.", "كدب / بجد من غير كدب", "He says he met the president? That's cap.", "بيقول قابل الرئيس؟ ده كدب.", "سلانج Gen Z"], ["receipts", "Proof or evidence (screenshots, links).", "إثباتات", "You say she said that? Show me the receipts.", "بتقول إنها قالت كده؟ وريني الإثبات.", "منتشرة على السوشيال"], ["sus", "Suspicious.", "مريب / مش مريح", "That account with no photo is kind of sus.", "الحساب اللي مفيهوش صورة ده مريب شوية.", "منتشرة جدًا"], ["ratio'd", "When a reply gets more likes than the original post (people disagree).", "اتعمله ريشيو (الرد أقوى من البوست)", "His fake claim got ratio'd in minutes.", "ادعاؤه الكاذب اتعمله ريشيو في دقايق.", "من تويتر"], ["doomscrolling", "Scrolling through bad news for a long time.", "سكرول على الأخبار السيئة", "Stop doomscrolling and go to sleep.", "بطّل سكرول على الأخبار السيئة ونام.", "مصطلح حديث"]], "quiz": [{"q": "Spending hours reading bad news = ___.", "o": ["doomscrolling", "receipts", "cap", "sus"], "a": 0}, {"q": "\"Show me the receipts\" means…", "o": ["show me the proof", "show me the bill", "show me the shop", "pay me back"], "a": 0}, {"q": "\"That's cap\" means…", "o": ["That's a lie.", "That's a hat.", "That's true.", "That's expensive."], "a": 0}, {"q": "Something suspicious is ___.", "o": ["sus", "ratio'd", "cap", "receipts"], "a": 0}]}, "story": {"title": "The Photo That Wasn't", "ar": "الصورة اللي مكانتش", "g": "m", "lines": [["Nadine was a junior reporter at a small online newspaper. One evening, a photo appeared in her feed: a famous historic mosque in flames.", "نادين كانت صحفية صغيرة في جريدة أونلاين صغيرة. في ليلة، صورة ظهرت قدامها: جامع تاريخي مشهور والنار فيه."], ["Within minutes, it had been shared fifty thousand times. Angry comments were pouring in. Her editor called: \"Publish it now — every other site already has!\"", "في دقايق، اتشيّرت ٥٠ ألف مرة. التعليقات الغاضبة كانت نازلة زي المطر. رئيس التحرير كلمها: \"انشريها دلوقتي — كل المواقع التانية نشرتها!\""], ["Admittedly, the photo looked convincing. Nonetheless, something felt sus. The smoke was strangely perfect, and the sky looked like the wrong time of day.", "لازم نعترف إن الصورة كانت مقنعة. ومع ذلك، في حاجة كانت مريبة. الدخان كان مثالي بشكل غريب، والسما كان شكلها في وقت غلط من اليوم."], ["\"Give me fifteen minutes,\" she said. Her editor was furious. \"In fifteen minutes, we'll be the only site without the story!\"", "\"اديني ربع ساعة،\" قالت. رئيس التحرير اتعصب. \"بعد ربع ساعة، هنبقى الموقع الوحيد اللي مفيهوش الخبر!\""], ["She did a reverse image search. Nothing. She zoomed in and noticed that the writing on a shop sign was meaningless — a classic sign of an AI-generated image.", "عملت بحث عكسي بالصورة. مفيش حاجة. قرّبت ولاحظت إن الكلام على يافطة محل مالوش معنى — علامة كلاسيكية لصورة معمولة بالذكاء الاصطناعي."], ["Then she called the mosque directly. A sleepy guard answered. \"Fire? No, madam. Everything is quiet. I'm sitting right outside.\"", "وبعدين كلّمت الجامع مباشرة. حارس نعسان رد. \"حريقة؟ لا يا فندم. كل حاجة هادية. أنا قاعد برة بالظبط.\""], ["By then, the rumour had spread like wildfire. Crowds were gathering, and some people were blaming certain groups, which was making the situation dangerous.", "لحد ساعتها، الإشاعة كانت انتشرت زي النار في الهشيم. الناس بدأت تتجمع، وفي ناس بيلوموا مجموعات معينة، وده خلى الموقف خطير."], ["Nadine published a different story: \"The mosque is NOT on fire — the viral image is fake.\" She included the guard's words and the evidence.", "نادين نشرت خبر مختلف: \"الجامع مش بيتحرق — الصورة المنتشرة مزيفة.\" وحطت كلام الحارس والإثباتات."], ["Her article was shared even more widely than the fake photo. Police later said it had helped calm the crowds.", "مقالتها اتشيّرت أكتر من الصورة المزيفة. والبوليس قال بعدها إنها ساعدت تهدّي الناس."], ["The next morning, her editor placed a coffee on her desk. \"Fifteen minutes,\" he said. \"Best fifteen minutes this newspaper has ever spent.\"", "تاني يوم الصبح، رئيس التحرير حط قهوة على مكتبها. \"ربع ساعة،\" قال. \"أحسن ربع ساعة الجريدة دي صرفتها في حياتها.\""]], "quiz": [{"q": "What did the photo show?", "o": ["a historic mosque in flames", "a car accident", "a flood"], "a": 0}, {"q": "What did her editor want?", "o": ["to publish it immediately", "to ignore it", "to call the police"], "a": 0}, {"q": "What clue showed the image was AI-generated?", "o": ["meaningless writing on a shop sign", "the colour of the mosque", "the number of shares"], "a": 0}, {"q": "What did the guard say?", "o": ["There was no fire.", "The mosque was burning.", "He didn't know."], "a": 0}, {"q": "What did the police say about her article?", "o": ["It helped calm the crowds.", "It was dangerous.", "It was fake."], "a": 0}]}, "challenge": {"title": "Truth or Fake?", "ar": "حقيقي ولا مزيف؟ — جاوب وسجّل", "qs": ["Describe a piece of fake news you saw. How did you discover it was false?", "Should social media companies be legally responsible for fake news on their platforms?", "Admittedly, citizen journalism has advantages. Nonetheless, what are its dangers?", "How can schools teach young people to think critically about the media?", "Is it ever acceptable for journalists to hide information from the public?", "Why do people believe conspiracy theories?", "Are you in an echo chamber? How could you get out of it?", "Should spreading deliberate disinformation be a crime?", "Use at least four discourse markers to argue: \"Traditional newspapers will disappear.\"", "What would you do if a friend kept sharing false information?"]}, "games": {"pairs": [["📰", "headline"], ["🔗", "source"], ["🤥", "fake news"], ["🫧", "echo chamber"], ["✅", "fact-check"], ["🚨", "debunk"]], "spell": [["🗞️", "journalism"], ["🗣️", "rumour"], ["🎭", "misinformation"], ["⚖️", "biased"], ["🔍", "verify"], ["🏛️", "credible"], ["📊", "evidence"], ["📺", "coverage"]], "speed": [["Admittedly, it looks real.", true], ["Be that as it may, we must check.", true], ["In light of the evidence is clear.", false], ["It is hard. Nonetheless, it matters.", true], ["Granted, the app is useful.", true], ["On second thought it, I'll stay.", false], ["The story was false. Consequently, he resigned.", true], ["Not to mention the cost.", true], ["Owing to the rain, the match was cancelled.", true], ["Hence means \"for example\".", false], ["Disinformation is spread deliberately.", true], ["A credible source cannot be trusted.", false], ["\"Spread like wildfire\" means to spread very quickly.", true], ["\"Play down\" means to make something seem less important.", true], ["\"Sus\" means trustworthy.", false], ["\"Doomscrolling\" is reading bad news for hours.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "False information spread on purpose = ___.", "o": ["disinformation", "coverage", "evidence"], "a": 0, "pic": "🎯"}, {"q": "To check that something is true = to ___.", "o": ["verify", "trigger", "blow up"], "a": 0, "pic": "🔍"}, {"q": "Unfairly favouring one side = ___.", "o": ["biased", "credible", "viral"], "a": 0, "pic": "⚖️"}, {"q": "To prove that a claim is false = to ___.", "o": ["debunk", "go viral", "make up"], "a": 0, "pic": "🚨"}, {"q": "A space where you only hear opinions like yours = an ___.", "o": ["echo chamber", "editorial", "headline"], "a": 0, "pic": "🫧"}, {"q": "\"إشاعة\" in English is…", "o": ["rumour", "humour", "rumble"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "___, the report had some errors, but it was mostly accurate.", "o": ["Admittedly", "Consequently", "Hence"], "a": 0}, {"q": "The evidence was weak. ___, he was found guilty.", "o": ["Nonetheless", "Admittedly", "Granted"], "a": 0}, {"q": "___ the new information, we have changed our decision.", "o": ["In light of", "Even so", "Not to mention"], "a": 0}, {"q": "The trains were late, ___ the buses.", "o": ["not to mention", "nonetheless", "consequently"], "a": 0}, {"q": "The site published false news. ___, it lost its readers.", "o": ["Consequently", "Granted", "Admittedly"], "a": 0}, {"q": "Which is correct?", "o": ["Be that as it may, we need more evidence.", "Being that as may, we need more evidence.", "Be that it as may, we need more evidence."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"My cousin shared it, so it must be true.\" — Best answer:", "o": ["Be that as it may, we should check the source.", "Cousins are family.", "Share it again!"], "a": 0}, {"q": "\"How do you know it's true?\" — Best answer:", "o": ["I heard it straight from the horse's mouth.", "From a pinch of salt.", "Like wildfire."], "a": 0}, {"q": "\"He says he's a millionaire at 15.\" — Best answer (slang):", "o": ["That's cap.", "That's receipts.", "That's ratio'd."], "a": 0}, {"q": "\"Everyone was furious about it for one day.\" — Best answer:", "o": ["So it was a storm in a teacup.", "So it spread like a horse.", "So it was cap."], "a": 0}, {"q": "\"I spent three hours reading terrible news.\" — Best answer:", "o": ["Stop doomscrolling — go for a walk.", "Keep doomscrolling!", "That's receipts."], "a": 0}, {"q": "\"I'll call her. Actually, no, I'll text.\" — Better phrase:", "o": ["I'll call her. On second thoughts, I'll text.", "I'll call her. Consequently, I'll text.", "I'll call her. Admittedly, I'll text."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["In 2020, a false claim that drinking hot water could cure a virus was shared millions of times.", "Admittedly, hot drinks can make people feel more comfortable when they are ill.", "Nonetheless, there was no evidence that they could cure anything.", "Health organisations quickly published fact-checks to debunk the claim.", "Consequently, several platforms began adding warning labels to posts containing health misinformation."], "qs": [{"q": "What did the false claim say?", "o": ["hot water could cure a virus", "cold water was dangerous", "vaccines were fake"], "a": 0}, {"q": "What is admitted about hot drinks?", "o": ["They can make ill people feel more comfortable.", "They cure viruses.", "They are dangerous."], "a": 0}, {"q": "Was there evidence for the claim?", "o": ["No.", "Yes, a lot.", "Some."], "a": 0}, {"q": "What did health organisations do?", "o": ["published fact-checks", "stayed silent", "agreed with the claim"], "a": 0}, {"q": "What did platforms start doing as a result?", "o": ["adding warning labels", "closing down", "paying users"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write an argumentative paragraph (100–150 words): \"Social media does more harm than good to the way we understand the news.\" Use at least four advanced discourse markers (Admittedly, Nonetheless, Be that as it may, Not to mention, Consequently…).", "promptAr": "اكتب فقرة جدلية (١٠٠–١٥٠ كلمة): \"السوشيال ميديا بتضر فهمنا للأخبار أكتر ما بتفيده.\" استخدم ٤ أدوات ربط متقدمة على الأقل.", "checks": [["📰", "Media words", "x", "\\b(news|media|social media|fake|misinformation|source|sources|journalists?|headlines?|rumours?|platforms?|fact)\\b"], ["🔗", "Concession / contrast", "x", "\\b(admittedly|granted|nonetheless|nevertheless|be that as it may|even so|that said)\\b"], ["➕", "Addition / result", "x", "\\b(not to mention|furthermore|moreover|consequently|hence|thus|in light of|owing to)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "cSKGa_7XJkg", "title": "How False News Can Spread", "ar": "إزاي الأخبار الكاذبة بتنتشر — TED-Ed", "by": "TED-Ed · Noah Tavlin", "lines": [["A famous saying claims that a lie can travel halfway around the world while the truth is still putting on its shoes.", "مقولة مشهورة بتقول إن الكدبة ممكن تلف نص العالم والحقيقة لسه بتلبس جزمتها."], ["It is usually attributed to Mark Twain — ironically, there is no proof he ever said it.", "عادة بتتنسب لمارك توين — والمفارقة إن مفيش دليل إنه قالها أصلًا."], ["In the past, most global news came from a few major newspapers and networks that gathered information directly.", "زمان، أغلب الأخبار العالمية كانت بتيجي من شوية جرايد وشبكات كبيرة بتجمع المعلومات بنفسها."], ["Today, many sites simply aggregate and reprint stories from other outlets, and information spreads extremely fast.", "النهارده، مواقع كتير بتجمّع وتعيد نشر أخبار من مصادر تانية، والمعلومات بتنتشر بسرعة رهيبة."], ["This creates ideal conditions for \"circular reporting\".", "وده بيعمل ظروف مثالية لـ\"النشر الدائري\"."], ["One outlet publishes false information, a second outlet repeats it, and the first then cites the second as proof.", "مصدر بينشر معلومة غلط، ومصدر تاني بيكررها، وبعدين الأول بيستشهد بالتاني كدليل."], ["When several outlets report the same claim, a later writer may wrongly believe it has been verified by multiple sources.", "لما كذا مصدر ينشروا نفس الادعاء، كاتب بعدهم ممكن يفتكر غلط إنه اتأكد منه من مصادر كتير."], ["A 1998 pseudoscientific paper falsely linked childhood vaccines to autism, and it was repeated again and again.", "ورقة بحثية علمية زائفة سنة ١٩٩٨ ربطت غلط بين تطعيمات الأطفال والتوحد، واتكررت مرة ورا مرة."], ["Even after scientists discredited it, many parents stopped vaccinating, and nearly eradicated diseases returned.", "حتى بعد ما العلماء أثبتوا إنها غلط، أهالي كتير بطّلوا يطعّموا ولادهم، وأمراض كانت قربت تختفي رجعت."], ["Wikis can also spread unverified facts, which journalists may copy and which later appear as the \"source\" for the wiki itself.", "الويكيز كمان ممكن تنشر معلومات متأكدش منها، والصحفيين ممكن ينقلوها، وبعدين تظهر كـ\"مصدر\" للويكي نفسها."], ["Our desire for quick answers often overpowers our need to be sure they are true.", "رغبتنا في الإجابات السريعة غالبًا بتتغلب على احتياجنا نتأكد إنها صح."], ["To slow down lies, avoid sensationalist media, look for criticism of suspicious claims and trace reports back to the original source.", "عشان تبطّأ الكدب، ابعد عن الإعلام اللي بيدوّر على الإثارة، ودوّر على انتقادات للادعاءات المشبوهة، وارجع للمصدر الأصلي."]], "words": ["halfway around the world", "attributed", "ironically", "networks", "aggregate", "circular reporting", "cites", "verified", "pseudoscientific", "discredited", "eradicated", "sensationalist"], "quiz": [{"q": "Who is the famous lie quote usually attributed to?", "o": ["Mark Twain", "Shakespeare", "Einstein"], "a": 0}, {"q": "Why is that ironic?", "o": ["There's no proof he ever said it.", "He hated newspapers.", "He was a journalist."], "a": 0}, {"q": "What is circular reporting?", "o": ["outlets repeating and citing each other's false information", "reporting on circles", "printing news daily"], "a": 0}, {"q": "What happened after the false 1998 vaccine paper?", "o": ["Some parents stopped vaccinating and diseases returned.", "Vaccines became cheaper.", "Nothing."], "a": 0}, {"q": "What often overpowers our need to check facts?", "o": ["our desire for quick answers", "our love of books", "our fear of doctors"], "a": 0}, {"q": "How can we slow down lies?", "o": ["avoid sensationalist media and trace the original source", "share faster", "only read headlines"], "a": 0}]}]}, "6": {"n": 6, "title": "Art, Creativity and Culture", "ar": "الفن والإبداع والثقافة — Fronting & Emphasis", "icon": "🎨", "cover": "img/c1/u6.jpg", "intro": "اتكلم عن الفن والإبداع والمتاحف والموسيقى ومين يقرر إيه هو \"الفن\"، واستخدم التقديم والتأكيد الأدبي: Such was… / So… that… / Strange as it may seem… / Into the room walked…", "videos": [{"id": "c1v6", "title": "Is This Really Art?", "ar": "ده فن بجد؟ — سارة وآدم", "src": "video/c1/u6v1.mp4", "poster": "img/c1/u6v1.jpg", "sp": {"a": {"n": "Sara", "g": "f"}, "b": {"n": "Adam", "g": "m"}}, "lines": [["b", "Sara, did you hear about that banana taped to a wall? It sold for six million dollars!", "سارة، سمعتي عن الموزة اللي متلزقة على الحيطة؟ اتباعت بـ٦ مليون دولار!"], ["a", "I did. Such was the public reaction that the museum had to put guards next to it.", "سمعت. رد فعل الناس كان لدرجة إن المتحف اضطر يحط حراس جنبها."], ["b", "But is it art? I could tape a banana to a wall!", "بس هو ده فن؟ أنا ممكن ألزق موزة على حيطة!"], ["a", "Strange as it may seem, that's the point. The artist wanted people to ask exactly that question.", "غريب زي ما يبان، ده المقصود. الفنان كان عايز الناس تسأل نفس السؤال ده بالظبط."], ["b", "So the idea matters more than the skill? That sounds a bit too easy.", "يعني الفكرة أهم من المهارة؟ ده شكله سهل أوي."], ["a", "Not always. What I love is art that combines both. Last week I saw an exhibition by a young Egyptian painter. So detailed were her paintings that people thought they were photographs.", "مش دايمًا. اللي بحبه الفن اللي بيجمع الاتنين. الأسبوع اللي فات شفت معرض لرسامة مصرية صغيرة. لوحاتها كانت دقيقة لدرجة إن الناس افتكروها صور."], ["b", "Now that's impressive. Talent like that takes years.", "ده بقى مبهر. موهبة زي دي بتاخد سنين."], ["a", "And creativity isn't only in galleries. My grandmother's embroidery is art too, if you ask me.", "والإبداع مش في المعارض بس. تطريز تيتة فن هو كمان، لو تسألني."], ["b", "True. Much as I love modern art, traditional crafts are being forgotten.", "صح. على قد ما بحب الفن الحديث، الحرف التقليدية بتتنسي."], ["a", "Exactly. Only when they disappear will people realise how valuable they were.", "بالظبط. الناس مش هتعرف قيمتها غير لما تختفي."], ["b", "Maybe we should open a gallery for traditional crafts — with no bananas!", "يمكن نفتح معرض للحرف التقليدية — من غير موز!"], ["a", "Deal! Although a banana embroidered by my grandmother might sell for millions.", "اتفقنا! رغم إن موزة متطرزة من تيتة ممكن تتباع بملايين."]], "quiz": [{"q": "What sold for six million dollars?", "o": ["a banana taped to a wall", "a painting of a banana", "a golden statue"], "a": 0}, {"q": "What did the museum have to do?", "o": ["put guards next to it", "close for a week", "give the money back"], "a": 0}, {"q": "What did the artist want, according to Sara?", "o": ["people to ask if it was art", "to eat the banana", "to become rich quickly"], "a": 0}, {"q": "What was special about the young Egyptian painter's work?", "o": ["It was so detailed it looked like photographs.", "It was made of food.", "It was very small."], "a": 0}, {"q": "What does Adam suggest at the end?", "o": ["opening a gallery for traditional crafts", "buying a banana", "learning embroidery"], "a": 0}], "fill": [[0, "taped"], [1, "Such was the public reaction"], [3, "Strange as it may seem"], [4, "skill"], [5, "So detailed were her paintings"], [5, "exhibition"], [6, "Talent like that"], [7, "embroidery"], [8, "Much as I love"], [8, "traditional crafts"], [9, "Only when they disappear will"], [10, "gallery"]]}], "vocab": [{"t": "The art world", "ar": "عالم الفن", "items": [["🖼️", "exhibition", "The exhibition opens next week."], ["🏛️", "gallery", "The gallery shows contemporary art."], ["🎨", "masterpiece", "The painting is considered a masterpiece."], ["🗿", "sculpture", "There is a huge sculpture in the square."], ["🖌️", "brushstroke", "You can see every brushstroke."], ["🧵", "craft", "Pottery is a traditional craft."], ["🧑‍🎨", "curator", "The curator chose every piece."], ["🎭", "contemporary", "I prefer contemporary art."]]}, {"t": "Creativity", "ar": "الإبداع", "items": [["💡", "inspiration", "Where do you find inspiration?"], ["🌀", "imagination", "Children have a wonderful imagination."], ["✨", "original", "Her ideas are completely original."], ["🔁", "derivative", "The film felt derivative and boring."], ["🎯", "self-expression", "Art is a form of self-expression."], ["🚧", "creative block", "Every writer suffers from creative block."], ["🧠", "innovative", "It's an innovative design."], ["🎼", "compose", "He composed his first symphony at twelve."]]}, {"t": "Judging art", "ar": "الحكم على الفن", "items": [["🤔", "interpretation", "Every viewer has a different interpretation."], ["😮", "thought-provoking", "The film was thought-provoking."], ["🙄", "pretentious", "Some modern art feels pretentious."], ["💰", "priceless", "The ancient statue is priceless."], ["🗣️", "critic", "The critics loved the exhibition."], ["🎟️", "acclaimed", "She is an internationally acclaimed artist."], ["🌍", "cultural heritage", "We must protect our cultural heritage."], ["🖤", "evocative", "The music was dark and evocative."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["What kind of art do you enjoy most?", "أنهي نوع فن بتحبه أكتر؟", "Photography and street art."], ["When was the last time you visited a museum or gallery?", "آخر مرة زرت متحف أو معرض إمتى؟", "Last summer, the Grand Egyptian Museum."], ["Are you a creative person? How do you express it?", "إنت شخص مبدع؟ بتعبر عن ده إزاي؟", "I write short stories in my free time."], ["Where do you find inspiration?", "بتلاقي الإلهام فين؟", "Usually when I travel or listen to music."], ["Which traditional craft from your country do you love?", "أنهي حرفة تقليدية من بلدك بتحبها؟", "Khayamiya — the colourful tent fabric."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Can anything be art? Where is the line?", "أي حاجة ممكن تبقى فن؟ الحد فين؟", "It needs an idea and an intention."], ["Should governments spend money on the arts?", "الحكومات تصرف فلوس على الفنون؟", "Yes — culture is part of our identity."], ["Is AI-generated art real art?", "الفن اللي بيعمله الذكاء الاصطناعي فن حقيقي؟", "It's a tool; the human idea is the art."], ["Should ancient artefacts be returned to their countries of origin?", "الآثار القديمة ترجع لبلادها الأصلية؟", "Absolutely — they belong to their culture."], ["Is graffiti art or vandalism?", "الجرافيتي فن ولا تخريب؟", "It depends on where it is and if it was allowed."]]}], "grammar": {"title": "Fronting & Emphasis", "ar": "التقديم والتأكيد — Such was… / So… that… / Strange as it may seem", "blocks": [{"type": "intro", "en": "Fronting means moving a part of the sentence to the beginning for emphasis or dramatic effect. It is common in literature, journalism and powerful speeches.", "ar": "الـ Fronting يعني إنك تحرّك جزء من الجملة للأول عشان التأكيد أو التأثير الدرامي. منتشر في الأدب والصحافة والخطب القوية."}, {"type": "big", "items": [{"v": "Such + be + noun + that… / So + adj + be + subject + that…", "p": "degree & result", "c": 1, "eg": ["Such was the reaction that guards were needed.", "So detailed were her paintings that people thought they were photos.", "So loud was the music that we left."]}, {"v": "Adjective / adverb + as + subject + verb", "p": "concession (although)", "c": 2, "eg": ["Strange as it may seem, that's the point.", "Much as I love modern art, crafts are being forgotten.", "Hard as he tried, he couldn't finish."]}, {"v": "Place / object fronting", "p": "dramatic description", "c": 3, "eg": ["Into the room walked a famous painter.", "On the wall hung a tiny portrait.", "This painting I will never forget."]}]}, {"type": "table", "title": "🔄 Normal → Fronted", "head": ["Normal", "Fronted (emphatic)"], "rows": [["The reaction was so strong that…", "Such was the reaction that…"], ["Her paintings were so detailed that…", "So detailed were her paintings that…"], ["Although it seems strange…", "Strange as it may seem…"], ["Although I love modern art…", "Much as I love modern art…"], ["A famous painter walked into the room.", "Into the room walked a famous painter."]]}, {"type": "uses", "title": "💡 Only when / Little did…", "ar": "تأكيد بالقلب", "items": [["⏳", "Only when + clause + inversion", "Only when they disappear will people realise.", "مش غير لما"], ["🙈", "Little did + subject + know", "Little did she know that the painting was fake.", "ولا كان يعرف"], ["🏁", "Not until + clause + inversion", "Not until years later did he become famous.", "مش غير بعد"], ["🎯", "Nowhere + inversion", "Nowhere else will you find such colours.", "في أي حتة تانية"]]}, {"type": "tip", "en": "With 'So + adjective', invert the subject and 'be': So detailed were her paintings ✔ (not So detailed her paintings were ✖ in this structure). With 'Strange as it may seem', there is NO inversion: Strange as it may seem ✔ (not Strange as may it seem ✖).", "ar": "مع So + صفة اقلب الفاعل وbe: So detailed were her paintings. ومع Strange as it may seem مفيش قلب."}]}, "exercises": [{"type": "mcq", "title": "Fronting & Emphasis — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "___ was the public reaction that guards were needed.", "o": ["Such", "So", "Very", "Too"], "a": 0}, {"q": "So detailed ___ her paintings that people thought they were photos.", "o": ["were", "was", "had", "did"], "a": 0}, {"q": "Strange as it ___ seem, that's the point.", "o": ["may", "does", "is", "can be"], "a": 0}, {"q": "___ as I love modern art, I prefer traditional crafts.", "o": ["Much", "Many", "Such", "So"], "a": 0}, {"q": "Into the room ___ a famous painter.", "o": ["walked", "walking", "did walk", "walks to"], "a": 0}, {"q": "Only when they disappear ___ people realise their value.", "o": ["will", "they will", "people", "do"], "a": 0}, {"q": "Little ___ she know that the painting was fake.", "o": ["did", "does", "had", "was"], "a": 0}, {"q": "Hard as he ___, he couldn't finish the sculpture.", "o": ["tried", "did try", "tries hard", "trying"], "a": 0}, {"q": "Which sentence is correct?", "o": ["So loud was the music that we left.", "So loud the music was that we left.", "Such loud was the music that we left.", "So was loud the music that we left."], "a": 0}, {"q": "Not until years later ___ famous.", "o": ["did he become", "he became", "became he", "he did become"], "a": 0}]}, {"type": "mcq", "title": "Normal or fronted?", "ar": "عادي ولا مقدَّم؟", "items": [{"q": "\"Although it seems strange\" → ___", "o": ["Strange as it may seem", "Strange it may seem as"], "a": 0}, {"q": "\"The noise was so loud that…\" → ___", "o": ["So loud was the noise that…", "Such loud was the noise that…"], "a": 0}, {"q": "\"Such was…\" is followed by a ___.", "o": ["noun", "adjective"], "a": 0}, {"q": "\"So… was\" is followed by an ___ first.", "o": ["adjective", "noun"], "a": 0}, {"q": "Fronting is common in ___.", "o": ["literature and speeches", "shopping lists"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["Such was", "the reaction", "that", "guards were needed"], "a": [0, 1, 2, 3]}, {"c": ["Strange as", "it may seem,", "that's", "the point"], "a": [0, 1, 2, 3]}, {"c": ["So detailed", "were", "her paintings", "that people stared"], "a": [0, 1, 2, 3]}, {"c": ["Little did", "she", "know", "the truth"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "The Forger Who Fooled the Experts", "ar": "المزوّر اللي ضحك على الخبراء", "g": "m", "lines": [["In 1945, a Dutch painter named Han van Meegeren was arrested for treason. The charge was serious: he had sold a priceless painting by the master Vermeer to the Nazi leader Hermann Göring.", "سنة ١٩٤٥، رسام هولندي اسمه هان فان ميخيرين اتقبض عليه بتهمة الخيانة. التهمة كانت خطيرة: باع لوحة لا تقدّر بتمن للفنان الكبير فيرمير للقائد النازي هيرمان جورينج."], ["Such was the seriousness of the crime that he faced the death penalty. Then he made an astonishing confession: the painting was not a Vermeer at all. He had painted it himself.", "الجريمة كانت خطيرة لدرجة إنه كان قصاده حكم الإعدام. وبعدين اعترف اعتراف مدهش: اللوحة مكانتش لفيرمير خالص. هو اللي رسمها بنفسه."], ["Nobody believed him. So convincing were his \"Vermeers\" that leading art critics had praised them as masterpieces. One had even been bought by a famous museum.", "محدش صدقه. لوحات \"فيرمير\" بتاعته كانت مقنعة لدرجة إن أكبر نقاد الفن مدحوها كتحف. وواحدة منهم كمان اشتراها متحف مشهور."], ["To prove his innocence, van Meegeren offered to paint a new \"Vermeer\" in front of witnesses. Over several weeks, under guard, he did exactly that.", "عشان يثبت براءته، فان ميخيرين عرض إنه يرسم \"فيرمير\" جديدة قدام شهود. وعلى مدار كذا أسبوع، تحت الحراسة، عمل كده بالظبط."], ["Little did the experts know how carefully he had worked. He had used old canvases, mixed his own paints from historic materials and baked the finished paintings to make them look centuries old.", "الخبراء مكانوش يعرفوا خالص هو اشتغل بحرص قد إيه. استخدم قماش لوحات قديم، وخلط ألوانه بنفسه من مواد تاريخية، وخبز اللوحات بعد ما تخلص عشان تبان عمرها قرون."], ["Strange as it may seem, the public began to see him as a hero — the man who had cheated a Nazi leader.", "غريب زي ما يبان، الناس بدأوا يشوفوه بطل — الراجل اللي ضحك على قائد نازي."], ["He was cleared of treason but found guilty of forgery. He died of a heart attack before he could serve his sentence.", "اتبرّأ من تهمة الخيانة بس اتحكم عليه بالتزوير. ومات بأزمة قلبية قبل ما يقضي العقوبة."], ["His story raises uncomfortable questions. If experts could not tell the difference, what exactly were they admiring? Is a painting valuable because of its beauty, or because of the name attached to it?", "قصته بتطرح أسئلة محرجة. لو الخبراء مقدروش يفرّقوا، كانوا معجبين بإيه بالظبط؟ اللوحة قيمتها في جمالها، ولا في الاسم اللي مكتوب عليها؟"], ["Today, forgers face a new opponent: science. X-rays, chemical analysis and even AI can detect fakes that once fooled the world's finest eyes.", "النهارده، المزورين قصادهم عدو جديد: العلم. الأشعة والتحليل الكيميائي وحتى الذكاء الاصطناعي يقدروا يكشفوا تزوير كان زمان بيضحك على أحسن عيون في العالم."], ["Much as we might admire his skill, van Meegeren reminds us that in the art world, the line between genius and fraud can be remarkably thin.", "على قد ما ممكن نعجب بمهارته، فان ميخيرين بيفكرنا إن في عالم الفن، الخط بين العبقرية والنصب ممكن يبقى رفيع جدًا."]], "keys": [["⚖️", "treason", "the crime of betraying your country"], ["🗣️", "confession", "a statement admitting you did something wrong"], ["🖼️", "canvas", "the cloth that artists paint on"], ["🖊️", "forgery", "making a copy to deceive people"], ["🔬", "chemical analysis", "scientific testing of materials"], ["🎭", "fraud", "deceiving people for money or gain"]], "quiz": [{"q": "Why was van Meegeren arrested?", "o": ["for selling a \"Vermeer\" to a Nazi leader", "for stealing a painting", "for burning a museum"], "a": 0}, {"q": "What was his astonishing confession?", "o": ["He had painted the \"Vermeer\" himself.", "He had never sold anything.", "He was a Nazi."], "a": 0}, {"q": "How did he prove his story?", "o": ["He painted a new \"Vermeer\" in front of witnesses.", "He showed a receipt.", "He called Vermeer."], "a": 0}, {"q": "How did he make his paintings look old?", "o": ["old canvases, historic paints and baking", "by washing them", "by burying them"], "a": 0}, {"q": "How did the public see him?", "o": ["as a hero who cheated a Nazi leader", "as a traitor", "as a boring man"], "a": 0}, {"q": "What can detect fakes today?", "o": ["X-rays, chemical analysis and AI", "only critics", "nothing"], "a": 0}]}, "idioms": {"items": [["beauty is in the eye of the beholder", "Different people find different things beautiful.", "الجمال في عين اللي بيشوف", "You hate the painting? Well, beauty is in the eye of the beholder.", "مش عاجبك اللوحة؟ الجمال في عين اللي بيشوف."], ["a work in progress", "Something that is still being developed.", "لسه تحت الشغل", "My novel is still a work in progress.", "روايتي لسه تحت الشغل."], ["think on your feet", "To react quickly and cleverly.", "يتصرف بسرعة وذكاء", "Actors in improv must think on their feet.", "الممثلين في الارتجال لازم يتصرفوا بسرعة وذكاء."], ["steal the show", "To be the most impressive part of an event.", "يخطف الأضواء", "The young singer stole the show.", "المغنية الصغيرة خطفت الأضواء."]], "quiz": [{"q": "Everyone was talking about the little girl's dance. She ___.", "o": ["stole the show", "thought on her feet", "was a work in progress", "beheld beauty"], "a": 0}, {"q": "The website isn't finished — it's ___.", "o": ["a work in progress", "stealing the show", "in the eye", "on its feet"], "a": 0}, {"q": "\"Beauty is in the eye of the beholder\" means…", "o": ["people find different things beautiful", "only experts know beauty", "eyes are beautiful", "beauty is rare"], "a": 0}, {"q": "When the microphone broke, the speaker ___ and sang instead.", "o": ["thought on her feet", "stole the show", "was in progress", "beheld"], "a": 0}]}, "phrasal": {"items": [["come up with", "To think of an idea.", "يطلع بفكرة", "She came up with a brilliant design.", "طلعت بتصميم رائع."], ["draw on", "To use experience or knowledge as a source.", "يستمد من", "The writer draws on her childhood in Aswan.", "الكاتبة بتستمد من طفولتها في أسوان."], ["bring out", "To make a quality more noticeable; to release.", "يبرز / ينزّل", "The lighting brings out the colours. / The band brought out a new album.", "الإضاءة بتبرز الألوان. / الفرقة نزّلت ألبوم جديد."], ["take after", "To have talent or features like a family member.", "طالع لـ", "She takes after her grandfather, who was a painter.", "هي طالعة لجدها اللي كان رسام."]], "quiz": [{"q": "The artist ___ her memories of the village in her work.", "o": ["draws on", "comes up with", "brings out", "takes after"], "a": 0}, {"q": "Who ___ the idea for this exhibition?", "o": ["came up with", "drew on", "took after", "brought out"], "a": 0}, {"q": "Natural light ___ the beauty of the sculpture.", "o": ["brings out", "comes up with", "takes after", "draws on"], "a": 0}, {"q": "He's so musical — he ___ his mother.", "o": ["takes after", "brings out", "draws on", "comes up"], "a": 0}]}, "slang": {"items": [["a vibe", "A feeling or atmosphere (often positive).", "جو / إحساس حلو", "This gallery is such a vibe.", "المعرض ده جوّه حلو جدًا.", "منتشرة جدًا"], ["aesthetic", "Having a stylish, beautiful look (as an adjective).", "شكله فني وشيك", "Her room is so aesthetic.", "أوضتها شكلها فني وشيك جدًا.", "من لغة إنستجرام"], ["slaps", "Is excellent (music, art).", "تحفة / جامدة", "This new song slaps!", "الأغنية الجديدة دي جامدة!", "سلانج حديث"], ["a flex", "Showing off something impressive.", "تفاخر / عرض عضلات", "Owning an original painting is a big flex.", "إنك تمتلك لوحة أصلية ده تفاخر كبير.", "منتشرة"], ["basic", "Unoriginal, following popular trends.", "تقليدي ومش أصلي", "Another sunset photo? That's so basic.", "صورة غروب تاني؟ ده تقليدي أوي.", "ممكن تضايق حد — بحذر"]], "quiz": [{"q": "\"This song ___!\" (it's excellent)", "o": ["slaps", "flexes", "is basic", "vibes"], "a": 0}, {"q": "Showing off your expensive watch is ___.", "o": ["a flex", "a vibe", "aesthetic", "basic"], "a": 0}, {"q": "A café with plants, soft lights and art on the walls is very ___.", "o": ["aesthetic", "basic", "flex", "slaps"], "a": 0}, {"q": "\"Basic\" means…", "o": ["unoriginal", "very creative", "expensive", "old"], "a": 0}]}, "story": {"title": "The Wall", "ar": "الحيطة", "g": "f", "lines": [["Hamza was sixteen when he first painted on the grey wall behind the bus station. It was illegal, of course. Such was his frustration with his grey neighbourhood that he didn't care.", "حمزة كان عنده ١٦ سنة لما رسم لأول مرة على الحيطة الرمادي ورا موقف الأتوبيسات. كان ممنوع طبعًا. بس كان متضايق من حيّه الرمادي لدرجة إنه مكانش فارق معاه."], ["He painted at night, quickly and secretly: a huge green tree whose branches were full of birds, each one a different colour.", "كان بيرسم بالليل، بسرعة وفي السر: شجرة خضرا ضخمة فروعها مليانة عصافير، كل واحد بلون مختلف."], ["The next morning, the neighbourhood woke up to something new. Strange as it may seem, nobody reported it. People stopped to take photos. Children counted the birds.", "تاني يوم الصبح، الحي صحي على حاجة جديدة. غريب زي ما يبان، محدش بلّغ. الناس وقفت تصوّر. والأطفال عدّوا العصافير."], ["A week later, a city official arrived with a pot of grey paint. \"Vandalism,\" he said. \"It must be removed.\"", "بعد أسبوع، موظف من المحافظة جه ومعاه جردل بوية رمادي. \"تخريب،\" قال. \"لازم يتشال.\""], ["Before he could start, an old woman stood in front of the wall. Then a shopkeeper. Then a group of schoolchildren. Within an hour, half the street was there.", "قبل ما يبدأ، ست كبيرة وقفت قدام الحيطة. وبعدين صاحب محل. وبعدين مجموعة تلاميذ. في خلال ساعة، نص الشارع كان هناك."], ["\"This tree is the only beautiful thing on this street,\" the old woman said. \"Paint over it, and you paint over us.\"", "\"الشجرة دي هي الحاجة الحلوة الوحيدة في الشارع ده،\" الست الكبيرة قالت. \"لو بوّظتها، يبقى بتبوّظنا إحنا.\""], ["The official, unsure what to do, took a photo and left. Little did Hamza know that the photo would reach the governor's office.", "الموظف، مكانش عارف يعمل إيه، صوّر ومشي. حمزة مكانش يعرف خالص إن الصورة هتوصل لمكتب المحافظ."], ["A month later, Hamza received an official letter. He was sure he was in trouble. Instead, it was an invitation: the city wanted him to lead a project painting twenty walls across the district — legally this time.", "بعد شهر، حمزة جاله جواب رسمي. كان متأكد إنه في مشكلة. بدل كده، كانت دعوة: المدينة عايزاه يقود مشروع لرسم ٢٠ حيطة في الحي كله — بشكل قانوني المرة دي."], ["He accepted on one condition: every wall would be designed with the people who lived beside it.", "وافق بشرط واحد: كل حيطة تتصمم مع الناس اللي ساكنين جنبها."], ["Today, tourists come to see \"the painted streets\". And on the first wall, under the green tree, someone has added a small sign: \"Art belongs to everyone.\"", "النهارده، السياح بييجوا يشوفوا \"الشوارع المرسومة\". وعلى أول حيطة، تحت الشجرة الخضرا، حد ضاف يافطة صغيرة: \"الفن ملك الجميع.\""]], "quiz": [{"q": "What did Hamza paint first?", "o": ["a green tree full of colourful birds", "a portrait of his mother", "the bus station"], "a": 0}, {"q": "How did people react the next morning?", "o": ["They took photos and nobody reported it.", "They called the police.", "They painted over it."], "a": 0}, {"q": "What did the official want to do?", "o": ["remove the painting", "buy the painting", "add more birds"], "a": 0}, {"q": "What was in the official letter?", "o": ["an invitation to lead a mural project", "a fine", "an arrest warrant"], "a": 0}, {"q": "What was Hamza's condition?", "o": ["Each wall would be designed with local residents.", "He would be paid a lot.", "He would work alone."], "a": 0}]}, "challenge": {"title": "What Is Art?", "ar": "يعني إيه فن؟ — جاوب وسجّل", "qs": ["Is a banana taped to a wall art? Defend your opinion.", "Describe the most beautiful work of art you have ever seen. Use \"So… was it that…\" or \"Such was…\".", "Should graffiti be allowed on public walls?", "Can AI ever be truly creative?", "Should ancient artefacts in foreign museums be returned to their home countries?", "Which traditional craft from your culture should be protected, and how?", "Strange as it may seem… — tell me something surprising about yourself.", "Is art more valuable because of the artist's name or because of its beauty?", "Should art and music be compulsory subjects at school?", "If you could create one work of art, what would it be and why?"]}, "games": {"pairs": [["🖼️", "exhibition"], ["🏛️", "gallery"], ["🎨", "masterpiece"], ["🗿", "sculpture"], ["🧑‍🎨", "curator"], ["💡", "inspiration"]], "spell": [["🌀", "imagination"], ["✨", "original"], ["🔁", "derivative"], ["🧠", "innovative"], ["🤔", "interpretation"], ["🙄", "pretentious"], ["💰", "priceless"], ["🎟️", "acclaimed"]], "speed": [["Such was the reaction that guards were needed.", true], ["Such loud was the music.", false], ["So detailed were her paintings that people stared.", true], ["Strange as it may seem, it worked.", true], ["Strange as may it seem, it worked.", false], ["Much as I love art, I prefer music.", true], ["Into the room walked a painter.", true], ["Little she knew the truth.", false], ["Only when they disappear will people realise.", true], ["Not until later did he become famous.", true], ["Derivative means completely original.", false], ["A curator chooses works for an exhibition.", true], ["\"Steal the show\" means to be the most impressive.", true], ["\"Come up with\" means to think of an idea.", true], ["\"Basic\" means very original.", false], ["\"This song slaps\" means it's excellent.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "A public show of art = an ___.", "o": ["exhibition", "interpretation", "inspiration"], "a": 0, "pic": "🖼️"}, {"q": "An extremely good work of art = a ___.", "o": ["masterpiece", "brushstroke", "craft"], "a": 0, "pic": "🎨"}, {"q": "Copying others, not original = ___.", "o": ["derivative", "innovative", "evocative"], "a": 0, "pic": "🔁"}, {"q": "Trying to seem more important than it is = ___.", "o": ["pretentious", "priceless", "acclaimed"], "a": 0, "pic": "🙄"}, {"q": "Making you think deeply = ___.", "o": ["thought-provoking", "basic", "contemporary"], "a": 0, "pic": "😮"}, {"q": "\"تحفة فنية\" in English is…", "o": ["masterpiece", "master plan", "mastermind"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "___ was the crowd that we couldn't get in.", "o": ["Such", "So", "Too"], "a": 0}, {"q": "So beautiful ___ the view that we stayed for hours.", "o": ["was", "were", "did"], "a": 0}, {"q": "Tired as she ___, she kept painting.", "o": ["was", "did", "had"], "a": 0}, {"q": "Little ___ we know what would happen.", "o": ["did", "had", "were"], "a": 0}, {"q": "Only after the exhibition ___ how successful it was.", "o": ["did we realise", "we realised", "realised we"], "a": 0}, {"q": "Which is correct?", "o": ["Into the gallery walked the minister.", "Into the gallery the minister walked in.", "Into walked the gallery the minister."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"I think this painting is ugly.\" — Best answer:", "o": ["Well, beauty is in the eye of the beholder.", "Beauty is a word.", "Paint it again!"], "a": 0}, {"q": "\"Is your book finished?\" — Best answer:", "o": ["Not yet — it's still a work in progress.", "Yes, it's a vibe.", "It's basic."], "a": 0}, {"q": "\"Who had the idea for the mural?\" — Best answer:", "o": ["Hamza came up with it.", "Hamza came up to it.", "Hamza took after it."], "a": 0}, {"q": "\"Did you enjoy the concert?\" — Best answer:", "o": ["Yes! The violinist stole the show.", "Yes, it was derivative.", "It was a flex."], "a": 0}, {"q": "\"Why do you love her music?\" — Best answer (slang):", "o": ["Because it slaps!", "Because it's basic.", "Because it's a flex."], "a": 0}, {"q": "\"You love modern art, don't you?\" — Best answer:", "o": ["Much as I love it, I prefer classical painting.", "Much I love it as.", "Such I love it."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["In 2011, the Arab Spring inspired a wave of street art across Cairo.", "Such was the energy of the period that artists painted entire streets in a matter of days.", "Many of the murals were later painted over by the authorities.", "Strange as it may seem, this made them even more famous, as photographs spread around the world online.", "Today, many of these images survive only in books and digital archives."], "qs": [{"q": "What inspired the wave of street art?", "o": ["the Arab Spring", "a football match", "a music festival"], "a": 0}, {"q": "How quickly did artists paint entire streets?", "o": ["in a matter of days", "over several years", "in one hour"], "a": 0}, {"q": "What happened to many murals?", "o": ["They were painted over.", "They were sold.", "They were moved to museums."], "a": 0}, {"q": "Why did they become more famous?", "o": ["Photographs spread online.", "They were on TV.", "Tourists bought them."], "a": 0}, {"q": "Where do many images survive today?", "o": ["in books and digital archives", "on the original walls", "nowhere"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write a review (100–150 words) of an exhibition, film, concert or work of art you loved. Use at least three fronting or emphasis structures (Such was…, So… that…, Strange as it may seem…, Little did I know…).", "promptAr": "اكتب ريفيو (١٠٠–١٥٠ كلمة) لمعرض أو فيلم أو حفلة أو عمل فني حبيته. استخدم ٣ تراكيب تقديم أو تأكيد على الأقل.", "checks": [["🎨", "Art words", "x", "\\b(art|artist|exhibition|gallery|painting|film|concert|music|masterpiece|creative|original|performance)\\b"], ["💥", "Such / So fronting", "x", "\\b(such was|such were|so \\w+ (was|were|is|are|did))\\b"], ["🔄", "Concession / Little did", "x", "\\b(\\w+ as (it|i|he|she|they|we) (may|might|was|were|am|is|are|tried|did)|much as|little did|only when|not until)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "HoXyw909Qu0", "title": "Who Decides What Art Means?", "ar": "مين اللي بيقرر معنى الفن؟ — TED-Ed", "by": "TED-Ed · Hayley Levitt", "lines": [["Two friends see the same striking painting: one sees love and stars, the other sees war and pollution.", "صاحبين بيشوفوا نفس اللوحة اللافتة: واحد شايف حب ونجوم، والتاني شايف حرب وتلوث."], ["Then they discover it is a replica of the artist's first-grade project: red was her favourite colour, and the dots were fairies.", "وبعدين بيكتشفوا إنها نسخة من مشروع الفنانة وهي في أولى ابتدائي: الأحمر كان لونها المفضل، والنقط كانت جنيّات."], ["So should the artist's intention change how we interpret a work? Philosophers and critics have debated this for decades with no consensus.", "طيب هل نية الفنان لازم تغير إزاي بنفسر العمل؟ الفلاسفة والنقاد بيتناقشوا في ده من عشرات السنين من غير اتفاق."], ["In the mid-20th century, two scholars called the idea that intentions matter \"the intentional fallacy\".", "في نص القرن العشرين، اتنين من العلماء سمّوا فكرة إن النية مهمة \"مغالطة النية\"."], ["Their first reason was practical: many artists are dead or never recorded what they meant.", "سببهم الأول كان عملي: فنانين كتير ماتوا أو عمرهم ما سجلوا كانوا يقصدوا إيه."], ["Their second reason was that searching for intentions distracts us from the work itself.", "وسببهم التاني إن التدوير على النية بيشتتنا عن العمل نفسه."], ["They compared art to a dessert: the chef's plans don't matter — only whether it tastes good.", "شبّهوا الفن بالحلويات: خطط الشيف مش مهمة — المهم طعمها حلو ولا لأ."], ["In this view, every viewer's interpretation is valid, and the artist's is just one among many.", "في الرأي ده، تفسير كل مشاهد صحيح، وتفسير الفنان مجرد واحد من كتير."], ["Other theorists strongly disagreed: they argued that a work only means what its creator intended.", "منظرين تانيين اعترضوا بقوة: قالوا إن العمل بيعني بس اللي صاحبه كان يقصده."], ["Their example: if waves accidentally formed the words of a poem in the sand, it wouldn't really be a poem, because nobody created it.", "مثالهم: لو الموج بالصدفة كوّن كلمات قصيدة على الرمل، مش هتبقى قصيدة بجد، لأن محدش عملها."], ["A middle position says intention matters in the same way it does in conversation — we try to understand what people mean, not just what they say.", "رأي وسط بيقول إن النية مهمة بنفس طريقتها في الكلام — إحنا بنحاول نفهم الناس يقصدوا إيه، مش بس بيقولوا إيه."], ["Artistic interpretation remains a complex web that will probably never have one definitive answer.", "تفسير الفن لسه شبكة معقدة غالبًا عمرها ما هيبقى ليها إجابة واحدة نهائية."]], "words": ["striking", "replica", "intention", "interpret", "consensus", "intentional fallacy", "practical", "distracts", "dessert", "interpretation", "theorists", "definitive"], "quiz": [{"q": "What did the painting turn out to be?", "o": ["a replica of the artist's first-grade project", "a famous masterpiece", "a photograph"], "a": 0}, {"q": "What is the \"intentional fallacy\"?", "o": ["the idea that the artist's intention should decide the meaning", "a type of paint", "a museum rule"], "a": 0}, {"q": "Why did the two scholars reject intentions?", "o": ["Artists may be dead, and intentions distract from the work.", "Artists always lie.", "Art has no meaning."], "a": 0}, {"q": "What was art compared to?", "o": ["a dessert", "a car", "a book"], "a": 0}, {"q": "What does the sand-poem example argue?", "o": ["Meaning needs a creator.", "Waves are artists.", "Poems are useless."], "a": 0}, {"q": "What is the final conclusion?", "o": ["Interpretation will probably never have one definitive answer.", "Only experts decide meaning.", "Artists always decide."], "a": 0}]}]}, "7": {"n": 7, "title": "Language, Identity and Belonging", "ar": "اللغة والهوية والانتماء — The Subjunctive", "icon": "🌍", "cover": "img/c1/u7.jpg", "intro": "اتكلم عن اللغة والهوية والانتماء والحياة بين ثقافتين ومستقبل اللغة العربية والإنجليزية، واستخدم صيغة الـ Subjunctive الرسمية: It's essential that he be… / I suggest she study… / It's high time we…", "videos": [{"id": "c1v7", "title": "Arabic or English?", "ar": "عربي ولا إنجليزي؟ — نور وياسين", "src": "video/c1/u7v1.mp4", "poster": "img/c1/u7v1.jpg", "sp": {"a": {"n": "Nour", "g": "f"}, "b": {"n": "Yassin", "g": "m"}}, "lines": [["a", "Yassin, my little nephew only speaks English with his friends now. He can barely write in Arabic.", "ياسين، ابن أختي الصغير بقى بيتكلم إنجليزي بس مع صحابه. وبالعافية بيكتب عربي."], ["b", "That's really common now, especially in international schools.", "ده منتشر جدًا دلوقتي، خصوصًا في المدارس الدولية."], ["a", "I know, but it worries me. My sister insists that he speak English at home too, so he gets better grades.", "عارفة، بس ده بيقلقني. أختي مصممة إنه يتكلم إنجليزي في البيت كمان، عشان ياخد درجات أحسن."], ["b", "I understand why. English opens doors. But I'd suggest that she keep Arabic as the home language.", "فاهم ليه. الإنجليزي بيفتح أبواب. بس أنا أقترح إنها تخلي العربي هو لغة البيت."], ["a", "Exactly. It's essential that children be able to talk to their grandparents, read our poetry, understand our jokes!", "بالظبط. ضروري إن الأطفال يقدروا يتكلموا مع أجدادهم، ويقروا شعرنا، ويفهموا نكتنا!"], ["b", "Language isn't just a tool. It's part of who you are. When I lived in London, I missed Arabic more than the food.", "اللغة مش مجرد أداة. هي جزء منك. لما كنت عايش في لندن، كنت مفتقد العربي أكتر من الأكل."], ["a", "Really? Did you feel like a different person speaking English?", "بجد؟ كنت حاسس إنك شخص تاني وإنت بتتكلم إنجليزي؟"], ["b", "A little. More polite, maybe! But I never felt I fully belonged. I was always between two worlds.", "شوية. أكتر أدب يمكن! بس عمري ما حسيت إني منتمي بالكامل. كنت دايمًا بين عالمين."], ["a", "That's the beauty and the difficulty of being bilingual.", "دي حلاوة وصعوبة إنك تتكلم لغتين."], ["b", "True. Honestly, it's high time schools treated Arabic as something exciting, not just grammar rules.", "صح. بصراحة، جه الوقت إن المدارس تتعامل مع العربي كحاجة ممتعة، مش قواعد نحو وبس."], ["a", "Agreed. I've proposed that my nephew join an Arabic storytelling club on Saturdays.", "موافقة. أنا اقترحت إن ابن أختي يشترك في نادي حكي بالعربي يوم السبت."], ["b", "Great idea. If he grows up loving both languages, he'll have two homes instead of none.", "فكرة حلوة. لو كبر وهو بيحب اللغتين، هيبقى عنده بيتين بدل ولا واحد."]], "quiz": [{"q": "What is Nour worried about?", "o": ["Her nephew can barely write in Arabic.", "Her nephew can't speak English.", "Her nephew failed his exams."], "a": 0}, {"q": "What does her sister insist on?", "o": ["that he speak English at home too", "that he move abroad", "that he stop studying"], "a": 0}, {"q": "What does Yassin suggest?", "o": ["keeping Arabic as the home language", "banning English", "changing schools"], "a": 0}, {"q": "How did Yassin feel in London?", "o": ["always between two worlds", "completely at home", "very angry"], "a": 0}, {"q": "What has Nour proposed for her nephew?", "o": ["an Arabic storytelling club", "an English summer camp", "a football club"], "a": 0}], "fill": [[0, "nephew"], [1, "international schools"], [2, "insists that he speak"], [3, "I'd suggest that she keep"], [4, "It's essential that children be"], [4, "grandparents"], [5, "part of who you are"], [7, "belonged"], [8, "bilingual"], [9, "it's high time schools treated"], [10, "proposed that my nephew join"], [11, "two homes"]]}], "vocab": [{"t": "Language", "ar": "اللغة", "items": [["🗣️", "mother tongue", "Arabic is my mother tongue."], ["🌐", "bilingual", "Bilingual children often switch languages."], ["🔀", "code-switching", "Code-switching between Arabic and English is common."], ["📜", "dialect", "Egyptian Arabic is a popular dialect."], ["🎙️", "accent", "She has a slight British accent."], ["🏛️", "official language", "Arabic is the official language of 22 countries."], ["🪦", "endangered language", "Hundreds of endangered languages may disappear."], ["🧑‍🏫", "fluency", "Fluency comes with practice."]]}, {"t": "Identity", "ar": "الهوية", "items": [["🪪", "identity", "Language is part of our identity."], ["🏠", "belonging", "He finally found a sense of belonging."], ["🧳", "expat", "Many expats live in Dubai."], ["🌍", "diaspora", "The Egyptian diaspora is large."], ["🔁", "assimilate", "Immigrants sometimes feel pressure to assimilate."], ["🎭", "stereotype", "Avoid stereotypes about other cultures."], ["🌉", "third culture kid", "Third culture kids grow up between countries."], ["🧬", "roots", "She went back to discover her roots."]]}, {"t": "Culture & society", "ar": "الثقافة والمجتمع", "items": [["🎎", "heritage", "We must protect our cultural heritage."], ["🔄", "preserve", "Communities try to preserve their language."], ["🌊", "globalised", "We live in a globalised world."], ["📉", "erode", "Local traditions are slowly eroding."], ["🤝", "tolerance", "Tolerance makes diverse societies work."], ["🌈", "multicultural", "London is a multicultural city."], ["🧭", "sense of self", "Travel changed his sense of self."], ["🗺️", "homesick", "I felt homesick during my first year abroad."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["How many languages do you speak? How do they make you feel?", "بتتكلم كام لغة؟ بيخلوك تحس بإيه؟", "Two — I feel more confident in English at work."], ["Do you ever mix Arabic and English when you speak?", "بتخلط عربي وإنجليزي وإنت بتتكلم؟", "All the time, especially with friends."], ["Have you ever felt homesick?", "حسيت بالحنين للبيت قبل كده؟", "Yes, on my first trip abroad."], ["What makes you feel that you belong somewhere?", "إيه اللي بيخليك تحس إنك منتمي لمكان؟", "People who know my name and my story."], ["Which part of your identity is most important to you?", "أنهي جزء من هويتك أهم بالنسبة لك؟", "My family and my language."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Should schools teach in English or in Arabic?", "المدارس تدرّس بالإنجليزي ولا بالعربي؟", "Both, but Arabic must not be neglected."], ["Is it important for immigrants to keep their mother tongue?", "مهم المهاجرين يحافظوا على لغتهم الأم؟", "Yes, it connects them to their roots."], ["Will English replace other languages one day?", "الإنجليزي هيحل محل لغات تانية في يوم؟", "I hope not — every language is a way of seeing the world."], ["Does your personality change when you speak English?", "شخصيتك بتتغير لما تتكلم إنجليزي؟", "I become more direct, I think."], ["Is it high time we changed how languages are taught?", "جه الوقت نغير طريقة تدريس اللغات؟", "Definitely — less memorising, more speaking."]]}], "grammar": {"title": "The Subjunctive", "ar": "صيغة الـ Subjunctive — It's essential that he be / I suggest she study / It's high time", "blocks": [{"type": "intro", "en": "The subjunctive is a formal structure used for demands, suggestions and necessity. Its main feature: the verb is in the BASE form for every subject (he be, she study, they go) — no -s, no past tense.", "ar": "الـ Subjunctive تركيب رسمي بنستخدمه للطلب والاقتراح والضرورة. أهم حاجة فيه: الفعل بيبقى في الصيغة الأساسية مع كل الفواعل (he be / she study) — من غير s ومن غير ماضي."}, {"type": "big", "items": [{"v": "suggest / insist / recommend / demand / propose + that + base verb", "p": "mandative subjunctive", "c": 1, "eg": ["My sister insists that he speak English at home.", "I'd suggest that she keep Arabic.", "The doctor recommended that he rest."]}, {"v": "It's essential / vital / important / crucial + that + base verb", "p": "necessity", "c": 2, "eg": ["It's essential that children be able to talk to their grandparents.", "It's vital that every student have a chance.", "It is crucial that she not be late."]}, {"v": "It's (high / about) time + subject + past simple", "p": "it's time (unreal past)", "c": 3, "eg": ["It's high time schools treated Arabic as exciting.", "It's about time you called your mother.", "It's time we left."]}]}, {"type": "table", "title": "📋 Subjunctive vs normal", "head": ["Normal (✖ in formal subjunctive)", "Subjunctive ✔"], "rows": [["She insists that he speaks English.", "She insists that he speak English."], ["It's essential that he is here.", "It's essential that he be here."], ["I suggest that she studies more.", "I suggest that she study more."], ["They demanded that he doesn't leave.", "They demanded that he not leave."], ["It's high time we change.", "It's high time we changed."]]}, {"type": "uses", "title": "💡 Fixed subjunctive expressions", "ar": "تعبيرات ثابتة", "items": [["🙏", "God save the King / Long live…", "Long live the King!", "تعبيرات قديمة"], ["🤷", "Be that as it may", "Be that as it may, we must decide.", "ومع ذلك"], ["📝", "Come what may", "Come what may, I'll support you.", "مهما حصل"], ["🙃", "If need be", "We can work late, if need be.", "لو لزم الأمر"]]}, {"type": "tip", "en": "In British English, 'should' is often used instead: I suggest that she should study. But NEVER add -s or use 'to': I suggest her to study ✖ → I suggest (that) she study ✔. The negative is 'not + base verb': that he not be late ✔.", "ar": "في الإنجليزي البريطاني ممكن نستخدم should. بس عمرك ما تقول I suggest her to study. والنفي not + الفعل: that he not be late."}]}, "exercises": [{"type": "mcq", "title": "The Subjunctive — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "My sister insists that he ___ English at home.", "o": ["speak", "speaks", "spoke", "to speak"], "a": 0}, {"q": "It's essential that children ___ able to talk to their grandparents.", "o": ["be", "are", "were", "being"], "a": 0}, {"q": "I'd suggest that she ___ Arabic as the home language.", "o": ["keep", "keeps", "kept", "to keep"], "a": 0}, {"q": "It's high time schools ___ Arabic as something exciting.", "o": ["treated", "treat", "treats", "treating"], "a": 0}, {"q": "The teacher recommended that he ___ more.", "o": ["read", "reads", "reading", "to read"], "a": 0}, {"q": "It is crucial that she ___ late for the interview.", "o": ["not be", "doesn't be", "isn't", "not is"], "a": 0}, {"q": "It's about time you ___ your grandmother.", "o": ["called", "call", "calls", "calling"], "a": 0}, {"q": "They demanded that the manager ___ immediately.", "o": ["resign", "resigns", "resigned", "to resign"], "a": 0}, {"q": "Which sentence is correct?", "o": ["I suggest that she study abroad.", "I suggest her to study abroad.", "I suggest that she studies abroad.", "I suggest she to study abroad."], "a": 0}, {"q": "\"Come what may\" means ___.", "o": ["whatever happens", "come here", "maybe later", "if possible"], "a": 0}]}, {"type": "mcq", "title": "Choose the form", "ar": "اختار الصيغة", "items": [{"q": "After \"insist that\", use the ___.", "o": ["base verb", "verb + s"], "a": 0}, {"q": "After \"It's high time\", use the ___.", "o": ["past simple", "base verb"], "a": 0}, {"q": "Negative subjunctive: that he ___ late", "o": ["not be", "doesn't be"], "a": 0}, {"q": "British alternative: I suggest that she ___ study.", "o": ["should", "would"], "a": 0}, {"q": "The subjunctive is ___.", "o": ["formal", "slang"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["She insists", "that he", "speak", "English"], "a": [0, 1, 2, 3]}, {"c": ["It's essential", "that she", "be", "on time"], "a": [0, 1, 2, 3]}, {"c": ["It's high time", "we", "changed", "the system"], "a": [0, 1, 2, 3]}, {"c": ["I suggest", "that he", "not", "leave"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "Do You Become a Different Person in Another Language?", "ar": "بتبقى شخص تاني في لغة تانية؟", "g": "f", "lines": [["Ask bilingual people whether they feel different when they switch languages, and many will say yes. Some feel more confident in English, more emotional in Arabic, or funnier in French.", "اسأل الناس اللي بيتكلموا لغتين إذا كانوا بيحسوا إنهم مختلفين لما يغيروا اللغة، وكتير هيقولوا أيوه. في ناس بيحسوا بثقة أكتر بالإنجليزي، وعاطفيين أكتر بالعربي، أو دمهم أخف بالفرنساوي."], ["Is this just imagination, or does language really shape who we are? Research suggests the answer is: a little of both.", "ده مجرد خيال، ولا اللغة فعلًا بتشكّل إحنا مين؟ الأبحاث بتقول الإجابة: شوية من الاتنين."], ["In one famous study, bilingual Mexican-Americans described themselves differently depending on the language of the questionnaire. In Spanish, they appeared more family-oriented; in English, more independent.", "في دراسة مشهورة، أمريكيين من أصل مكسيكي بيتكلموا لغتين وصفوا نفسهم بشكل مختلف على حسب لغة الاستبيان. بالإسباني، بانوا مرتبطين بالعيلة أكتر؛ وبالإنجليزي، مستقلين أكتر."], ["Part of the explanation is cultural. When we learn a language, we also absorb the values, humour and social rules of the people who speak it.", "جزء من التفسير ثقافي. لما بنتعلم لغة، بنمتص كمان القيم والنكت والقواعد الاجتماعية للناس اللي بيتكلموها."], ["Language also affects how we notice the world. Arabic, for example, has many words related to family relationships, while some Aboriginal languages use compass directions instead of \"left\" and \"right\".", "واللغة كمان بتأثر على إزاي بنلاحظ العالم. العربي مثلًا فيه كلمات كتير عن صلات القرابة، وبعض لغات السكان الأصليين في أستراليا بتستخدم الاتجاهات (شمال وجنوب) بدل \"يمين\" و\"شمال\"."], ["Interestingly, people often find it easier to discuss painful or embarrassing topics in a second language. The emotional distance makes difficult words feel less heavy.", "والمثير إن الناس غالبًا بيلاقوا أسهل يتكلموا في مواضيع مؤلمة أو محرجة بلغة تانية. المسافة العاطفية بتخلي الكلام الصعب أخف."], ["Conversely, swearing, praying and counting are usually done in the mother tongue — the language most deeply connected to our childhood and feelings.", "وبالعكس، الشتيمة والدعاء والعد غالبًا بيتعملوا باللغة الأم — اللغة اللي مرتبطة أكتر بطفولتنا ومشاعرنا."], ["For millions of people living between cultures, this can create a complex sense of identity. Many describe feeling \"too foreign\" in their new country and \"too different\" when they return home.", "لملايين الناس اللي عايشين بين ثقافتين، ده ممكن يعمل إحساس معقد بالهوية. كتير بيوصفوا إنهم حاسين إنهم \"أجانب أوي\" في بلدهم الجديدة و\"مختلفين أوي\" لما يرجعوا بلدهم."], ["Experts recommend that families raising bilingual children see this not as a problem but as a gift. It is essential that children feel proud of every language they speak.", "الخبراء بينصحوا إن العيلات اللي بتربي أطفال بلغتين تشوف ده مش كمشكلة لكن كهدية. ضروري إن الأطفال يحسوا بالفخر بكل لغة بيتكلموها."], ["After all, speaking two languages doesn't mean being half of two people. It means being a whole person with two windows onto the world.", "في الآخر، إنك تتكلم لغتين مش معناه إنك نص شخصين. معناه إنك شخص كامل عنده شباكين يطل منهم على العالم."]], "keys": [["📋", "questionnaire", "a list of questions people answer for research"], ["🏠", "family-oriented", "putting family first"], ["🧽", "absorb", "to take in and learn"], ["🧭", "compass directions", "north, south, east and west"], ["🔄", "conversely", "in the opposite way"], ["🪟", "window onto", "a way of seeing or understanding something"]], "quiz": [{"q": "What do many bilingual people say?", "o": ["They feel different in each language.", "They feel exactly the same.", "They forget one language."], "a": 0}, {"q": "How did Mexican-Americans appear in Spanish?", "o": ["more family-oriented", "more independent", "more angry"], "a": 0}, {"q": "Why do people find painful topics easier in a second language?", "o": ["There is more emotional distance.", "They know fewer words.", "It is more polite."], "a": 0}, {"q": "What is usually done in the mother tongue?", "o": ["swearing, praying and counting", "writing emails", "business meetings"], "a": 0}, {"q": "How do many people between cultures feel?", "o": ["\"too foreign\" abroad and \"too different\" at home", "completely at home everywhere", "only Egyptian"], "a": 0}, {"q": "What does the last paragraph say bilingualism means?", "o": ["being a whole person with two windows onto the world", "being half of two people", "being confused"], "a": 0}]}, "idioms": {"items": [["lost in translation", "When meaning is lost when changing languages.", "المعنى ضاع في الترجمة", "The joke got lost in translation.", "النكتة معناها ضاع في الترجمة."], ["a fish out of water", "Someone who feels uncomfortable in an unfamiliar place.", "زي السمكة برة المية", "In my first week abroad, I felt like a fish out of water.", "في أول أسبوع برة، كنت حاسس إني زي السمكة برة المية."], ["when in Rome (do as the Romans do)", "Follow the customs of the place you are in.", "اللي يروح بلد يمشي على عاداتها", "Everyone eats with their hands here — when in Rome!", "الكل بياكل بإيده هنا — اللي يروح بلد يمشي على عاداتها!"], ["speak the same language", "To share similar ideas and understand each other well.", "بيتكلموا نفس اللغة (متفاهمين)", "My new colleague and I really speak the same language.", "أنا وزميلي الجديد متفاهمين جدًا."]], "quiz": [{"q": "The poem is beautiful in Arabic, but some meaning is ___ in English.", "o": ["lost in translation", "a fish out of water", "when in Rome", "the same language"], "a": 0}, {"q": "At the formal dinner, I felt like ___.", "o": ["a fish out of water", "lost in translation", "speaking the same language", "a Roman"], "a": 0}, {"q": "\"When in Rome\" means…", "o": ["follow local customs", "visit Italy", "eat pasta", "speak Latin"], "a": 0}, {"q": "We agree on everything — we ___.", "o": ["speak the same language", "are lost in translation", "are fish out of water", "are in Rome"], "a": 0}]}, "phrasal": {"items": [["fit in", "To be accepted as part of a group.", "يندمج / يتأقلم مع", "It took me a year to fit in at my new school.", "خدت سنة على ما اندمجت في مدرستي الجديدة."], ["pick up", "To learn a language or skill informally.", "يلقط (لغة)", "Children pick up languages very quickly.", "الأطفال بيلقطوا اللغات بسرعة جدًا."], ["hold on to", "To keep something and not lose it.", "يتمسك بـ", "Hold on to your traditions.", "اتمسك بعاداتك."], ["look down on", "To think you are better than someone.", "يبص لحد من فوق", "Never look down on someone's accent.", "عمرك ما تبص من فوق للهجة حد."]], "quiz": [{"q": "She ___ some Spanish while living in Madrid.", "o": ["picked up", "looked down on", "held on to", "fitted in"], "a": 0}, {"q": "Many immigrant families try to ___ their language.", "o": ["hold on to", "pick up", "look down on", "fit in"], "a": 0}, {"q": "It's wrong to ___ people who speak with a different accent.", "o": ["look down on", "hold on to", "pick up", "fit in"], "a": 0}, {"q": "At first, he didn't ___, but now he has lots of friends.", "o": ["fit in", "pick up", "look down", "hold on"], "a": 0}]}, "slang": {"items": [["Franco-Arab / Arabizi", "Writing Arabic with English letters and numbers (3, 7…).", "فرانكو", "My little brother texts me in Arabizi: \"7abibi 3amel eh?\"", "أخويا الصغير بيبعتلي فرانكو: \"حبيبي عامل إيه؟\"", "مصطلح معروف"], ["my people", "People from the same background or who share your interests.", "ناسي / جماعتي", "Found a café full of Egyptians in Berlin — my people!", "لقيت كافيه مليان مصريين في برلين — ناسي!", "لطيفة"], ["lowkey / highkey", "Slightly, secretly / very, openly.", "شوية في السر / جدًا وعلى الملأ", "I lowkey miss my mum's cooking. Highkey, actually!", "أنا مفتقد أكل ماما شوية. لأ جدًا بصراحة!", "منتشرة جدًا"], ["culture shock", "Confusion when experiencing a new culture.", "صدمة ثقافية", "Queuing silently was a real culture shock for me.", "الوقوف في طابور في صمت كان صدمة ثقافية بالنسبة لي.", "عادي"], ["homie", "A close friend (informal).", "صاحبي الأنتيم", "He's my homie from school.", "ده صاحبي الأنتيم من المدرسة.", "سلانج أمريكي"]], "quiz": [{"q": "Writing \"3amel eh\" uses ___.", "o": ["Arabizi", "highkey", "homie", "culture shock"], "a": 0}, {"q": "\"I lowkey love this song.\" means…", "o": ["I secretly / slightly love it", "I hate it", "I love it loudly", "I don't know it"], "a": 0}, {"q": "Feeling confused by a new culture = ___.", "o": ["culture shock", "my people", "homie", "lowkey"], "a": 0}, {"q": "\"My people!\" is used when you meet people who…", "o": ["share your background or interests", "are your employees", "are strangers", "are angry"], "a": 0}]}, "story": {"title": "Two Names", "ar": "اسمين", "g": "m", "lines": [["At home in Manchester, she was Fatma. At school, she became \"Fay\". It was easier, she told herself — teachers couldn't pronounce her real name, and Fay sounded like everyone else.", "في البيت في مانشستر، كانت فاطمة. في المدرسة، بقت \"فاي\". قالت لنفسها إن ده أسهل — المدرسين مكانوش بيعرفوا ينطقوا اسمها الحقيقي، وفاي كان شبه أسامي كل الناس."], ["Fay spoke perfect English, loved British comedy and fitted in easily. Fatma spoke Arabic with her parents, but less and less every year.", "فاي كانت بتتكلم إنجليزي ممتاز، وبتحب الكوميديا البريطاني، واندمجت بسهولة. وفاطمة كانت بتتكلم عربي مع أهلها، بس أقل وأقل كل سنة."], ["When she was seventeen, her grandmother came from Egypt to stay with them. Teta Zeinab spoke no English at all.", "لما بقى عندها ١٧ سنة، جدتها جت من مصر تقعد معاهم. تيتة زينب مكانتش بتعرف إنجليزي خالص."], ["On the first evening, Teta told a long story about Fatma's great-grandfather. Everyone laughed — except Fatma, who had understood only half of it.", "أول ليلة، تيتة حكت قصة طويلة عن جد جد فاطمة. الكل ضحك — إلا فاطمة، اللي فهمت نصها بس."], ["She felt like a fish out of water in her own home. For the first time, Fay felt ashamed of what Fatma had lost.", "حست إنها زي السمكة برة المية في بيتها. ولأول مرة، فاي اتكسفت من اللي فاطمة خسرته."], ["\"Teach me,\" she said to her grandmother the next morning. Teta Zeinab didn't answer. She simply opened an old notebook full of songs, proverbs and recipes, all written in her careful handwriting.", "\"علّميني،\" قالت لجدتها تاني يوم الصبح. تيتة زينب مردتش. فتحت بس كشكول قديم مليان أغاني وأمثال ووصفات، كلها مكتوبة بخطها الحريص."], ["Every evening for three months, they sat together. Fatma read aloud, made mistakes and laughed. Slowly, she picked up words she had forgotten and many she had never known.", "كل ليلة لمدة ٣ شهور، قعدوا مع بعض. فاطمة قرت بصوت عالي، وغلطت، وضحكت. شوية بشوية، لقطت كلمات كانت نسيتها وكلمات كتير عمرها ما عرفتها."], ["When Teta left, she insisted that Fatma keep the notebook. \"A language is a house,\" she said. \"If you don't live in it, it falls down.\"", "لما تيتة مشيت، أصرّت إن فاطمة تحتفظ بالكشكول. \"اللغة زي البيت،\" قالت. \"لو معشتيش فيه، بيقع.\""], ["The next term, when a new teacher called the register, she paused at the name \"Fay\". \"Actually,\" the girl said, \"it's Fatma.\"", "الترم اللي بعده، لما مدرسة جديدة نادت الأسامي، وقفت عند اسم \"فاي\". \"في الحقيقة،\" البنت قالت، \"اسمي فاطمة.\""], ["The teacher repeated it carefully, twice, until she got it right. Fatma smiled. It was high time someone did.", "المدرسة كررته بحرص، مرتين، لحد ما نطقته صح. فاطمة ابتسمت. كان جه الوقت إن حد يعمل كده."]], "quiz": [{"q": "Why did Fatma call herself \"Fay\" at school?", "o": ["Teachers couldn't pronounce her name and Fay sounded like everyone else.", "Her parents chose it.", "She hated her name."], "a": 0}, {"q": "Who came to stay with the family?", "o": ["her grandmother from Egypt", "her cousin from London", "her teacher"], "a": 0}, {"q": "Why didn't Fatma laugh at the story?", "o": ["She understood only half of it.", "It wasn't funny.", "She was tired."], "a": 0}, {"q": "What was in Teta's notebook?", "o": ["songs, proverbs and recipes", "English grammar", "photos"], "a": 0}, {"q": "What did Teta say a language is like?", "o": ["a house that falls down if you don't live in it", "a tool", "a game"], "a": 0}]}, "challenge": {"title": "Who Am I?", "ar": "أنا مين؟ — جاوب وسجّل", "qs": ["How does speaking English change the way you think or behave?", "Is it important to keep your mother tongue if you move abroad? Why?", "What would you insist that every school teach? Use the subjunctive.", "Describe a time you felt like a fish out of water.", "Will Arabic be stronger or weaker in 50 years? What should be done?", "Should children in Egypt learn in English from primary school?", "Is it high time we changed how languages are taught? Explain.", "What do you think is lost when an endangered language disappears?", "Have you ever experienced culture shock? Describe it.", "What makes you feel you belong — a place, a language, or people?"]}, "games": {"pairs": [["🗣️", "mother tongue"], ["🌐", "bilingual"], ["📜", "dialect"], ["🎙️", "accent"], ["🏠", "belonging"], ["🌍", "diaspora"]], "spell": [["🪪", "identity"], ["🔁", "assimilate"], ["🧬", "roots"], ["🔄", "preserve"], ["📉", "erode"], ["🤝", "tolerance"], ["🌈", "multicultural"], ["🗺️", "homesick"]], "speed": [["She insists that he speak English.", true], ["She insists that he speaks English.", false], ["It's essential that she be on time.", true], ["I suggest her to study abroad.", false], ["It's high time we changed the system.", true], ["It's high time we change the system.", false], ["They demanded that he not leave.", true], ["The doctor recommended that he rest.", true], ["Come what may, I'll support you.", true], ["If need be, we can work late.", true], ["Bilingual means speaking one language.", false], ["A dialect is a local form of a language.", true], ["\"Lost in translation\" means meaning was lost.", true], ["\"Pick up\" a language means to learn it informally.", true], ["\"Look down on\" means to respect.", false], ["\"Culture shock\" is confusion in a new culture.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "The first language you learned = your ___.", "o": ["mother tongue", "dialect", "accent"], "a": 0, "pic": "🗣️"}, {"q": "Able to speak two languages = ___.", "o": ["bilingual", "multicultural", "homesick"], "a": 0, "pic": "🌐"}, {"q": "Switching between languages while speaking = ___.", "o": ["code-switching", "assimilating", "eroding"], "a": 0, "pic": "🔀"}, {"q": "People from one country living around the world = the ___.", "o": ["diaspora", "heritage", "roots"], "a": 0, "pic": "🌍"}, {"q": "Missing your home and family = ___.", "o": ["homesick", "tolerant", "fluent"], "a": 0, "pic": "🗺️"}, {"q": "\"الانتماء\" in English is…", "o": ["belonging", "believing", "behaving"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "The manager insisted that everyone ___ on time.", "o": ["be", "is", "was"], "a": 0}, {"q": "It's vital that he ___ the truth.", "o": ["know", "knows", "knew"], "a": 0}, {"q": "It's high time you ___ to bed.", "o": ["went", "go", "going"], "a": 0}, {"q": "I recommend that she ___ a language course.", "o": ["take", "takes", "to take"], "a": 0}, {"q": "They asked that the meeting ___ postponed.", "o": ["be", "is", "was"], "a": 0}, {"q": "Which is correct?", "o": ["It is crucial that he not miss the exam.", "It is crucial that he doesn't misses the exam.", "It is crucial that he not misses the exam."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"How did you feel in your first week abroad?\" — Best answer:", "o": ["Like a fish out of water!", "Like a Roman.", "Lost in a dialect."], "a": 0}, {"q": "\"Why didn't they laugh at your joke?\" — Best answer:", "o": ["I think it got lost in translation.", "They were a fish.", "When in Rome."], "a": 0}, {"q": "\"What would you suggest?\" — Best answer (formal):", "o": ["I would suggest that he take an Arabic course.", "I suggest him to take a course.", "I suggest he takes to course."], "a": 0}, {"q": "\"Everyone here eats dinner at 10 p.m.\" — Best answer:", "o": ["Well, when in Rome!", "Lost in translation!", "Arabizi!"], "a": 0}, {"q": "\"How did you learn Spanish?\" — Best answer:", "o": ["I picked it up while living in Spain.", "I looked down on it.", "I held on Spain."], "a": 0}, {"q": "\"You haven't called your grandmother for weeks.\" — Best answer:", "o": ["You're right. It's high time I called her.", "It's high time I call her.", "It's time I calling her."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["Of the world's 7,000 languages, around 40% are considered endangered.", "Many have fewer than a thousand speakers, most of whom are elderly.", "When the last speaker dies, songs, stories and knowledge about nature can disappear forever.", "Linguists insist that communities be supported in teaching their languages to children.", "Some apps and online dictionaries are now helping young people hold on to the languages of their grandparents."], "qs": [{"q": "How many languages are there in the world?", "o": ["about 7,000", "about 700", "about 70,000"], "a": 0}, {"q": "What percentage are endangered?", "o": ["around 40%", "around 4%", "around 90%"], "a": 0}, {"q": "Who are most speakers of endangered languages?", "o": ["elderly people", "children", "teachers"], "a": 0}, {"q": "What do linguists insist on?", "o": ["that communities be supported in teaching children", "that all languages be replaced", "that only English be taught"], "a": 0}, {"q": "What is helping young people now?", "o": ["apps and online dictionaries", "television only", "nothing"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write a formal letter (100–150 words) to the Minister of Education with recommendations on how to protect Arabic while improving English teaching. Use the subjunctive at least three times (I recommend that…, It is essential that…, It is high time…).", "promptAr": "اكتب جواب رسمي (١٠٠–١٥٠ كلمة) لوزير التعليم بتوصيات تحمي العربي وتحسّن تدريس الإنجليزي. استخدم الـ Subjunctive ٣ مرات على الأقل.", "checks": [["🌍", "Language words", "x", "\\b(arabic|english|language|languages|identity|culture|students|bilingual|mother tongue|heritage|schools?)\\b"], ["📜", "Subjunctive", "x", "\\b(recommend|suggest|insist|propose|demand|essential|vital|crucial|important)\\s+that\\s+\\w+\\s+(be|not|have|learn|study|teach|keep|read|speak|use|receive|include|protect|spend|offer)\\b"], ["⏰", "It's high time", "x", "\\b(it is|it's) (high |about )?time\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "MMmOLN5zBLY", "title": "The Benefits of a Bilingual Brain", "ar": "فوايد المخ ثنائي اللغة — TED-Ed", "by": "TED-Ed · Mia Nacamulli", "lines": [["Knowing more than one language makes travelling and watching films easier — but does it also change the brain?", "معرفة أكتر من لغة بتسهّل السفر والتفرج على الأفلام — بس هل كمان بتغير المخ؟"], ["Language ability is measured in four skills: speaking and writing are active; listening and reading are passive.", "القدرة اللغوية بتتقاس في ٤ مهارات: الكلام والكتابة نشطين؛ والاستماع والقراءة سلبيين."], ["There are three general types of bilinguals: compound, coordinate and subordinate.", "في ٣ أنواع عامة للي بيتكلموا لغتين: المركّب، والمتوازي، والتابع."], ["Compound bilinguals learn two languages at the same time, often as children, with one set of concepts.", "المركّب بيتعلم لغتين في نفس الوقت، غالبًا وهو طفل، بمجموعة مفاهيم واحدة."], ["Coordinate bilinguals work with two separate sets of concepts, for example one language at home and another at school.", "المتوازي بيشتغل بمجموعتين منفصلتين من المفاهيم، مثلًا لغة في البيت ولغة في المدرسة."], ["Subordinate bilinguals learn a second language through their first language.", "التابع بيتعلم اللغة التانية من خلال لغته الأولى."], ["Brain imaging shows that children tend to use both hemispheres for language, while adults use mainly the left.", "تصوير المخ بيوضح إن الأطفال غالبًا بيستخدموا النصين بتوع المخ للغة، والكبار بيستخدموا الشمال أساسًا."], ["Children's brains are more flexible, which may help them understand the social and emotional context of a language.", "مخ الأطفال أمرن، وده ممكن يساعدهم يفهموا السياق الاجتماعي والعاطفي للغة."], ["Adults who learn a second language may approach it in a more rational, less emotional way.", "الكبار اللي بيتعلموا لغة تانية ممكن يتعاملوا معاها بطريقة عقلانية أكتر وعاطفية أقل."], ["Bilingual brains show higher density of grey matter and more activity in certain regions.", "المخ ثنائي اللغة بيبان فيه كثافة أعلى في المادة الرمادية ونشاط أكتر في مناطق معينة."], ["This lifelong mental workout may delay the onset of Alzheimer's and dementia by up to five years.", "التمرين الذهني ده طول العمر ممكن يأخر ظهور الزهايمر والخرف لحد ٥ سنين."], ["Bilingualism was once wrongly seen as a handicap, but research now shows clear benefits — and it is never too late to start.", "ازدواجية اللغة كانت زمان بتتشاف غلط كعائق، بس الأبحاث دلوقتي بتوضح فوايد واضحة — وعمره ما بيبقى متأخر إنك تبدأ."]], "words": ["bilingual", "active", "passive", "compound", "coordinate", "subordinate", "hemispheres", "flexible", "rational", "grey matter", "dementia", "handicap"], "quiz": [{"q": "Which language skills are \"active\"?", "o": ["speaking and writing", "listening and reading", "reading and writing"], "a": 0}, {"q": "How many general types of bilinguals are there?", "o": ["three", "two", "five"], "a": 0}, {"q": "Which type learns a second language through the first?", "o": ["subordinate", "compound", "coordinate"], "a": 0}, {"q": "Which hemispheres do children tend to use for language?", "o": ["both", "only the left", "only the right"], "a": 0}, {"q": "What may bilingualism delay?", "o": ["Alzheimer's and dementia", "puberty", "ageing of the skin"], "a": 0}, {"q": "How was bilingualism once seen?", "o": ["as a handicap", "as a superpower", "as illegal"], "a": 0}]}]}}, "final": {"pass": 60, "sections": [{"id": "lis", "title": "Listening", "ar": "الاستماع", "icon": "🎧", "listen": true, "qs": [{"audio": "Some jobs are bound to disappear, but new ones are set to appear as companies adopt AI.", "g": "m", "q": "What does the speaker say about jobs?", "o": ["Some will disappear and new ones will appear.", "All jobs will disappear.", "Nothing will change."], "a": 0}, {"audio": "Is he feeling better? I think so. He was going to see a therapist, and finally he did.", "g": "f", "q": "What did he finally do?", "o": ["He saw a therapist.", "He changed jobs.", "He moved abroad."], "a": 0}, {"audio": "The neighbourhood in which I grew up has changed completely, most of the old houses having been pulled down.", "g": "f2", "q": "What happened to most of the old houses?", "o": ["They were pulled down.", "They were painted.", "They became museums."], "a": 0}, {"audio": "Had the scientists tested the drug properly, the side effects would have been discovered earlier.", "g": "m2", "q": "What would have happened if the drug had been tested properly?", "o": ["The side effects would have been discovered earlier.", "The drug would have been cheaper.", "Nobody would have used it."], "a": 0}, {"audio": "Admittedly, the video looked real. Nonetheless, a reverse image search showed it was ten years old.", "g": "f", "q": "What did the reverse image search show?", "o": ["The video was ten years old.", "The video was new.", "The video was fake from AI."], "a": 0}, {"audio": "So detailed were her paintings that visitors thought they were photographs.", "g": "m", "q": "What did visitors think about her paintings?", "o": ["They thought they were photographs.", "They thought they were ugly.", "They thought they were stolen."], "a": 0}, {"audio": "It's essential that children be proud of every language they speak, and it's high time schools encouraged them.", "g": "f2", "q": "What does the speaker say schools should do?", "o": ["encourage children to be proud of their languages", "teach only English", "stop language lessons"], "a": 0}, {"audio": "Strange as it may seem, the official left without removing the mural, and a month later the artist was invited to paint twenty more walls.", "g": "m2", "q": "What happened a month later?", "o": ["The artist was invited to paint twenty more walls.", "The mural was removed.", "The artist was arrested."], "a": 0}]}, {"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "No longer useful or needed = ___.", "o": ["obsolete", "resilient", "credible"], "a": 0, "pic": "📉"}, {"q": "Shame linked to something (e.g. mental illness) = ___.", "o": ["stigma", "heritage", "bias"], "a": 0, "pic": "🚫"}, {"q": "Rising prices pushing poorer residents out = ___.", "o": ["gentrification", "regeneration", "congestion"], "a": 0, "pic": "📈"}, {"q": "Agreement after understanding all the risks = informed ___.", "o": ["consent", "evidence", "cure"], "a": 0, "pic": "🤝"}, {"q": "To prove that a claim is false = to ___.", "o": ["debunk", "verify", "preserve"], "a": 0, "pic": "🚨"}, {"q": "Copying others, not original = ___.", "o": ["derivative", "innovative", "acclaimed"], "a": 0, "pic": "🔁"}, {"q": "Able to speak two languages = ___.", "o": ["bilingual", "multicultural", "fluent"], "a": 0, "pic": "🌐"}, {"q": "\"A double-edged sword\" means something that…", "o": ["has both good and bad effects", "is very sharp", "is dangerous only", "is very old"], "a": 0, "pic": "⚔️"}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "The company is ___ to launch its new product in May.", "o": ["set", "verge", "point"], "a": 0}, {"q": "\"Will it rain tomorrow?\" — \"I hope ___.\"", "o": ["not", "no", "don't"], "a": 0}, {"q": "I have three sisters, all of ___ are doctors.", "o": ["whom", "them", "who"], "a": 0}, {"q": "___ I known, I would have told you.", "o": ["Had", "Have", "Were"], "a": 0}, {"q": "The trial was well designed. ___, the results were disappointing.", "o": ["Nonetheless", "Consequently", "Admittedly"], "a": 0}, {"q": "___ was the noise that nobody could sleep.", "o": ["Such", "So", "Too"], "a": 0}, {"q": "The teacher insisted that he ___ the essay again.", "o": ["write", "writes", "wrote"], "a": 0}, {"q": "It's high time you ___ a decision.", "o": ["made", "make", "making"], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["In 2024, a small town in the Netherlands became one of the first in Europe to ban smartphones in all its primary and secondary schools.", "Admittedly, many parents were sceptical at first. Some insisted that their children be allowed to carry phones for safety reasons.", "Within a year, however, teachers reported that students were concentrating better, talking more during breaks and suffering less from anxiety.", "Such was the success of the experiment that the national government is now set to introduce a similar policy across the country.", "Had the town not taken the first step, experts say, the debate might have continued for years."], "qs": [{"q": "What did the town ban?", "o": ["smartphones in schools", "cars in the centre", "social media"], "a": 0}, {"q": "How did many parents react at first?", "o": ["They were sceptical.", "They celebrated.", "They didn't care."], "a": 0}, {"q": "What did teachers report within a year?", "o": ["better concentration and less anxiety", "more fights", "lower grades"], "a": 0}, {"q": "What is the national government set to do?", "o": ["introduce a similar policy", "cancel the ban", "buy phones for students"], "a": 0}, {"q": "What might have happened had the town not acted?", "o": ["The debate might have continued for years.", "Phones would be cheaper.", "Schools would close."], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write an essay (150–200 words): \"Technology is making us less human.\" Discuss both sides and give your opinion. Use at least five C1 grammar structures (advanced future forms, ellipsis, advanced relatives, conditional inversion, discourse markers, fronting, subjunctive).", "promptAr": "اكتب مقال (١٥٠–٢٠٠ كلمة): \"التكنولوجيا بتخلينا أقل إنسانية.\" ناقش الرأيين وقول رأيك، واستخدم ٥ تراكيب على الأقل من قواعد C1.", "checks": [["🔮", "Future / inversion", "x", "\\b(bound to|on the verge of|set to|due to|about to)\\b|(^|[.!?]\\s+)(had|were|should)\\s+\\w+\\s+\\w+"], ["🔗", "Relatives", "x", "\\b(in which|of which|of whom|whereby|by which time|to whom)\\b"], ["🧭", "Discourse markers", "x", "\\b(admittedly|nonetheless|be that as it may|not to mention|consequently|in light of|granted)\\b"], ["💥", "Fronting / subjunctive", "x", "\\b(such was|so \\w+ (was|were)|as it may seem|little did|(essential|vital|crucial|insist|suggest|recommend) that \\w+ (be|not)|high time)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "cert": "C1 – Advanced Level", "home": "<span dir=\"rtl\" style=\"display:block\">مستوى <bdi dir=\"ltr\">C1</bdi> — اتكلم زي المحترفين عن الذكاء الاصطناعي والصحة النفسية ومدن المستقبل والعلم والأخلاق والإعلام والفن واللغة والهوية، ومعاهم Idioms وPhrasal Verbs وSlang وقصص مع Wisy.</span>", "sub": "Advanced", "spr": 80, "ch": "img/char-wisy.png"};
